    private void payDueDate(String id, String treasuryCode, LocalDate date, String method, Runnable after) {
        Task<com.benjagest.ui.model.DueDateEntry> tk = new Task<>() {
            @Override protected com.benjagest.ui.model.DueDateEntry call() throws Exception {
                return dueDateApi.pay(id, treasuryCode, date, method);
            }
        };
        tk.setOnSucceeded(e -> { after.run(); com.benjagest.ui.support.RefreshBus.emit(
                com.benjagest.ui.support.RefreshBus.TOPIC_JOURNAL); });
        tk.setOnFailed(e -> showError(t("duedates.fail"), msgOf(tk.getException())));
        start(tk, "due-dates-pay");
    }

    /** Editor del cuadro de vencimientos: filas (fecha + importe). */
    private void openEditSchedule(String kind, String invoiceId,
                                   java.math.BigDecimal total, Runnable after) {
        javafx.scene.control.Dialog<ButtonType> dlg = new javafx.scene.control.Dialog<>();
        dlg.setResizable(true);
        dlg.setTitle(t("duedates.edit.title"));
        ButtonType saveBt = new ButtonType(t("duedates.edit.save"),
                javafx.scene.control.ButtonBar.ButtonData.OK_DONE);
        dlg.getDialogPane().getButtonTypes().addAll(saveBt, ButtonType.CANCEL);

        ObservableList<DueRow> rows = FXCollections.observableArrayList();
        rows.add(new DueRow(LocalDate.now().format(DD_FMT), total == null ? "" : total.toPlainString()));

        TableView<DueRow> tbl = new TableView<>(rows);
        tbl.setEditable(true);
        tbl.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY);
        tbl.setPrefHeight(220);
        TableColumn<DueRow, String> colDate = new TableColumn<>(t("duedates.col.due"));
        colDate.setCellValueFactory(c -> c.getValue().date);
        colDate.setCellFactory(javafx.scene.control.cell.TextFieldTableCell.forTableColumn());
        colDate.setOnEditCommit(ev -> ev.getRowValue().date.set(ev.getNewValue()));
        TableColumn<DueRow, String> colAmt = new TableColumn<>(t("duedates.col.amount"));
        colAmt.setCellValueFactory(c -> c.getValue().amount);
        colAmt.setCellFactory(javafx.scene.control.cell.TextFieldTableCell.forTableColumn());
        colAmt.setOnEditCommit(ev -> ev.getRowValue().amount.set(ev.getNewValue()));
        tbl.getColumns().setAll(java.util.List.of(colDate, colAmt));

        Button add = new Button(t("duedates.edit.add"));
        add.setOnAction(e -> rows.add(new DueRow(LocalDate.now().format(DD_FMT), "")));
        Button rem = new Button(t("duedates.edit.remove"));
        rem.setOnAction(e -> { DueRow s = tbl.getSelectionModel().getSelectedItem(); if (s != null) rows.remove(s); });
        Label hint = new Label(t("duedates.edit.hint").replace("{t}", eur(total)));
        hint.setWrapText(true); hint.getStyleClass().add("settings-hint");

        VBox box = new VBox(10, hint, new HBox(8, add, rem), tbl);
        box.setPadding(new Insets(12));
        VBox.setVgrow(tbl, Priority.ALWAYS);
        dlg.getDialogPane().setContent(box);
        dlg.getDialogPane().setPrefSize(540, 420);

        dlg.showAndWait().ifPresent(bt -> {
            if (bt != saveBt) return;
            java.util.List<com.benjagest.ui.service.DueDateApiClient.DueDateReq> reqs = new java.util.ArrayList<>();
            for (DueRow r : rows) {
                LocalDate d = com.benjagest.ui.support.EditableCells.parseFlexibleDate(r.date.get());
                java.math.BigDecimal amt;
                try { amt = new java.math.BigDecimal(r.amount.get().replace(',', '.').trim()); }
                catch (Exception ex) { amt = null; }
                reqs.add(new com.benjagest.ui.service.DueDateApiClient.DueDateReq(d, amt, null));
            }
            Task<java.util.List<com.benjagest.ui.model.DueDateEntry>> tk = new Task<>() {
                @Override protected java.util.List<com.benjagest.ui.model.DueDateEntry> call() throws Exception {
                    return dueDateApi.replace(kind, invoiceId, reqs);
                }
            };
            tk.setOnSucceeded(e -> after.run());
            tk.setOnFailed(e -> showError(t("duedates.fail"), msgOf(tk.getException())));
            start(tk, "due-dates-replace");
        });
    }

    private static final DateTimeFormatter DD_FMT = DateTimeFormatter.ofPattern("dd-MM-yyyy");

    /** Holder editable de una fila del cuadro de vencimientos. */
    private static class DueRow {
        final javafx.beans.property.SimpleStringProperty date;
        final javafx.beans.property.SimpleStringProperty amount;
        DueRow(String d, String a) {
            this.date = new javafx.beans.property.SimpleStringProperty(d);
            this.amount = new javafx.beans.property.SimpleStringProperty(a);
        }
    }

    private javafx.scene.control.ListCell<String> treasuryCell() {
        return new javafx.scene.control.ListCell<>() {
            @Override protected void updateItem(String item, boolean empty) {
                super.updateItem(item, empty);
                if (empty || item == null) { setText(null); return; }
                setText("572".equals(item) ? t("duedates.pay.bank") : t("duedates.pay.cash"));
            }
        };
    }

    private javafx.scene.control.ListCell<String> methodCell() {
        return new javafx.scene.control.ListCell<>() {
            @Override protected void updateItem(String item, boolean empty) {
                super.updateItem(item, empty);
                setText(empty || item == null ? null : t("duedates.method." + item));
            }
        };
    }

    private String msgOf(Throwable ex) {
        if (ex == null) return "";
        String m = ex.getMessage() == null ? ex.toString() : ex.getMessage();
        int i = m.indexOf("\"message\":\"");
        if (i >= 0) { int s = i + 11; int e = m.indexOf('"', s); if (e > s) return m.substring(s, e); }
        return m;
    }

    private String eur(java.math.BigDecimal v) {
        return CURRENCY_FORMAT.format(v == null ? java.math.BigDecimal.ZERO : v);
    }

    private void importPurchasePdf() {
        javafx.stage.FileChooser chooser = new javafx.stage.FileChooser();
        chooser.setTitle(t("purchases.import.select_pdf"));
        chooser.getExtensionFilters().add(
                new javafx.stage.FileChooser.ExtensionFilter("PDF", "*.pdf"));
        java.io.File file = chooser.showOpenDialog(root.getScene().getWindow());
        if (file == null) return;
        processSinglePurchasePdf(file, null);
    }

    /**
     * Multi-importación: FileChooser multi-select → cada PDF se procesa
     * en secuencia mostrando el diálogo de revisión con visor PDF
     * embebido. El asesor revisa/edita y guarda uno tras otro. Esto
     * mismo, hecho a mano con 30 PDFs de un trimestre, son ~15 minutos
     * de clicks; aquí queda en 2-3 minutos.
     */
    /**
     * Slice 2C — Importación con auto-detección venta/gasto.
     *
     * <p>Para cada PDF seleccionado:
     * <ol>
     *   <li>Lo extrae vía {@code pdfImportApi.uploadAndExtract}.</li>
     *   <li>Lee el campo {@code emitterNif} del primer objeto del array
     *       de extracciones.</li>
     *   <li>Si el emisor coincide con {@code selfTaxId} (NIF de la
     *       empresa del cliente actual) → es una VENTA que el cliente
     *       emitió → flujo de venta ({@link #showSalesExtractionDialog}).</li>
     *   <li>Si no coincide → es un GASTO recibido → flujo de gasto
     *       ({@link #processSinglePurchasePdf}).</li>
     * </ol>
     *
     * <p>Si {@code selfTaxId} viene vacío, todos los PDFs se asumen
     * gastos como antes. La normalización descarta espacios y
     * convierte a mayúsculas para que "24259998 N" vs "24259998N"
     * comparen igual.
     */
    private void importPdfsAuto(String selfTaxId) {
        javafx.stage.FileChooser chooser = new javafx.stage.FileChooser();
        chooser.setTitle(t("client.action.import_pdfs_auto"));
        chooser.getExtensionFilters().add(
                new javafx.stage.FileChooser.ExtensionFilter("PDF", "*.pdf"));
        java.util.List<java.io.File> files = chooser.showOpenMultipleDialog(
                root.getScene().getWindow());
        if (files == null || files.isEmpty()) return;

        String selfNorm = normalizeNifLite(selfTaxId);
        int total = files.size();
        int salesCount = 0, expensesCount = 0;

        for (int i = 0; i < total; i++) {
            java.io.File f = files.get(i);
            String progress = "  (" + (i + 1) + "/" + total + ")";

            byte[] pdfBytes;
            try {
                pdfBytes = java.nio.file.Files.readAllBytes(f.toPath());
            } catch (Exception ex) {
                showError(t("purchases.import.fail.title"),
                        t("purchases.import.fail.body"));
                continue;
            }
            String json;
            try {
                json = pdfImportApi.uploadAndExtract(f);
            } catch (Exception ex) {
                showError(t("purchases.import.fail.title"),
                        t("purchases.import.fail.body"));
                continue;
            }
            java.util.List<String> invoices = splitJsonArrayObjects(json);
            if (invoices.isEmpty()) continue;

            // Decisión por PDF (no por factura). Si el PDF tiene varias
            // facturas dentro, asumimos que comparten emisor.
            String first = invoices.get(0);
            String emitterNif = extractField(first, "emitterNif");
            String emitterNorm = normalizeNifLite(emitterNif);
            boolean isSale = !emitterNorm.isEmpty()
                    && emitterNorm.equalsIgnoreCase(selfNorm);

            for (int j = 0; j < invoices.size(); j++) {
                String label = f.getName() + progress
                        + (invoices.size() > 1
                                ? "  [" + (j + 1) + "/" + invoices.size() + "]"
                                : "");
                if (isSale) {
                    showSalesExtractionDialog(invoices.get(j), label, pdfBytes);
                    salesCount++;
                } else {
                    // Reusa el flujo de gasto con visor.
                    showExtractionResultWithViewer(invoices.get(j), label, j, pdfBytes);
                    expensesCount++;
                }
            }
        }

        // Aviso final con balance: cuántas ventas / cuántos gastos
        // se importaron. Útil porque el asesor a veces selecciona en
        // bloque y no recuerda lo que entró cada cubeta.
        if (salesCount + expensesCount > 0) {
            showInfo(t("client.import_auto.done.title"),
                    t("client.import_auto.done.body")
                            .replace("{s}", String.valueOf(salesCount))
                            .replace("{e}", String.valueOf(expensesCount)));
        }
    }

    /** Quita espacios y pasa a mayúsculas — útil para comparar NIFs. */
    private String normalizeNifLite(String s) {
        if (s == null) return "";
        return s.replaceAll("\\s+", "").toUpperCase();
    }

    private void importPurchasePdfsMulti() {
        javafx.stage.FileChooser chooser = new javafx.stage.FileChooser();
        chooser.setTitle(t("purchases.action.import_multi"));
        chooser.getExtensionFilters().add(
                new javafx.stage.FileChooser.ExtensionFilter("PDF", "*.pdf"));
        java.util.List<java.io.File> files = chooser.showOpenMultipleDialog(
                root.getScene().getWindow());
        if (files == null || files.isEmpty()) return;
        // Procesado secuencial: extract async → showAndWait del diálogo
        // de revisión por cada archivo. El asesor controla el ritmo.
        int total = files.size();
        for (int i = 0; i < total; i++) {
            java.io.File f = files.get(i);
            String progress = "  (" + (i + 1) + "/" + total + ")";
            processSinglePurchasePdf(f, progress);
        }
    }

    /**
     * Procesa un único PDF: lo sube al backend para extraer, lee los
     * bytes del archivo (para el visor) y muestra el diálogo de revisión.
     * Bloquea (showAndWait) hasta que el usuario cierra el diálogo, lo
     * cual permite encadenar varios PDFs secuencialmente.
     */
    private void processSinglePurchasePdf(java.io.File file, String progressSuffix) {
        byte[] pdfBytes;
        try {
            pdfBytes = java.nio.file.Files.readAllBytes(file.toPath());
        } catch (Exception ex) {
            showError(t("purchases.import.fail.title"),
                    t("purchases.import.fail.body"));
            return;
        }
        // Extract síncrono — bloquea el flujo del multi-import para
        // que el siguiente PDF espere a que el asesor cierre este.
        String json;
        try {
            json = pdfImportApi.uploadAndExtract(file);
        } catch (Exception ex) {
            showError(t("purchases.import.fail.title"),
                    t("purchases.import.fail.body"));
            return;
        }
        List<String> invoices = splitJsonArrayObjects(json);
        if (invoices.isEmpty()) {
            showError(t("purchases.import.fail.title"),
                    t("purchases.import.fail.body"));
            return;
        }
        int n = invoices.size();
        for (int i = 0; i < n; i++) {
            String label = file.getName()
                    + (progressSuffix == null ? "" : progressSuffix)
                    + (n > 1 ? "  [" + (i + 1) + "/" + n + "]" : "");
            showExtractionResultWithViewer(invoices.get(i), label, i, pdfBytes);
        }
    }

    /**
     * Parte un array JSON top-level "[{...},{...}]" en una lista de
     * objetos top-level. Tolera strings con llaves escapadas dentro.
     * No es un parser JSON completo — solo necesitamos separar objetos
     * en el primer nivel del array.
     */
    private List<String> splitJsonArrayObjects(String arrayJson) {
        List<String> out = new ArrayList<>();
        if (arrayJson == null) return out;
        String s = arrayJson.trim();
        if (s.isEmpty()) return out;
        // Si nos pasan un objeto suelto (no array), tratarlo como
        // lista de 1.
        if (s.startsWith("{")) {
            out.add(s);
            return out;
        }
        int depth = 0;
        int start = -1;
        boolean inString = false;
        boolean escape = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (escape) { escape = false; continue; }
            if (c == '\\') { escape = true; continue; }
            if (c == '"') { inString = !inString; continue; }
            if (inString) continue;
            if (c == '{') {
                if (depth == 0) start = i;
                depth++;
            } else if (c == '}') {
                depth--;
                if (depth == 0 && start >= 0) {
                    out.add(s.substring(start, i + 1));
                    start = -1;
                }
            }
        }
        return out;
    }

    /**
     * Multi-import de PDFs de ventas: el asesor selecciona varios PDFs
     * que el cliente le entregó por trimestre, y para cada uno se crea
     * un asiento contable de venta directo (sin factura legal — el
     * cliente la emitió en otro sistema). El diálogo de revisión por
     * PDF incluye el visor con la imagen del PDF a la izquierda.
     */
    private void importSalesPdfsMulti() {
        javafx.stage.FileChooser chooser = new javafx.stage.FileChooser();
        chooser.setTitle(t("sales.action.import_multi"));
        chooser.getExtensionFilters().add(
                new javafx.stage.FileChooser.ExtensionFilter("PDF", "*.pdf"));
        java.util.List<java.io.File> files = chooser.showOpenMultipleDialog(
                root.getScene().getWindow());
        if (files == null || files.isEmpty()) return;
        int total = files.size();
        for (int i = 0; i < total; i++) {
            java.io.File f = files.get(i);
            byte[] bytes;
            try {
                bytes = java.nio.file.Files.readAllBytes(f.toPath());
            } catch (Exception ex) {
                showError(t("purchases.import.fail.title"),
                        t("purchases.import.fail.body"));
                continue;
            }
            String json;
            try {
                json = pdfImportApi.uploadAndExtract(f);
            } catch (Exception ex) {
                showError(t("purchases.import.fail.title"),
                        t("purchases.import.fail.body"));
                continue;
            }
            // El extractor está enfocado en compras (NIF emisor =
            // proveedor). En ventas reinterpretamos:
            //   emitterNif/supplierName → NIF/nombre del CLIENTE.
            // Los demás campos (fecha, base, IVA, total, nº) valen igual.
            String progress = "  (" + (i + 1) + "/" + total + ")";
            List<String> invoices = splitJsonArrayObjects(json);
            if (invoices.isEmpty()) continue;
            for (int j = 0; j < invoices.size(); j++) {
                String label = f.getName() + progress
                        + (invoices.size() > 1
                                ? "  [" + (j + 1) + "/" + invoices.size() + "]"
                                : "");
                showSalesExtractionDialog(invoices.get(j), label, bytes);
            }
        }
    }

    /**
     * Diálogo de revisión para importar 1 PDF de venta → asiento DRAFT.
     * Layout: PdfViewer a la izquierda + formulario a la derecha con
     * NIF cliente, fecha, base, IVA%, IVA, total, concepto. Botón
     * "Crear asiento" llama al backend que persiste el PDF y crea el
     * asiento contable. {@code showAndWait} bloquea para encadenar
     * varios PDFs.
     */
    private void showSalesExtractionDialog(String json, String filename, byte[] pdfBytes) {
        // Mapeo extractor → ventas:
        //   - receiverNif/receiverName = DESTINATARIO de la factura =
        //     CLIENTE en facturas emitidas (el caso normal en ventas).
        // NO caemos al emitterNif/supplierName si el receptor está vacío
        // — el emisor es el propio Benjamin, ponerlo como cliente
        // genera "Fra. X a Benjamin" que no tiene sentido. Mejor dejar
        // el campo vacío y que el usuario rellene a mano.
        // extractField devuelve "—" cuando el campo no existe en el JSON;
        // por eso isBlankOrDash() y no isBlank().
        String customerNif = extractField(json, "receiverNif");
        String customerName = extractField(json, "receiverName");
        if (isBlankOrDash(customerNif)) customerNif = "";
        if (isBlankOrDash(customerName)) customerName = "";
        String number = extractField(json, "invoiceNumber");
        String date = extractField(json, "invoiceDate");
        String base = extractNumber(json, "baseAmount");
        String vatPct = extractNumber(json, "vatPercent");
        String vatAmt = extractNumber(json, "vatAmount");
        String total = extractNumber(json, "totalAmount");
        // Flags rectificativa (los devuelve InvoiceFieldsExtractor):
        //   rectifying = true → el PDF dice "FACTURA RECTIFICATIVA"
        //   rectifiedInvoiceNumber = nº de la factura original que se anula
        boolean rectifying = "true".equalsIgnoreCase(extractBool(json, "rectifying"));
        String rectifiedNumber = extractField(json, "rectifiedInvoiceNumber");
        if (isBlankOrDash(rectifiedNumber)) rectifiedNumber = "";

        Dialog<ButtonType> dialog = new Dialog<>();
        dialog.setTitle(t("sales.import.title_prefix") + filename);
        ButtonType cancelBt = new ButtonType(t("purchases.import.action.accept"),
                ButtonBar.ButtonData.CANCEL_CLOSE);
        ButtonType saveBt = new ButtonType(t("sales.import.action.create_entry"),
                ButtonBar.ButtonData.OK_DONE);
        dialog.getDialogPane().getButtonTypes().addAll(saveBt, cancelBt);

        // Limpiar "—" en los demás campos también para que no entren al
        // TextField como literal de guión.
        if (isBlankOrDash(number)) number = "";
        if (isBlankOrDash(date)) date = "";
        if (isBlankOrDash(base)) base = "";
        if (isBlankOrDash(vatPct)) vatPct = "";
        if (isBlankOrDash(vatAmt)) vatAmt = "";
        if (isBlankOrDash(total)) total = "";

        TextField nifField = new TextField(customerNif);
        TextField nameField = new TextField(customerName);
        TextField numberField = new TextField(number);
        TextField dateField = new TextField(date);
        TextField baseField = new TextField(base);
        TextField vatPctField = new TextField(vatPct);
        TextField vatAmtField = new TextField(vatAmt);
        TextField totalField = new TextField(total);
        TextField conceptField = new TextField();
        conceptField.setPromptText(t("purchases.import.field.concept_prompt"));

        // Controles de rectificativa:
        //   - CheckBox: detectado vs no detectado (editable)
        //   - TextField "anula factura nº": editable, prerelleno con
        //     lo que detectó el extractor.
        CheckBox rectifyingChk = new CheckBox(t("sales.import.field.rectifying"));
        rectifyingChk.setSelected(rectifying);
        TextField rectifiedField = new TextField(rectifiedNumber);
        rectifiedField.setPromptText(t("sales.import.field.rectified_prompt"));
        rectifiedField.setDisable(!rectifying);
        rectifyingChk.selectedProperty().addListener(
                (obs, old, val) -> rectifiedField.setDisable(!val));

        // Pre-rellenar concepto con un texto razonable.
        //   Normal:        "Fra. {nº} a {cliente}"
        //   Rectificativa: "Fra. rectificativa {nº} a {cliente} (anula {original})"
        StringBuilder pre = new StringBuilder();
        if (rectifying) pre.append("Fra. rectificativa ");
        else pre.append("Fra. ");
        if (!number.isBlank()) pre.append(number);
        if (!customerName.isBlank()) {
            if (pre.length() > "Fra. ".length()) pre.append(" ");
            pre.append("a ").append(customerName);
        }
        if (rectifying && !rectifiedNumber.isBlank()) {
            pre.append(" (anula ").append(rectifiedNumber).append(")");
        }
        if (pre.length() > "Fra. ".length()) conceptField.setText(pre.toString());

        for (TextField tf : new TextField[]{
                nifField, nameField, numberField, dateField, baseField,
                vatPctField, vatAmtField, totalField, conceptField, rectifiedField}) {
            tf.setPrefColumnCount(32);
        }
        GridPane g = new GridPane();
        g.setHgap(12); g.setVgap(8);
        int row = 0;
        g.add(new Label(t("sales.import.field.customer_nif")), 0, row); g.add(nifField, 1, row++);
        g.add(new Label(t("sales.import.field.customer_name")), 0, row); g.add(nameField, 1, row++);
        g.add(new Label(t("purchases.import.field.number")), 0, row); g.add(numberField, 1, row++);
        g.add(new Label(t("purchases.import.field.date")), 0, row); g.add(dateField, 1, row++);
        g.add(new Label(t("purchases.import.field.base")), 0, row); g.add(baseField, 1, row++);
        g.add(new Label(t("purchases.import.field.vat_pct")), 0, row); g.add(vatPctField, 1, row++);
        g.add(new Label(t("purchases.import.field.vat_amount")), 0, row); g.add(vatAmtField, 1, row++);
        g.add(new Label(t("purchases.import.field.total")), 0, row); g.add(totalField, 1, row++);
        g.add(new Label(t("purchases.import.field.concept")), 0, row); g.add(conceptField, 1, row++);
        // Bloque rectificativa al final.
        g.add(rectifyingChk, 0, row, 2, 1); row++;
        g.add(new Label(t("sales.import.field.rectified_label")), 0, row); g.add(rectifiedField, 1, row++);

        // Montaje con visor.
        com.benjagest.ui.support.PdfViewer viewer = new com.benjagest.ui.support.PdfViewer();
        viewer.loadFromBytes(pdfBytes);
        viewer.attachAutoDispose();
        viewer.setPrefWidth(550);
        javafx.scene.control.ScrollPane formScroll =
                new javafx.scene.control.ScrollPane(g);
        formScroll.setFitToWidth(true);
        formScroll.setStyle("-fx-background-color: transparent;");
        javafx.scene.control.SplitPane split =
                new javafx.scene.control.SplitPane(viewer, formScroll);
        split.setDividerPositions(0.55);
        // Sin wrap externo: el visor PDF ya tiene su propio ScrollPane y
        // el formulario tiene formScroll. installDialog estándar añadía
        // un tercer ScrollPane que obligaba a scrollear "dos ventanas"
        // para llegar al final de un PDF con zoom alto.
        installDialogNoWrap(dialog, split);
        dialog.getDialogPane().setPrefSize(1200, 720);

        Button saveBtn = (Button) dialog.getDialogPane().lookupButton(saveBt);
        saveBtn.getStyleClass().add("button-primary");
        saveBtn.addEventFilter(javafx.event.ActionEvent.ACTION, ev -> {
            ev.consume();
            java.time.LocalDate invDate = parseDateSafe(dateField.getText());
            if (invDate == null) {
                showError(t("sales.import.fail.title"),
                        t("sales.import.fail.missing.body"));
                return;
            }
            java.math.BigDecimal baseAmt = parseDecimalSafe(baseField.getText());
            java.math.BigDecimal vatPctV = parseDecimalSafe(vatPctField.getText());
            java.math.BigDecimal vatAmtV = parseDecimalSafe(vatAmtField.getText());
            java.math.BigDecimal totalAmt = parseDecimalSafe(totalField.getText());
            if (baseAmt == null || vatAmtV == null || totalAmt == null) {
                showError(t("sales.import.fail.title"),
                        t("sales.import.fail.missing.body"));
                return;
            }
            final String nif = nullIfBlank(nifField.getText());
            final String name = nullIfBlank(nameField.getText());
            final String invoiceNum = nullIfBlank(numberField.getText());
            final String concept = nullIfBlank(conceptField.getText());
            final boolean isRect = rectifyingChk.isSelected();
            final String rectifiedNum = nullIfBlank(rectifiedField.getText());
            Task<com.benjagest.ui.service.AccountingApiClient.SalesImportResult> task = new Task<>() {
                @Override
                protected com.benjagest.ui.service.AccountingApiClient.SalesImportResult call()
                        throws Exception {
                    return accountingApiClient.importSalesFromPdf(
                            nif, name, invDate,
                            baseAmt, vatPctV, vatAmtV,
                            java.math.BigDecimal.ZERO, totalAmt,
                            invoiceNum, concept, pdfBytes,
                            isRect, rectifiedNum);
                }
            };
            task.setOnSucceeded(e -> {
                // Asiento creado → refrescamos Diario y Por validar.
                com.benjagest.ui.support.RefreshBus.emit(
                        com.benjagest.ui.support.RefreshBus.TOPIC_JOURNAL,
                        com.benjagest.ui.support.RefreshBus.TOPIC_SALES);
                dialog.setResult(saveBt);
                dialog.close();
            });
            task.setOnFailed(e -> {
                // Mostramos el mensaje real del backend cuando lo hay
                // (p. ej. "No hay ejercicio fiscal OPEN para esa fecha"),
                // no solo un toast genérico. Hace mucho más fácil
                // diagnosticar problemas de configuración del cliente.
                Throwable ex = task.getException();
                String detail = ex == null ? null : ex.getMessage();
                showError(t("sales.import.fail.title"),
                        detail == null || detail.isBlank()
                                ? t("sales.import.fail.body")
                                : detail);
            });
            start(task, "sales-pdf-import");
        });

        dialog.showAndWait();
    }

    /**
     * Wrapper para que la multi-importación pase los bytes del PDF al
     * diálogo. Cuando hay bytes, el diálogo monta un visor PDF a la
     * izquierda del formulario.
     */
    private void showExtractionResultWithViewer(String json, String filename,
                                                  int invoiceIndex, byte[] pdfBytes) {
        currentExtractionPdfBytes = pdfBytes;
        try {
            showExtractionResult(json, filename, invoiceIndex);
        } finally {
            currentExtractionPdfBytes = null;
        }
    }

    /** Bytes del PDF de la factura en curso de revisión (para el visor). */
    private byte[] currentExtractionPdfBytes;

    private void showExtractionResult(String json, String filename, int invoiceIndex) {
        // Diálogo EDITABLE: el usuario corrige los campos que el
        // extractor no acertó y puede guardar la corrección como
        // plantilla para futuras facturas del mismo NIF de proveedor.
        String supplier = extractField(json, "supplierName");
        String emitter = extractField(json, "emitterNif");
        String number = extractField(json, "invoiceNumber");
        String date = extractField(json, "invoiceDate");
        String base = extractNumber(json, "baseAmount");
        String vatPct = extractNumber(json, "vatPercent");
        String vatAmt = extractNumber(json, "vatAmount");
        String total = extractNumber(json, "totalAmount");
        String confidence = extractField(json, "confidence");
        String hash = extractField(json, "documentSha256");

        // Valores originales (para detectar si el usuario modificó)
        String origSupplier = supplier;
        String origVatPct = vatPct;

        Dialog<ButtonType> dialog = new Dialog<>();
        dialog.setTitle(t("purchases.import.result_prefix") + filename);
        ButtonType acceptBt = new ButtonType(t("purchases.import.action.accept"),
                ButtonBar.ButtonData.CANCEL_CLOSE);
        ButtonType saveExpenseBt = new ButtonType(t("purchases.import.action.save_expense"),
                ButtonBar.ButtonData.OK_DONE);
        ButtonType saveTemplateBt = new ButtonType(t("purchases.import.action.save_template"),
                ButtonBar.ButtonData.LEFT);
        dialog.getDialogPane().getButtonTypes().addAll(
                saveTemplateBt, saveExpenseBt, acceptBt);

        TextField supplierField = new TextField(supplier);
        TextField emitterField = new TextField(emitter);
        TextField numberField = new TextField(number);
        TextField dateField = new TextField(date);
        TextField baseField = new TextField(base);
        TextField vatPctField = new TextField(vatPct);
        TextField vatAmtField = new TextField(vatAmt);
        TextField totalField = new TextField(total);
        // Concepto del gasto — el asesor escribe qué fue ese gasto
        // (p. ej. "Material de oficina") y eso aparece en la línea 6xx
        // del asiento contable. Si lo deja vacío, se genera un fallback.
        TextField conceptField = new TextField();
        conceptField.setPromptText(t("purchases.import.field.concept_prompt"));
        for (TextField tf : new TextField[]{
                supplierField, emitterField, numberField, dateField,
                baseField, vatPctField, vatAmtField, totalField,
                conceptField}) {
            tf.setPrefColumnCount(32);
        }

        GridPane g = new GridPane();
        g.setHgap(12); g.setVgap(8);
        int row = 0;
        g.add(new Label(t("purchases.import.field.supplier")), 0, row); g.add(supplierField, 1, row++);
        g.add(new Label(t("purchases.import.field.emitter_nif")), 0, row); g.add(emitterField, 1, row++);
        g.add(new Label(t("purchases.import.field.number")), 0, row); g.add(numberField, 1, row++);
        g.add(new Label(t("purchases.import.field.date")), 0, row); g.add(dateField, 1, row++);
        g.add(new Label(t("purchases.import.field.base")), 0, row); g.add(baseField, 1, row++);
        g.add(new Label(t("purchases.import.field.vat_pct")), 0, row); g.add(vatPctField, 1, row++);
        g.add(new Label(t("purchases.import.field.vat_amount")), 0, row); g.add(vatAmtField, 1, row++);
        g.add(new Label(t("purchases.import.field.total")), 0, row); g.add(totalField, 1, row++);
        g.add(new Label(t("purchases.import.field.concept")), 0, row); g.add(conceptField, 1, row++);
        g.add(new Separator(), 0, row++, 2, 1);
        Label confLabel = new Label(confidenceLabel(confidence));
        confLabel.getStyleClass().add("settings-section-title");
        g.add(new Label(t("purchases.import.field.confidence")), 0, row); g.add(confLabel, 1, row++);

        Label tip = new Label(t("purchases.import.tip.edit"));
        tip.setWrapText(true);
        tip.getStyleClass().add("settings-hint");
        g.add(tip, 0, row++, 2, 1);

        if (hash != null && hash.length() > 16) {
            Label hashShort = new Label(t("purchases.import.field.hash") + " " + hash.substring(0, 16) + "…");
            hashShort.getStyleClass().add("settings-hint");
            g.add(hashShort, 0, row++, 2, 1);
        }

        // Si la multi-importación cargó bytes del PDF, montamos un visor a
        // la izquierda del formulario (SplitPane). Sin bytes, el diálogo
        // sale como hasta ahora — sin cambios.
        if (currentExtractionPdfBytes != null && currentExtractionPdfBytes.length > 0) {
            com.benjagest.ui.support.PdfViewer viewer =
                    new com.benjagest.ui.support.PdfViewer();
            viewer.loadFromBytes(currentExtractionPdfBytes);
            viewer.attachAutoDispose();
            viewer.setPrefWidth(550);
            javafx.scene.control.ScrollPane formScroll =
                    new javafx.scene.control.ScrollPane(g);
            formScroll.setFitToWidth(true);
            formScroll.setStyle("-fx-background-color: transparent;");
            javafx.scene.control.SplitPane split =
                    new javafx.scene.control.SplitPane(viewer, formScroll);
            split.setDividerPositions(0.55);
            // Sin wrap externo (mismo motivo que en ventas): evita el
            // doble scroll del visor PDF + formulario dentro de otro
            // ScrollPane mayor.
            installDialogNoWrap(dialog, split);
            dialog.getDialogPane().setPrefSize(1200, 720);
        } else {
            installDialog(dialog, g);
            dialog.getDialogPane().setPrefWidth(620);
        }

        // Botón "Guardar plantilla" deshabilitado si NI el extractor ni el
        // usuario han informado un NIF — sin ningún NIF no hay clave de
        // búsqueda posible.
        final String detectedNif = (emitter == null) ? "" : emitter.trim();
        Button saveBtn = (Button) dialog.getDialogPane().lookupButton(saveTemplateBt);
        Runnable refreshSaveEnabled = () -> {
            String corr = emitterField.getText() == null ? "" : emitterField.getText().trim();
            saveBtn.setDisable(detectedNif.isEmpty() && corr.isEmpty());
        };
        refreshSaveEnabled.run();
        emitterField.textProperty().addListener((o, ov, nv) -> refreshSaveEnabled.run());

        saveBtn.addEventFilter(javafx.event.ActionEvent.ACTION, ev -> {
            ev.consume(); // no cerrar
            // Componer rules JSON con los valores fijos. CLAVE de diseño:
            // la plantilla se busca por el NIF que DETECTA el extractor
            // (aunque sea el equivocado, p. ej. el LU de Amazon en vez del
            // W español). Si el usuario corrige el NIF en el modal, ese
            // NIF corregido se guarda como regla `emitterNif` para que
            // futuras importaciones (que detectarán otra vez lo mismo)
            // muestren el NIF correcto. Así la corrección sobrevive al
            // hecho de que el extractor falle de forma consistente.
            StringBuilder rules = new StringBuilder("{");
            boolean first = true;
            String sName = supplierField.getText();
            if (sName != null && !sName.isBlank()) {
                rules.append("\"supplierName\":\"").append(sName.replace("\"", "\\\"")).append("\"");
                first = false;
            }
            String pct = vatPctField.getText();
            if (pct != null && !pct.isBlank() && !pct.equals("—")) {
                if (!first) rules.append(",");
                rules.append("\"vatPercent\":\"").append(pct.trim()).append("\"");
                first = false;
            }
            String correctedNif = emitterField.getText() == null ? "" : emitterField.getText().trim();
            if (!correctedNif.isEmpty() && !correctedNif.equalsIgnoreCase(detectedNif)) {
                if (!first) rules.append(",");
                rules.append("\"emitterNif\":\"").append(correctedNif.replace("\"", "\\\"")).append("\"");
            }
            rules.append("}");
            // Llave de búsqueda: el detectado si existe; si el extractor no
            // detectó nada, caemos al corregido como llave (caso raro).
            String lookupNif = detectedNif.isEmpty() ? correctedNif : detectedNif;
            Task<Void> task = new Task<>() {
                @Override protected Void call() throws Exception {
                    pdfImportApi.saveTemplate(lookupNif, sName, rules.toString());
                    return null;
                }
            };
            task.setOnSucceeded(e -> showInfo(t("purchases.import.template_saved.title"),
                    t("purchases.import.template_saved.body") + " " + lookupNif));
            task.setOnFailed(e -> showError(t("purchases.import.template_failed.title"),
                    t("purchases.import.template_failed.body")));
            start(task, "pdf-template-save");
        });

        // Botón "Guardar gasto" — persiste la factura como purchase_invoice,
        // intenta crear asiento contable (si la empresa tiene PGC + fiscal
        // year), maneja dedup 409. Cierra el diálogo en éxito.
        Button saveExpense = (Button) dialog.getDialogPane().lookupButton(saveExpenseBt);
        saveExpense.getStyleClass().add("button-primary");
        saveExpense.addEventFilter(javafx.event.ActionEvent.ACTION, ev -> {
            ev.consume();
            var payload = new com.benjagest.ui.service.PurchaseInvoiceApiClient.SavePayload();
            payload.supplierNif = nullIfBlank(emitterField.getText());
            payload.supplierName = nullIfBlank(supplierField.getText());
            payload.invoiceNumber = nullIfBlank(numberField.getText());
            payload.invoiceDate = parseDateSafe(dateField.getText());
            payload.baseAmount = parseDecimalSafe(baseField.getText());
            payload.vatPercent = parseDecimalSafe(vatPctField.getText());
            payload.vatAmount = parseDecimalSafe(vatAmtField.getText());
            payload.totalAmount = parseDecimalSafe(totalField.getText());
            payload.documentSha256 = nullIfBlank(hash);
            payload.invoiceIndexInPdf = invoiceIndex;
            payload.concept = nullIfBlank(conceptField.getText());
            // Validación mínima: necesitamos al menos total o base+iva.
            if (payload.totalAmount == null
                    && (payload.baseAmount == null || payload.vatAmount == null)) {
                showError(t("purchases.save.fail.missing.title"),
                        t("purchases.save.fail.missing.body"));
                return;
            }
            Task<com.benjagest.ui.service.PurchaseInvoiceApiClient.SaveOutcome> task = new Task<>() {
                @Override
                protected com.benjagest.ui.service.PurchaseInvoiceApiClient.SaveOutcome call()
                        throws Exception {
                    return purchasesApi.save(payload);
                }
            };
            task.setOnSucceeded(e -> {
                var outcome = task.getValue();
                if (outcome.duplicate()) {
                    showInfo(t("purchases.save.duplicate.title"),
                            t("purchases.save.duplicate.body"));
                } else {
                    showInfo(t("purchases.save.ok.title"),
                            t("purchases.save.ok.body"));
                    // El gasto generó factura + asiento contable. Avisamos
                    // a las pantallas de Compras y Diario.
                    com.benjagest.ui.support.RefreshBus.emit(
                            com.benjagest.ui.support.RefreshBus.TOPIC_PURCHASES,
                            com.benjagest.ui.support.RefreshBus.TOPIC_JOURNAL);
                }
                dialog.setResult(saveExpenseBt);
                dialog.close();
            });
            task.setOnFailed(e -> {
                // Mensaje real del backend cuando lo hay (p. ej.
                // "No hay ejercicio fiscal OPEN" o
                // "No se pudo crear la sub-cuenta del proveedor").
                Throwable ex = task.getException();
                String detail = ex == null ? null : ex.getMessage();
                showError(t("purchases.save.fail.title"),
                        detail == null || detail.isBlank()
                                ? t("purchases.save.fail.body")
                                : detail);
            });
            start(task, "purchase-invoice-save");
        });

        dialog.showAndWait();
    }

    /** Parser seguro para BigDecimal; admite coma o punto decimal y "—". */
    private java.math.BigDecimal parseDecimalSafe(String text) {
        if (text == null || text.isBlank() || "—".equals(text.trim())) return null;
        try { return new java.math.BigDecimal(text.trim().replace(",", ".")); }
        catch (Exception ex) { return null; }
    }

    private String nullIfBlank(String s) {
        return (s == null || s.isBlank()) ? null : s.trim();
    }

    private String confidenceLabel(String code) {
        if (code == null || code.isBlank()) return "—";
        return switch (code) {
            case "HIGH" -> "✓ " + t("purchases.import.confidence.high");
            case "MEDIUM" -> "⚠ " + t("purchases.import.confidence.medium");
            case "LOW" -> "✗ " + t("purchases.import.confidence.low");
            default -> code;
        };
    }

    private String extractField(String json, String field) {
        java.util.regex.Matcher m = java.util.regex.Pattern
                .compile("\"" + field + "\"\\s*:\\s*\"([^\"]*)\"")
                .matcher(json);
        return m.find() ? m.group(1) : "—";
    }

    /** "—" o cadena vacía → true. Usado por fallbacks de extractField. */
    private boolean isBlankOrDash(String s) {
        return s == null || s.isBlank() || "—".equals(s.trim());
    }

    /**
     * Extrae un booleano del JSON ({@code "campo": true|false}). Para
     * flags como {@code rectifying} en el resultado del extractor.
     */
    private String extractBool(String json, String field) {
        java.util.regex.Matcher m = java.util.regex.Pattern
                .compile("\"" + field + "\"\\s*:\\s*(true|false)")
                .matcher(json);
        return m.find() ? m.group(1) : "false";
    }

    private String extractNumber(String json, String field) {
        java.util.regex.Matcher m = java.util.regex.Pattern
                .compile("\"" + field + "\"\\s*:\\s*([0-9.\\-]+)")
                .matcher(json);
        return m.find() ? m.group(1) : "—";
    }

    // ===================================================================
    //  Pantalla Fichajes (Slice C4 — RD 8/2019)
    // ===================================================================

    private final com.benjagest.ui.service.TimeClockApiClient timeClockApi =
            new com.benjagest.ui.service.TimeClockApiClient();
    private TableView<com.benjagest.ui.model.TimeClockEntry> timeClockTable;
    // FJ-3 — banner + botones del fichaje, para resaltar el que toca segun la jornada.
    private Label timeClockSuggestBanner;
    // FJ — enlace para reactivar los botones cuando se desactivan los no sugeridos.
    private javafx.scene.control.Hyperlink timeClockOverrideLink;
    private final java.util.Map<String, Button> timeClockPunchButtons = new java.util.HashMap<>();

    private void showTimeClock() {
        // EMP-USER-MAP: el employeeId NO es el userId. Buscamos primero
        // la ficha en `employees` por (user_id, company_id). Si el
        // usuario no tiene ficha (típico de OWNERs de empresa que nunca
        // se dieron de alta como empleado), pintamos pantalla amigable
        // con instrucciones en lugar de explotar al primer fichaje.
        Task<com.benjagest.ui.service.TimeClockApiClient.MyEmployee> resolve = new Task<>() {
            @Override
            protected com.benjagest.ui.service.TimeClockApiClient.MyEmployee call() throws Exception {
                return timeClockApi.me();
            }
        };
        resolve.setOnSucceeded(ev -> renderTimeClock(resolve.getValue()));
        resolve.setOnFailed(ev -> {
            Throwable err = resolve.getException();
            if (err instanceof com.benjagest.ui.service.TimeClockApiClient.NotEnrolledException nee) {
                renderTimeClockNotEnrolled(nee.getMessage());
            } else {
                setCenterAnimated(scroll(errorPanel(t("timeclock.fail.title"))));
            }
        });
        start(resolve, "timeclock-resolve-employee");
    }

    /** Pinta una pantalla amigable cuando el usuario no tiene ficha de
     *  empleado en la empresa activa — no puede fichar hasta que el
     *  admin lo dé de alta en Personal > Empleados. */
    private void renderTimeClockNotEnrolled(String backendMsg) {
        Label header = label(t("timeclock.header"), "settings-section-title");
        Label icon = new Label("⚠");
        icon.setStyle("-fx-font-size: 48px;");
        Label title = new Label(t("timeclock.not_enrolled.title"));
        title.getStyleClass().add("settings-section-title");
        Label body = new Label(backendMsg != null && !backendMsg.isBlank()
                ? backendMsg
                : t("timeclock.not_enrolled.body"));
        body.setWrapText(true);
        body.getStyleClass().add("settings-hint");
        VBox notice = new VBox(12, icon, title, body);
        notice.setPadding(new Insets(40));
        notice.setAlignment(Pos.CENTER);
        VBox content = new VBox(16, header, notice);
        content.setPadding(new Insets(20));
        setCenterAnimated(scroll(content));
    }

    private void renderTimeClock(com.benjagest.ui.service.TimeClockApiClient.MyEmployee me) {
        String employeeId = me.employeeId();
        // Header explicativo: contexto legal RD 8/2019 y aclaración de
        // que el CSV emitido al fichar sirve para verificación pública.
        Label header = label(t("timeclock.header"), "settings-section-title");
        Label hint = new Label(t("timeclock.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        // Bloque grande con botones de fichaje. Tamaño visible para
        // que sirva también en kiosko (los empleados fichan rápido).
        Button inBtn = bigPunchButton(t("timeclock.action.in"), "fas-sign-in-alt", "IN", employeeId);
        Button outBtn = bigPunchButton(t("timeclock.action.out"), "fas-sign-out-alt", "OUT", employeeId);
        Button breakStartBtn = bigPunchButton(t("timeclock.action.break_start"), "fas-coffee", "BREAK_START", employeeId);
        Button breakEndBtn = bigPunchButton(t("timeclock.action.break_end"), "fas-utensils", "BREAK_END", employeeId);
        HBox punchRow = new HBox(12, inBtn, outBtn, breakStartBtn, breakEndBtn);

        // FJ-3 — registro de botones para poder resaltar el que toca + banner de sugerencia.
        timeClockPunchButtons.clear();
        timeClockPunchButtons.put("IN", inBtn);
        timeClockPunchButtons.put("OUT", outBtn);
        timeClockPunchButtons.put("BREAK_START", breakStartBtn);
        timeClockPunchButtons.put("BREAK_END", breakEndBtn);
        timeClockSuggestBanner = new Label();
        timeClockSuggestBanner.setWrapText(true);
        timeClockSuggestBanner.setMaxWidth(Double.MAX_VALUE);
        timeClockSuggestBanner.setManaged(false);
        timeClockSuggestBanner.setVisible(false);
        // FJ — "Fichar otra cosa": reactiva los botones desactivados (desviación real).
        timeClockOverrideLink = new javafx.scene.control.Hyperlink(t("timeclock.suggest.override"));
        timeClockOverrideLink.setManaged(false);
        timeClockOverrideLink.setVisible(false);
        timeClockOverrideLink.setOnAction(ev -> {
            timeClockPunchButtons.values().forEach(b -> b.setDisable(false));
            timeClockOverrideLink.setManaged(false);
            timeClockOverrideLink.setVisible(false);
        });

        // Listado últimos N fichajes del empleado.
        timeClockTable = new TableView<>();
        timeClockTable.getStyleClass().add("data-table");
        timeClockTable.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        timeClockTable.setPlaceholder(new Label(t("timeclock.placeholder.empty")));

        TableColumn<com.benjagest.ui.model.TimeClockEntry, String> colWhen =
                new TableColumn<>(t("timeclock.col.when"));
        colWhen.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().eventTimeIso()));
        colWhen.setPrefWidth(200);
        colWhen.setComparator(ISO_DATE_COMPARATOR);
        TableColumn<com.benjagest.ui.model.TimeClockEntry, String> colType =
                new TableColumn<>(t("timeclock.col.type"));
        colType.setCellValueFactory(c -> new SimpleStringProperty(localizedPunchType(c.getValue().eventType())));
        colType.setPrefWidth(150);
        TableColumn<com.benjagest.ui.model.TimeClockEntry, String> colOrigin =
                new TableColumn<>(t("timeclock.col.origin"));
        colOrigin.setCellValueFactory(c -> new SimpleStringProperty(localizedEnum("timeclock_origin", c.getValue().origin())));
        colOrigin.setPrefWidth(100);
        TableColumn<com.benjagest.ui.model.TimeClockEntry, String> colStatus =
                new TableColumn<>(t("timeclock.col.status"));
        colStatus.setCellValueFactory(c -> new SimpleStringProperty(localizedEnum("timeclock_status", c.getValue().status())));
        colStatus.setPrefWidth(110);
        timeClockTable.getColumns().addAll(java.util.List.of(colWhen, colType, colOrigin, colStatus));

        Button refresh = new Button(t("timeclock.action.refresh"));
        refresh.setGraphic(icon("fas-sync"));
        refresh.setOnAction(ev -> reloadTimeClock(employeeId));

        // Bloque de exportación para Inspección de Trabajo / Hacienda.
        // Defaults: trimestre actual completo (lo más habitual).
        Label exportTitle = label(t("timeclock.export.title"), "settings-section-title");
        Label exportHint = new Label(t("timeclock.export.hint"));
        exportHint.setWrapText(true);
        exportHint.getStyleClass().add("settings-hint");
        java.time.LocalDate today = java.time.LocalDate.now();
        int quarter = (today.getMonthValue() - 1) / 3;
        java.time.LocalDate quarterStart = java.time.LocalDate.of(today.getYear(), quarter * 3 + 1, 1);
        java.time.LocalDate quarterEnd = quarterStart.plusMonths(3).minusDays(1);
        DatePicker fromPicker = new DatePicker(quarterStart);
        DatePicker toPicker = new DatePicker(quarterEnd);
        Label fromLbl = new Label(t("timeclock.export.from"));
        Label toLbl = new Label(t("timeclock.export.to"));
        Button exportPdfBtn = new Button(t("timeclock.export.pdf"));
        exportPdfBtn.setGraphic(icon("fas-file-pdf"));
        exportPdfBtn.getStyleClass().add("button-primary");
        exportPdfBtn.setOnAction(ev -> downloadTimeClockExport("pdf",
                fromPicker.getValue(), toPicker.getValue(), employeeId));
        Button exportCsvBtn = new Button(t("timeclock.export.csv"));
        exportCsvBtn.setGraphic(icon("fas-file-csv"));
        exportCsvBtn.setOnAction(ev -> downloadTimeClockExport("csv",
                fromPicker.getValue(), toPicker.getValue(), employeeId));
        HBox exportRow = new HBox(8, fromLbl, fromPicker, toLbl, toPicker,
                exportPdfBtn, exportCsvBtn);
        exportRow.setAlignment(Pos.CENTER_LEFT);
        VBox exportBlock = new VBox(8, exportTitle, exportHint, exportRow);

        VBox body = new VBox(16, header, hint, timeClockSuggestBanner, punchRow, timeClockOverrideLink,
                refresh, timeClockTable,
                new Separator(), exportBlock);
        body.setPadding(new Insets(20));

        setCenterAnimated(scroll(body));
        reloadTimeClock(employeeId);
        refreshTimeClockSuggestion();
        // NOTIF-RT — refresco en vivo de la lista + sugerencia cuando llega un fichaje.
        com.benjagest.ui.support.RefreshBus.subscribe(
                com.benjagest.ui.support.RefreshBus.TOPIC_TIMECLOCK,
                () -> { reloadTimeClock(employeeId); refreshTimeClockSuggestion(); },
                timeClockTable);
    }

    /**
     * FJ-3 — Pide la sugerencia de "que toca fichar ahora" segun la jornada
     * asignada y, si estamos en ventana (+/-15 min), resalta ese boton y muestra
     * un banner. Fuera de ventana o jornada completa: banner suave. Sin jornada
     * hoy: no muestra nada (todos los botones normales). Nunca bloquea ni rompe
     * el fichaje si la sugerencia falla.
     */
    private void refreshTimeClockSuggestion() {
        if (timeClockSuggestBanner == null) return;
        Task<com.benjagest.ui.service.TimeClockApiClient.Suggestion> task = new Task<>() {
            @Override protected com.benjagest.ui.service.TimeClockApiClient.Suggestion call() throws Exception {
                return timeClockApi.suggestion();
            }
        };
        task.setOnSucceeded(ev -> applyTimeClockSuggestion(task.getValue()));
        task.setOnFailed(ev -> applyTimeClockSuggestion(null)); // silencioso
        start(task, "timeclock-suggestion");
    }

    private void applyTimeClockSuggestion(com.benjagest.ui.service.TimeClockApiClient.Suggestion s) {
        // Reset: limpia resaltado y reactiva todos los botones; oculta el override.
        timeClockPunchButtons.values().forEach(b -> {
            b.getStyleClass().remove("punch-suggested");
            b.setDisable(false);
        });
        if (timeClockOverrideLink != null) {
            timeClockOverrideLink.setManaged(false);
            timeClockOverrideLink.setVisible(false);
        }
        Label banner = timeClockSuggestBanner;
        banner.getStyleClass().removeAll("suggest-banner", "suggest-banner-soft");
        if (s == null || !s.hasSchedule()) {
            banner.setManaged(false);
            banner.setVisible(false);
            return;
        }
        banner.setManaged(true);
        banner.setVisible(true);
        if (!s.hasAction()) { // jornada completa
            banner.getStyleClass().addAll("suggest-banner", "suggest-banner-soft");
            banner.setText(t("timeclock.suggest.completed"));
            return;
        }
        String actionLabel = localizedPunchType(s.action());
        if (s.inWindow()) {
            banner.getStyleClass().add("suggest-banner");
            banner.setText(t("timeclock.suggest.now").replace("{action}", actionLabel)
                    + "  " + t("timeclock.suggest.scheduled")
                            .replace("{time}", nz(s.scheduledTime()))
                            .replace("{from}", nz(s.windowFrom()))
                            .replace("{to}", nz(s.windowTo())));
            Button b = timeClockPunchButtons.get(s.action());
            if (b != null && !b.getStyleClass().contains("punch-suggested")) {
                b.getStyleClass().add("punch-suggested");
            }
            // CONTENDO: solo el botón que toca. Desactiva los demás para no confundir;
            // "Fichar otra cosa" los reactiva (desviación real, RD 8/2019).
            timeClockPunchButtons.forEach((code, btn) -> btn.setDisable(!code.equals(s.action())));
            if (timeClockOverrideLink != null) {
                timeClockOverrideLink.setManaged(true);
                timeClockOverrideLink.setVisible(true);
            }
        } else {
            banner.getStyleClass().addAll("suggest-banner", "suggest-banner-soft");
            banner.setText(t("timeclock.suggest.next").replace("{action}", actionLabel)
                            .replace("{time}", nz(s.scheduledTime()))
                    + "  " + t("timeclock.suggest.next_hint").replace("{from}", nz(s.windowFrom())));
        }
    }

    private static String nz(String s) { return s == null ? "" : s; }

    /** Descarga el export de fichajes y ofrece guardarlo. */
    private void downloadTimeClockExport(String format,
                                          java.time.LocalDate from, java.time.LocalDate to,
                                          String employeeId) {
        if (from == null || to == null || from.isAfter(to)) {
            showError(t("timeclock.export.fail.range.title"),
                    t("timeclock.export.fail.range.body"));
            return;
        }
        Task<byte[]> task = new Task<>() {
            @Override protected byte[] call() throws Exception {
                return "pdf".equals(format)
                        ? timeClockApi.exportPdf(from.toString(), to.toString(), employeeId)
                        : timeClockApi.exportCsv(from.toString(), to.toString(), employeeId);
            }
        };
        task.setOnSucceeded(ev -> {
            byte[] body = task.getValue();
            javafx.stage.FileChooser fc = new javafx.stage.FileChooser();
            fc.setInitialFileName("fichajes-" + from + "_" + to + "." + format);
            fc.getExtensionFilters().add(new javafx.stage.FileChooser.ExtensionFilter(
                    format.toUpperCase(), "*." + format));
            java.io.File target = fc.showSaveDialog(root.getScene().getWindow());
            if (target == null) return;
            try {
                java.nio.file.Files.write(target.toPath(), body);
                showInfo(t("timeclock.export.ok.title"),
                        t("timeclock.export.ok.body") + "\n" + target.getAbsolutePath());
            } catch (java.io.IOException ex) {
                showError(t("timeclock.export.fail.write.title"), ex.getMessage());
            }
        });
        task.setOnFailed(ev -> showError(t("timeclock.export.fail.title"),
                t("timeclock.export.fail.body")));
        start(task, "timeclock-export-" + format);
    }

    private Button bigPunchButton(String text, String iconName, String eventType, String employeeId) {
        Button btn = new Button(text);
        btn.setGraphic(icon(iconName));
        btn.getStyleClass().add("invoice-validate-action");
        btn.setMinHeight(50);
        btn.setMinWidth(160);
        btn.setOnAction(ev -> punch(employeeId, eventType));
        return btn;
    }

    private void punch(String employeeId, String eventType) {
        Task<com.benjagest.ui.service.TimeClockApiClient.PunchOutcome> task = new Task<>() {
            @Override
            protected com.benjagest.ui.service.TimeClockApiClient.PunchOutcome call() throws Exception {
                return timeClockApi.punch(employeeId, eventType);
            }
        };
        task.setOnSucceeded(ev -> {
            var outcome = task.getValue();
            // Mostramos el CSV en un dialog con TextField copiable para
            // que el trabajador lo guarde si lo necesita (justificante).
            javafx.scene.control.TextField field = new javafx.scene.control.TextField(outcome.csv());
            field.setEditable(false);
            field.setPrefColumnCount(20);
            Alert ok = new Alert(Alert.AlertType.INFORMATION);
            ok.setHeaderText(t("timeclock.success.title"));
            VBox content = new VBox(8,
                    new Label(t("timeclock.success.csv_label")),
                    field);
            // TC-CAL (Benjamin 2026-06-10): si el backend devolvio
            // holidayWarning, anadir tarjeta amarilla con icono y
            // nombre del festivo. No bloquea — solo informa.
            if (outcome.hasHolidayWarning()) {
                Label warnTitle = new Label(t("timeclock.holiday_warning.title"));
                warnTitle.getStyleClass().add("holiday-warning-title");
                String typeLabel = humanizeHolidayType(outcome.holidayType());
                Label warnBody = new Label(t("timeclock.holiday_warning.body")
                        .replace("{type}", typeLabel)
                        .replace("{name}", outcome.holidayName()));
                warnBody.setWrapText(true);
                warnBody.getStyleClass().add("holiday-warning-body");
                VBox warnBox = new VBox(4, warnTitle, warnBody);
                warnBox.getStyleClass().add("holiday-warning-card");
                warnBox.setPadding(new Insets(10));
                content.getChildren().add(warnBox);
            }
            content.setPadding(new Insets(8));
            ok.getDialogPane().setContent(content);
            ok.showAndWait();
            reloadTimeClock(employeeId);
            refreshTimeClockSuggestion();
        });
        task.setOnFailed(ev -> showError(t("timeclock.fail.title"), t("timeclock.fail.body")));
        start(task, "timeclock-punch");
    }

    /** TC-CAL — humaniza el code de holiday_type para el warning. */
    private String humanizeHolidayType(String raw) {
        if (raw == null || raw.isBlank()) return "";
        return switch (raw.trim().toUpperCase(java.util.Locale.ROOT)) {
            case "FESTIVO" -> t("holiday.type.festivo");
            case "AJUSTE" -> t("holiday.type.ajuste");
            case "CIERRE" -> t("holiday.type.cierre");
            default -> raw;
        };
    }

    private void reloadTimeClock(String employeeId) {
        Task<java.util.List<com.benjagest.ui.model.TimeClockEntry>> task = new Task<>() {
            @Override
            protected java.util.List<com.benjagest.ui.model.TimeClockEntry> call() throws Exception {
                return timeClockApi.recent(employeeId, 50);
            }
        };
        task.setOnSucceeded(ev -> {
            if (timeClockTable != null) {
                timeClockTable.setItems(FXCollections.observableArrayList(task.getValue()));
            }
        });
        task.setOnFailed(ev -> {
            if (timeClockTable != null) timeClockTable.getItems().clear();
        });
        start(task, "timeclock-reload");
    }

    private String localizedPunchType(String code) {
        if (code == null) return "";
        // Para los 4 tipos estándar usamos las keys legacy que ya existían.
        // Para tipos custom (creados por el OWNER) caemos a humanizeFromKey
        // con prefix labor.cfg_timeclock.code.* (mismo prefix que el listado
        // de configuración). Así una cláusula "COMIDA" muestra "Comida"
        // si hay key, y "COMIDA" como último recurso — pero NUNCA debería
        // salir el código en bruto si el i18n está completo.
        return switch (code) {
            case "IN" -> t("timeclock.type.in");
            case "OUT" -> t("timeclock.type.out");
            case "BREAK_START" -> t("timeclock.type.break_start");
            case "BREAK_END" -> t("timeclock.type.break_end");
            default -> humanizeFromKey("labor.cfg_timeclock.code." + code,
                    humanizeCodeSafe(code));
        };
    }

    /** Última red de seguridad: COMIDA_LIBRE → "Comida libre". */
    private static String humanizeCodeSafe(String code) {
        if (code == null || code.isEmpty()) return "";
        String low = code.replace('_', ' ').toLowerCase(java.util.Locale.ROOT);
        return Character.toUpperCase(low.charAt(0)) + low.substring(1);
    }

