    /**
     * Crea los tipos de IVA/IRPF estándar que falten (por código), idempotente.
     * Conecta con los textos legales: 21/10/4 % + Exento (art. 20) + Inversión
     * del sujeto pasivo (art. 84.Uno.2º) y retenciones IRPF 15/7/19 %. El
     * usuario puede añadir/editar/borrar otros. Quedan elegibles en Nueva factura.
     */
    private void loadStandardVatRates() {
        java.util.Set<String> have = new java.util.HashSet<>();
        boolean hasVatDefault = false;
        for (var r : vatRatesTable.getItems()) {
            if (r.code() != null) have.add(r.code().toUpperCase());
            if ("VAT".equals(r.kind()) && r.isDefault()) hasVatDefault = true;
        }
        record Std(String kind, String code, String label, String pct, boolean def) {}
        final boolean genDefault = !hasVatDefault;
        java.util.List<Std> std = java.util.List.of(
                new Std("VAT", "GEN21", "IVA general (21%)", "21", genDefault),
                new Std("VAT", "RED10", "IVA reducido (10%)", "10", false),
                new Std("VAT", "SUP4", "IVA superreducido (4%)", "4", false),
                new Std("VAT", "EXE0", "Exento de IVA (art. 20 Ley 37/1992)", "0", false),
                new Std("VAT", "ISP0", "Inversión del sujeto pasivo (art. 84.Uno.2º)", "0", false),
                new Std("WITHHOLDING", "IRPF15", "Retención profesionales (15%)", "15", false),
                new Std("WITHHOLDING", "IRPF7", "Retención profesionales reducida (7%)", "7", false),
                new Std("WITHHOLDING", "IRPF19", "Retención arrendamientos (19%)", "19", false));
        java.util.List<Std> toCreate = new java.util.ArrayList<>();
        for (Std s : std) if (!have.contains(s.code())) toCreate.add(s);
        javafx.stage.Window win = root == null || root.getScene() == null ? null : root.getScene().getWindow();
        if (toCreate.isEmpty()) {
            toast(win, t("billing.config.vat.load_standard.exists"));
            return;
        }
        Task<Integer> task = new Task<>() {
            @Override protected Integer call() throws Exception {
                int n = 0;
                for (Std s : toCreate) {
                    billingApiClient.createVatRate(s.kind(), s.code(), s.label(),
                            new java.math.BigDecimal(s.pct()), s.def());
                    n++;
                }
                return n;
            }
        };
        task.setOnSucceeded(ev -> {
            reloadVatRates();
            toast(win, t("billing.config.vat.load_standard.done")
                    .replace("{n}", String.valueOf(task.getValue())));
        });
        task.setOnFailed(ev -> showError(t("billing.config.vat.section"),
                task.getException() == null ? "" : task.getException().getMessage()));
        start(task, "vat-load-standard");
    }

    private void reloadVatRates() {
        if (vatRatesTable == null) return;
        Task<java.util.List<com.benjagest.ui.model.VatRateEntry>> task = new Task<>() {
            @Override
            protected java.util.List<com.benjagest.ui.model.VatRateEntry> call() throws Exception {
                return billingApiClient.listVatRates(true);
            }
        };
        task.setOnSucceeded(ev -> vatRatesTable.setItems(FXCollections.observableArrayList(task.getValue())));
        task.setOnFailed(ev -> vatRatesTable.getItems().clear());
        start(task, "billing-vat-rates-reload");
    }

    private void showVatRateEditor(com.benjagest.ui.model.VatRateEntry existing) {
        Dialog<ButtonType> dialog = new Dialog<>();
        dialog.setTitle(existing == null ? t("billing.config.vat.editor.title_new")
                : t("billing.config.vat.editor.title_edit"));
        ButtonType saveBt = new ButtonType(t("billing.config.vat.editor.save"), ButtonBar.ButtonData.OK_DONE);
        dialog.getDialogPane().getButtonTypes().addAll(saveBt, ButtonType.CANCEL);

        ComboBox<String> kindCombo = new ComboBox<>();
        kindCombo.getItems().addAll("VAT", "WITHHOLDING");
        localizeEnumCombo(kindCombo, "vat_kind");
        kindCombo.getSelectionModel().select(existing == null ? "VAT" : existing.kind());
        kindCombo.setDisable(existing != null);  // no editable tras crear

        TextField codeField = new TextField(existing == null ? "" : existing.code());
        codeField.setDisable(existing != null);  // no editable tras crear
        TextField labelField = new TextField(existing == null ? "" : existing.label());
        TextField pctField = new TextField(existing == null ? "21" : existing.percent().toPlainString());
        CheckBox defaultCb = new CheckBox(t("billing.config.vat.editor.is_default"));
        defaultCb.setSelected(existing != null && existing.isDefault());
        CheckBox activeCb = new CheckBox(t("billing.config.vat.editor.active"));
        activeCb.setSelected(existing == null || existing.active());

        GridPane grid = new GridPane();
        grid.setHgap(10); grid.setVgap(8); grid.setPadding(new Insets(10));
        grid.add(new Label(t("billing.config.vat.editor.kind")), 0, 0); grid.add(kindCombo, 1, 0);
        grid.add(new Label(t("billing.config.vat.editor.code")), 0, 1); grid.add(codeField, 1, 1);
        grid.add(new Label(t("billing.config.vat.editor.label")), 0, 2); grid.add(labelField, 1, 2);
        grid.add(new Label(t("billing.config.vat.editor.percent")), 0, 3); grid.add(pctField, 1, 3);
        grid.add(defaultCb, 1, 4);
        grid.add(activeCb, 1, 5);
        installDialog(dialog, grid);

        dialog.showAndWait().ifPresent(bt -> {
            if (bt != saveBt) return;
            try {
                java.math.BigDecimal pct = new java.math.BigDecimal(pctField.getText().trim().replace(",", "."));
                Task<com.benjagest.ui.model.VatRateEntry> task = new Task<>() {
                    @Override
                    protected com.benjagest.ui.model.VatRateEntry call() throws Exception {
                        if (existing == null) {
                            return billingApiClient.createVatRate(
                                    kindCombo.getValue(),
                                    codeField.getText().trim().toUpperCase(),
                                    labelField.getText().trim(),
                                    pct,
                                    defaultCb.isSelected());
                        }
                        return billingApiClient.updateVatRate(
                                existing.id(),
                                existing.kind(),
                                existing.code(),
                                labelField.getText().trim(),
                                pct,
                                defaultCb.isSelected(),
                                activeCb.isSelected());
                    }
                };
                task.setOnSucceeded(ev -> reloadVatRates());
                task.setOnFailed(ev -> showError(t("billing.config.vat.editor.fail.title"),
                        t("billing.config.vat.editor.fail.body")));
                start(task, "billing-vat-rates-save");
            } catch (NumberFormatException ex) {
                showError(t("billing.config.vat.editor.fail.title"),
                        t("billing.config.vat.editor.invalid_percent"));
            }
        });
    }

    private void deleteVatRate(com.benjagest.ui.model.VatRateEntry entry) {
        Alert confirm = new Alert(Alert.AlertType.CONFIRMATION,
                t("billing.config.vat.delete.body") + " " + entry.label(),
                ButtonType.OK, ButtonType.CANCEL);
        confirm.setHeaderText(t("billing.config.vat.delete.title"));
        confirm.showAndWait().ifPresent(bt -> {
            if (bt != ButtonType.OK) return;
            Task<Void> task = new Task<>() {
                @Override
                protected Void call() throws Exception {
                    billingApiClient.deleteVatRate(entry.id());
                    return null;
                }
            };
            task.setOnSucceeded(ev -> reloadVatRates());
            task.setOnFailed(ev -> showError(t("billing.config.vat.delete.fail.title"),
                    t("billing.config.vat.delete.fail.body")));
            start(task, "billing-vat-rates-delete");
        });
    }

    /**
     * Bloque "Auditoría SIF" — listado del Registro de Eventos del SIF
     * con filtro por tipo, botón Refrescar y botón Verificar integridad.
     * Es la cara visible del slice VF-EVENTS para el OWNER/ADMIN.
     */
    private TableView<com.benjagest.ui.model.SifEventEntry> sifEventsTable;
    private ComboBox<String> sifEventTypeFilter;

    /** Traduce el código de tipo de evento SIF (INVOICE_VALIDATED → "Factura validada"…). */
    private String localizedSifEventType(String code) {
        if (code == null || code.isBlank()) return "";
        return t("sif.event_type." + code);
    }

    /**
     * Humaniza el payload JSON del evento SIF a "Etiqueta: valor · …" (claves comunes
     * traducidas; valores largos como UUID se acortan). Si no se puede parsear, lo deja tal cual.
     */
    private String humanizeSifPayload(String payload) {
        if (payload == null || payload.isBlank()) return "";
        java.util.Map<String, String> map = parseDataMap(payload);
        if (map.isEmpty()) return payload;
        StringBuilder sb = new StringBuilder();
        for (java.util.Map.Entry<String, String> e : map.entrySet()) {
            String label = t("sif.payload." + e.getKey());
            if (label.equals("sif.payload." + e.getKey())) label = e.getKey(); // sin traducción
            String val = e.getValue() == null ? "" : e.getValue();
            if (val.length() > 14) val = val.substring(0, 12) + "…";
            if (sb.length() > 0) sb.append("   ·   ");
            sb.append(label).append(": ").append(val);
        }
        return sb.toString();
    }

    private Node sifEventsAuditBlock() {
        Label header = label(t("billing.config.sif.section"), "settings-section-title");
        Label hint = new Label(t("billing.config.sif.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        sifEventTypeFilter = new ComboBox<>();
        sifEventTypeFilter.getItems().addAll(
                t("list.filter.all"),
                "SYSTEM_START", "SYSTEM_STOP",
                "INVOICE_VALIDATED", "INVOICE_VOIDED",
                "ANOMALY_DETECTION_INVOICES_RUN", "ANOMALY_DETECTION_INVOICES_HIT",
                "ANOMALY_DETECTION_EVENTS_RUN", "ANOMALY_DETECTION_EVENTS_HIT",
                "BACKUP_RESTORED",
                "EXPORT_INVOICES", "EXPORT_EVENTS",
                "SUMMARY_6H", "SUMMARY_SHUTDOWN");
        sifEventTypeFilter.getSelectionModel().selectFirst();
        sifEventTypeFilter.getStyleClass().add("form-input");
        // Mostrar los tipos traducidos en el combo (el valor interno sigue siendo el
        // código, para que el filtro funcione igual).
        sifEventTypeFilter.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(String s) {
                return s == null || s.equals(t("list.filter.all")) ? s : localizedSifEventType(s);
            }
            @Override public String fromString(String s) { return s; }
        });

        sifEventsTable = new TableView<>();
        sifEventsTable.getStyleClass().add("data-table");
        sifEventsTable.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        sifEventsTable.setPlaceholder(new Label(t("billing.config.sif.placeholder.empty")));
        sifEventsTable.setPrefHeight(220);

        TableColumn<com.benjagest.ui.model.SifEventEntry, String> colWhen =
                new TableColumn<>(t("billing.config.sif.col.when"));
        colWhen.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().generatedAtIso()));
        colWhen.setPrefWidth(160);
        colWhen.setComparator(ISO_DATE_COMPARATOR);
        TableColumn<com.benjagest.ui.model.SifEventEntry, String> colType =
                new TableColumn<>(t("billing.config.sif.col.type"));
        colType.setCellValueFactory(c -> new SimpleStringProperty(localizedSifEventType(c.getValue().eventType())));
        colType.setPrefWidth(220);
        TableColumn<com.benjagest.ui.model.SifEventEntry, String> colHash =
                new TableColumn<>(t("billing.config.sif.col.hash"));
        colHash.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().hashCurrent() == null || c.getValue().hashCurrent().length() < 16
                        ? "" : c.getValue().hashCurrent().substring(0, 16) + "…"));
        colHash.setPrefWidth(150);
        TableColumn<com.benjagest.ui.model.SifEventEntry, String> colPayload =
                new TableColumn<>(t("billing.config.sif.col.payload"));
        colPayload.setCellValueFactory(c -> new SimpleStringProperty(
                humanizeSifPayload(c.getValue().payload())));
        sifEventsTable.getColumns().addAll(List.of(colWhen, colType, colHash, colPayload));

        Button refresh = new Button(t("billing.config.sif.refresh"));
        refresh.setGraphic(icon("fas-sync"));
        refresh.setOnAction(event -> refreshSifEvents());

        Button verifySif = new Button(t("billing.config.sif.verify"));
        verifySif.setGraphic(icon("fas-shield-alt"));
        verifySif.setOnAction(event -> verifySifEventChain());

        HBox filterRow = new HBox(8, sifEventTypeFilter, refresh, verifySif);
        filterRow.setAlignment(javafx.geometry.Pos.CENTER_LEFT);

        // VF-EVENTS-EXPORT: bloque de exportación PDF/CSV verificable.
        // Defaults: trimestre actual. Emite evento legal EXPORT_EVENTS
        // en la cadena SIF + auditoría con SHA-256 del documento.
        java.time.LocalDate today = java.time.LocalDate.now();
        int quarter = (today.getMonthValue() - 1) / 3;
        java.time.LocalDate quarterStart = java.time.LocalDate.of(today.getYear(), quarter * 3 + 1, 1);
        java.time.LocalDate quarterEnd = quarterStart.plusMonths(3).minusDays(1);
        DatePicker fromPicker = new DatePicker(quarterStart);
        DatePicker toPicker = new DatePicker(quarterEnd);
        Button exportPdfBtn = new Button(t("billing.config.sif.export.pdf"));
        exportPdfBtn.setGraphic(icon("fas-file-pdf"));
        exportPdfBtn.getStyleClass().add("button-primary");
        exportPdfBtn.setOnAction(ev -> downloadSifExport("pdf",
                fromPicker.getValue(), toPicker.getValue(),
                sifEventTypeFilter == null ? null : sifEventTypeFilter.getValue()));
        Button exportCsvBtn = new Button(t("billing.config.sif.export.csv"));
        exportCsvBtn.setGraphic(icon("fas-file-csv"));
        exportCsvBtn.setOnAction(ev -> downloadSifExport("csv",
                fromPicker.getValue(), toPicker.getValue(),
                sifEventTypeFilter == null ? null : sifEventTypeFilter.getValue()));
        Label exportTitle = label(t("billing.config.sif.export.title"), "settings-section-title");
        Label exportHint = new Label(t("billing.config.sif.export.hint"));
        exportHint.setWrapText(true);
        exportHint.getStyleClass().add("settings-hint");
        HBox exportRow = new HBox(8,
                label(t("billing.config.sif.export.from"), "form-label"), fromPicker,
                label(t("billing.config.sif.export.to"), "form-label"), toPicker,
                exportPdfBtn, exportCsvBtn);
        exportRow.setAlignment(javafx.geometry.Pos.CENTER_LEFT);
        VBox exportBlock = new VBox(8, new Separator(), exportTitle, exportHint, exportRow);

        // Carga inicial diferida: si la pestaña aun no esta visible,
        // un Task no bloqueante asegura que la UI responde antes de
        // que el endpoint responda.
        refreshSifEvents();

        return new VBox(8, header, hint, filterRow, sifEventsTable, exportBlock);
    }

    /** Descarga el export del Registro de Eventos del SIF. */
    private void downloadSifExport(String format,
                                    java.time.LocalDate from, java.time.LocalDate to,
                                    String selectedTypeFilter) {
        if (from == null || to == null || from.isAfter(to)) {
            showError(t("settings.audit.export.fail.range.title"),
                    t("settings.audit.export.fail.range.body"));
            return;
        }
        String filter = selectedTypeFilter;
        if (filter != null && ("(todos)".equals(filter) || "(all)".equals(filter)
                || t("list.filter.all").equals(filter))) {
            filter = null;
        }
        String eventType = filter;
        Task<byte[]> task = new Task<>() {
            @Override protected byte[] call() throws Exception {
                return billingApiClient.exportSifEvents(format,
                        from.toString(), to.toString(), eventType);
            }
        };
        task.setOnSucceeded(ev -> {
            byte[] body = task.getValue();
            javafx.stage.FileChooser fc = new javafx.stage.FileChooser();
            fc.setInitialFileName("sif-events-" + from + "_" + to + "." + format);
            fc.getExtensionFilters().add(new javafx.stage.FileChooser.ExtensionFilter(
                    format.toUpperCase(), "*." + format));
            java.io.File target = fc.showSaveDialog(root.getScene().getWindow());
            if (target == null) return;
            try {
                java.nio.file.Files.write(target.toPath(), body);
                showInfo(t("settings.audit.export.ok.title"),
                        t("settings.audit.export.ok.body") + "\n" + target.getAbsolutePath());
                // Refresca el listado para que se vea el EXPORT_EVENTS recién emitido.
                refreshSifEvents();
            } catch (java.io.IOException ex) {
                showError(t("settings.audit.export.fail.write.title"), ex.getMessage());
            }
        });
        task.setOnFailed(ev -> showError(t("settings.audit.export.fail.title"),
                t("settings.audit.export.fail.body")));
        start(task, "sif-export-" + format);
    }

    private void refreshSifEvents() {
        if (sifEventsTable == null) return;
        String selected = sifEventTypeFilter == null ? null : sifEventTypeFilter.getValue();
        String filter = (selected == null
                || t("list.filter.all").equals(selected)
                || "(todos)".equals(selected)
                || "(all)".equals(selected))
                ? null : selected;
        Task<java.util.List<com.benjagest.ui.model.SifEventEntry>> task = new Task<>() {
            @Override
            protected java.util.List<com.benjagest.ui.model.SifEventEntry> call() throws Exception {
                return billingApiClient.listSifEvents(filter);
            }
        };
        task.setOnSucceeded(event -> sifEventsTable.getItems().setAll(task.getValue()));
        task.setOnFailed(event -> sifEventsTable.getItems().clear());
        start(task, "billing-sif-events-list");
    }

    private void verifySifEventChain() {
        Task<com.benjagest.ui.model.SifEventIntegrityResult> task = new Task<>() {
            @Override
            protected com.benjagest.ui.model.SifEventIntegrityResult call() throws Exception {
                return billingApiClient.verifySifEventChain();
            }
        };
        task.setOnSucceeded(event -> {
            com.benjagest.ui.model.SifEventIntegrityResult result = task.getValue();
            if (result.ok()) {
                Alert ok = new Alert(Alert.AlertType.INFORMATION,
                        t("billing.config.sif.verify.ok.prefix") + result.totalChecked()
                                + t("billing.config.sif.verify.ok.suffix"),
                        ButtonType.OK);
                ok.setHeaderText(null);
                ok.showAndWait();
            } else {
                String broken = result.brokenEventType() == null ? "—" : result.brokenEventType();
                String body = t("billing.config.sif.verify.broken.prefix") + broken + "\n"
                        + (result.reason() == null ? "" : result.reason());
                showError(t("billing.config.sif.verify.broken.title"), body);
            }
        });
        task.setOnFailed(event -> showError(
                t("billing.config.sif.verify.fail.title"),
                t("billing.config.sif.verify.fail.body")));
        start(task, "billing-sif-events-verify");
    }

    private javafx.scene.control.TextArea textArea(String value, String prompt) {
        javafx.scene.control.TextArea area = new javafx.scene.control.TextArea(value == null ? "" : value);
        area.setPromptText(prompt);
        area.setPrefRowCount(2);
        area.setWrapText(true);
        area.getStyleClass().add("form-input");
        return area;
    }

    private void applyMigration() {
        // Resolver la serie del combo EDITABLE: el valor elegido de la lista o
        // el código tecleado (que puede no existir aún → se creará).
        SeriesEntry serie = migrationSeriesCombo.getValue();
        String typed = migrationSeriesCombo.getEditor() == null ? null
                : migrationSeriesCombo.getEditor().getText();
        if (typed != null && !typed.isBlank()
                && (serie == null || !typed.trim().equalsIgnoreCase(serie.code()))) {
            serie = resolveMigrationSeries(typed);
        }
        if (serie == null || serie.code() == null || serie.code().isBlank()) {
            showError(t("billing.config.migration.error.no_series.title"),
                    t("billing.config.migration.error.no_series.body"));
            return;
        }
        if (!migrationAcknowledgeCheck.isSelected()) {
            showError(t("billing.config.migration.error.no_ack.title"),
                    t("billing.config.migration.error.no_ack.body"));
            return;
        }
        Integer next;
        try {
            next = Integer.parseInt(migrationNextNumberField.getText().trim());
        } catch (NumberFormatException ex) {
            showError(t("billing.config.migration.error.bad_number.title"),
                    t("billing.config.migration.error.bad_number.body"));
            return;
        }
        if (next < 1) {
            showError(t("billing.config.migration.error.bad_number.title"),
                    t("billing.config.migration.error.bad_number.body_low"));
            return;
        }
        Integer yr = null;
        try {
            String y = migrationYearField == null ? null : migrationYearField.getText();
            if (y != null && !y.isBlank()) yr = Integer.parseInt(y.trim());
        } catch (NumberFormatException ignored) { /* año vacío/erróneo → null */ }

        final SeriesEntry serieF = serie;
        final int nextNumber = next;
        final Integer declaredYear = yr;
        final String fmt = migrationFormatTemplate == null || migrationFormatTemplate.isBlank()
                ? null : migrationFormatTemplate;
        final byte[] pdf = migrationImportedPdf;
        final com.benjagest.ui.service.BillingApiClient.MigrationExtracted ext = migrationExtracted;
        final String declarationText = t("billing.config.migration.ack");

        Runnable onOk = () -> {
            Alert ok = new Alert(Alert.AlertType.INFORMATION,
                    t("billing.config.migration.success_prefix") + serieF.code()
                            + t("billing.config.migration.success.middle") + nextNumber + ".",
                    ButtonType.OK);
            ok.setHeaderText(null);
            ok.showAndWait();
            migrationImportedPdf = null;
            migrationExtracted = null;
            pendingBillingTab = "config";
            billingRefresh.run();
        };

        Task<Void> task = new Task<>() {
            @Override protected Void call() throws Exception {
                // Si la serie NO existe (id null), se crea ahora con el próximo
                // número ya fijado. Si existe, se ajusta su número.
                String seriesId = serieF.id();
                boolean created = false;
                if (seriesId == null) {
                    SeriesEntry s = billingApiClient.createSeries(
                            serieF.code(), "STANDARD", "BY_YEAR", fmt, nextNumber, false);
                    seriesId = s.id();
                    created = true;
                }
                if (pdf != null) {
                    // Guarda PDF de prueba + declaración firmada (fijar el número
                    // de nuevo es inocuo: mismo valor).
                    billingApiClient.confirmMigrationBaseline(
                            seriesId, serieF.code(),
                            ext == null ? null : ext.invoiceNumber(),
                            nextNumber - 1,
                            ext == null ? null : ext.invoiceDateIso(),
                            declaredYear,
                            ext == null ? null : ext.emitterNif(),
                            ext == null ? null : ext.customerNif(),
                            ext == null ? null : ext.customerName(),
                            ext == null ? null : ext.totalAmount(),
                            ext == null ? null : ext.confidence(),
                            true, declarationText, pdf);
                } else if (!created) {
                    // Serie existente, sin PDF: solo ajustar el próximo número.
                    billingApiClient.migrateSeries(seriesId, nextNumber, true);
                }
                return null;
            }
        };
        task.setOnSucceeded(event -> onOk.run());
        task.setOnFailed(event -> showError(t("billing.config.migration.fail.title"),
                task.getException() == null ? t("billing.config.migration.fail.body")
                        : task.getException().getMessage()));
        start(task, "migration-apply");
    }

    /** MIG-2 — Importa el PDF de la última factura y autorellena por OCR. */
    private void importMigrationPdf() {
        javafx.stage.FileChooser fc = new javafx.stage.FileChooser();
        fc.setTitle(t("billing.config.migration.import_pdf"));
        fc.getExtensionFilters().add(new javafx.stage.FileChooser.ExtensionFilter("PDF", "*.pdf"));
        java.io.File file = fc.showOpenDialog(root == null || root.getScene() == null
                ? null : root.getScene().getWindow());
        if (file == null) return;
        final byte[] bytes;
        try {
            bytes = java.nio.file.Files.readAllBytes(file.toPath());
        } catch (Exception ex) {
            showError(t("billing.config.migration.import_pdf"), ex.getMessage());
            return;
        }
        Task<com.benjagest.ui.service.BillingApiClient.MigrationExtracted> task = new Task<>() {
            @Override protected com.benjagest.ui.service.BillingApiClient.MigrationExtracted call() throws Exception {
                return billingApiClient.extractMigrationBaseline(bytes);
            }
        };
        task.setOnSucceeded(ev -> {
            var ext = task.getValue();
            migrationImportedPdf = bytes;
            migrationExtracted = ext;
            // Troceador: el usuario etiqueta cada parte del número. De ahí salen
            // serie, año, próximo número y la plantilla de formato.
            String yearHint = ext.invoiceDateIso() != null && ext.invoiceDateIso().length() >= 4
                    ? ext.invoiceDateIso().substring(0, 4) : null;
            buildMigrationTokenTagger(ext.invoiceNumber(), yearHint);
            String sb = t("billing.config.migration.detected.header")
                    + "\n• " + t("billing.config.migration.detected.number") + ": " + nzDash(ext.invoiceNumber())
                    + "\n• " + t("billing.config.migration.detected.series") + ": " + nzDash(ext.seriesCodeGuess())
                    + "\n• " + t("billing.config.migration.detected.date") + ": " + nzDash(ext.invoiceDateIso())
                    + "\n• " + t("billing.config.migration.detected.customer") + ": "
                            + nzDash(ext.customerName()) + "  " + nzDash(ext.customerNif())
                    + "\n• " + t("billing.config.migration.detected.total") + ": " + nzDash(ext.totalAmount())
                    + (ext.confidence() == null ? ""
                            : "   (" + t("billing.config.migration.detected.confidence") + ": " + ext.confidence() + ")");
            migrationDetectedLabel.setText(sb);
            migrationDetectedLabel.setVisible(true);
            migrationDetectedLabel.setManaged(true);
        });
        task.setOnFailed(ev -> showError(t("billing.config.migration.import_pdf"),
                task.getException() == null ? "" : task.getException().getMessage()));
        start(task, "migration-extract");
    }

    private static String nzDash(String s) { return s == null || s.isBlank() ? "—" : s; }

    /** MIG-3 — Diálogo con las migraciones (baselines) guardadas + ver su PDF de prueba. */
    private void showMigrationBaselines() {
        Dialog<Void> dialog = new Dialog<>();
        dialog.setTitle(t("billing.config.migration.view_saved"));
        dialog.setHeaderText(null);
        dialog.setResizable(true);
        dialog.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);

        TableView<com.benjagest.ui.service.BillingApiClient.BaselineEntry> table = new TableView<>();
        table.getStyleClass().add("data-table");
        table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        table.setPlaceholder(new Label(t("billing.config.migration.saved.empty")));
        table.setPrefSize(680, 300);
        TableColumn<com.benjagest.ui.service.BillingApiClient.BaselineEntry, String> cSerie =
                new TableColumn<>(t("billing.config.migration.field.series"));
        cSerie.setCellValueFactory(c -> new SimpleStringProperty(nzDash(c.getValue().seriesCode())));
        TableColumn<com.benjagest.ui.service.BillingApiClient.BaselineEntry, String> cNum =
                new TableColumn<>(t("billing.config.migration.detected.number"));
        cNum.setCellValueFactory(c -> new SimpleStringProperty(nzDash(c.getValue().fullNumber())));
        TableColumn<com.benjagest.ui.service.BillingApiClient.BaselineEntry, String> cDate =
                new TableColumn<>(t("billing.config.migration.detected.date"));
        cDate.setCellValueFactory(c -> new SimpleStringProperty(nzDash(c.getValue().date())));
        TableColumn<com.benjagest.ui.service.BillingApiClient.BaselineEntry, String> cCust =
                new TableColumn<>(t("billing.config.migration.detected.customer"));
        cCust.setCellValueFactory(c -> new SimpleStringProperty(nzDash(c.getValue().customerName())));
        TableColumn<com.benjagest.ui.service.BillingApiClient.BaselineEntry, String> cTotal =
                new TableColumn<>(t("billing.config.migration.detected.total"));
        cTotal.setCellValueFactory(c -> new SimpleStringProperty(nzDash(c.getValue().total())));
        TableColumn<com.benjagest.ui.service.BillingApiClient.BaselineEntry, String> cWhen =
                new TableColumn<>(t("billing.config.migration.saved.registered"));
        cWhen.setCellValueFactory(c -> new SimpleStringProperty(shortIso(c.getValue().createdAt())));
        table.getColumns().addAll(java.util.List.of(cSerie, cNum, cDate, cCust, cTotal, cWhen));

        Button viewPdf = new Button(t("billing.config.migration.saved.view_pdf"));
        viewPdf.setGraphic(icon("fas-file-pdf"));
        viewPdf.setDisable(true);
        table.getSelectionModel().selectedItemProperty().addListener((o, a, b) ->
                viewPdf.setDisable(b == null || !b.hasEvidence()));
        viewPdf.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null) return;
            Task<byte[]> tk = new Task<>() {
                @Override protected byte[] call() throws Exception { return billingApiClient.getMigrationEvidence(sel.id()); }
            };
            tk.setOnSucceeded(e -> showInternalPdfViewer(tk.getValue(),
                    java.nio.file.Paths.get("prueba-migracion.pdf")));
            tk.setOnFailed(e -> showError(t("billing.config.migration.view_saved"),
                    tk.getException() == null ? "" : tk.getException().getMessage()));
            start(tk, "migration-evidence");
        });

        VBox box = new VBox(10, table, new HBox(viewPdf));
        box.setPrefWidth(700);
        dialog.getDialogPane().setContent(box);

        Task<java.util.List<com.benjagest.ui.service.BillingApiClient.BaselineEntry>> load = new Task<>() {
            @Override protected java.util.List<com.benjagest.ui.service.BillingApiClient.BaselineEntry> call() throws Exception {
                return billingApiClient.listMigrationBaselines();
            }
        };
        load.setOnSucceeded(e -> table.setItems(FXCollections.observableArrayList(load.getValue())));
        load.setOnFailed(e -> showError(t("billing.config.migration.view_saved"),
                load.getException() == null ? "" : load.getException().getMessage()));
        start(load, "migration-baselines");

        dialog.showAndWait();
    }

    /**
     * Resuelve el código de serie tecleado/elegido en la migración: si coincide
     * (sin distinguir mayúsculas) con una serie existente, la devuelve; si no,
     * devuelve una serie sintética con id=null (señal de "crear al aplicar").
     */
    private SeriesEntry resolveMigrationSeries(String code) {
        if (code == null || code.isBlank()) return null;
        String c = code.trim();
        if (migrationSeriesCombo != null) {
            for (SeriesEntry s : migrationSeriesCombo.getItems()) {
                if (s != null && c.equalsIgnoreCase(s.code())) return s;
            }
        }
        return new SeriesEntry(null, c, "STANDARD", "BY_YEAR", null, 0, null, false, true);
    }

    /**
     * MIG-2c — Trocea el número detectado (p. ej. "FRA-2026-0007") en sus
     * partes y deja que el usuario etiquete cada una: Serie / Año / Número /
     * Texto fijo. De ahí salen el código, el año, el próximo número y la
     * plantilla de formato ({CODE}-{YYYY}-{0000}) para que las próximas
     * facturas salgan idénticas. Auto-sugiere roles, pero manda el usuario.
     */
    private void buildMigrationTokenTagger(String fullNumber, String yearHint) {
        migrationTokenBox.getChildren().clear();
        migrationSegTexts = new java.util.ArrayList<>();
        migrationSegIsToken = new java.util.ArrayList<>();
        migrationRoleCombos = new java.util.ArrayList<>();
        migrationFormatTemplate = null;
        if (fullNumber == null || fullNumber.isBlank()) {
            migrationTokenBox.setVisible(false);
            migrationTokenBox.setManaged(false);
            return;
        }
        java.util.regex.Matcher m = java.util.regex.Pattern.compile("[A-Za-z0-9]+").matcher(fullNumber);
        int idx = 0;
        while (m.find()) {
            if (m.start() > idx) {
                migrationSegTexts.add(fullNumber.substring(idx, m.start()));
                migrationSegIsToken.add(false);
            }
            migrationSegTexts.add(m.group());
            migrationSegIsToken.add(true);
            idx = m.end();
        }
        if (idx < fullNumber.length()) {
            migrationSegTexts.add(fullNumber.substring(idx));
            migrationSegIsToken.add(false);
        }
        int lastTokenSeg = -1;
        for (int i = 0; i < migrationSegIsToken.size(); i++) {
            if (migrationSegIsToken.get(i)) lastTokenSeg = i;
        }
        String roleSerie = t("billing.config.migration.role.series");
        String roleYear = t("billing.config.migration.role.year");
        String roleNumber = t("billing.config.migration.role.number");
        String roleFixed = t("billing.config.migration.role.fixed");
        for (int i = 0; i < migrationSegTexts.size(); i++) {
            String text = migrationSegTexts.get(i);
            if (!migrationSegIsToken.get(i)) {
                migrationRoleCombos.add(null);
                Label sep = new Label(text);
                sep.setStyle("-fx-font-size: 18px; -fx-padding: 20 2 0 2;");
                migrationTokenBox.getChildren().add(sep);
                continue;
            }
            ComboBox<String> role = new ComboBox<>();
            role.getItems().addAll(roleSerie, roleYear, roleNumber, roleFixed);
            String suggested;
            if (i == lastTokenSeg && text.matches("\\d+")) suggested = roleNumber;
            else if (text.matches("\\d{4}") && (yearHint == null || text.equals(yearHint))) suggested = roleYear;
            else if (text.matches(".*[A-Za-z].*")) suggested = roleSerie;
            else suggested = roleFixed;
            role.setValue(suggested);
            role.valueProperty().addListener((o, a, b) -> recomputeMigrationFromTokens());
            migrationRoleCombos.add(role);
            Label tokLbl = new Label(text);
            tokLbl.setStyle("-fx-font-weight: 700;");
            VBox cell = new VBox(2, tokLbl, role);
            cell.setAlignment(Pos.CENTER_LEFT);
            migrationTokenBox.getChildren().add(cell);
        }
        migrationTokenBox.setVisible(true);
        migrationTokenBox.setManaged(true);
        recomputeMigrationFromTokens();
    }

    /** Recalcula código/año/nº/plantilla a partir de las etiquetas del troceador. */
    private void recomputeMigrationFromTokens() {
        if (migrationSegTexts == null) return;
        String roleSerie = t("billing.config.migration.role.series");
        String roleYear = t("billing.config.migration.role.year");
        String roleNumber = t("billing.config.migration.role.number");
        StringBuilder tpl = new StringBuilder();
        String code = null;
        String year = null;
        Integer number = null;
        boolean codeUsed = false;
        for (int i = 0; i < migrationSegTexts.size(); i++) {
            String text = migrationSegTexts.get(i);
            if (!migrationSegIsToken.get(i)) { tpl.append(text); continue; }
            ComboBox<String> role = migrationRoleCombos.get(i);
            String r = role == null ? null : role.getValue();
            if (roleSerie.equals(r)) {
                if (!codeUsed) { tpl.append("{CODE}"); code = text; codeUsed = true; }
                else tpl.append(text);
            } else if (roleYear.equals(r)) {
                tpl.append("{YYYY}");
                year = text;
            } else if (roleNumber.equals(r)) {
                tpl.append("{").append("0".repeat(Math.max(1, text.length()))).append("}");
                try { number = Integer.parseInt(text); } catch (NumberFormatException ignored) { }
            } else {
                tpl.append(text);
            }
        }
        migrationFormatTemplate = tpl.toString();
        if (code != null && migrationSeriesCombo.getEditor() != null) {
            migrationSeriesCombo.getEditor().setText(code);
        }
        if (year != null) migrationYearField.setText(year);
        if (number != null) migrationNextNumberField.setText(String.valueOf(number + 1));
    }

    // ----- Editor de series (crear/editar) -----

    /**
     * Dialogo modal de creacion/edicion de una serie. El proximo numero
     * solo es editable en CREATE (en UPDATE el backend lo rechaza para
     * no abrir agujero legal — si necesitas mover el correlativo usa
     * Migracion desde otro programa). El backend tambien bloquea cambios
     * de code/format/kind cuando la serie ya emitio facturas validadas
     * este ano.
     */
    private void showSeriesEditor(SeriesEntry existing) {
        Dialog<Boolean> dialog = new Dialog<>();
        dialog.setTitle(existing == null ? t("billing.series.editor.title.create") : t("billing.series.editor.title.edit"));
        dialog.setHeaderText(null);

        TextField codeField = new TextField(existing == null ? "" : existing.code());
        codeField.setPromptText(t("billing.series.editor.code.prompt"));
        codeField.getStyleClass().add("form-input");

        // Tipo factura: fijo a STANDARD (el usuario solo define su serie
        // de facturas normales). Las PROF/RECT las gestiona el sistema.
        Label kindFixedLabel = new Label(t("billing.series.editor.kind.fixed"));
        kindFixedLabel.getStyleClass().add("invoice-pill");

        ComboBox<String> numberingCombo = new ComboBox<>();
        numberingCombo.getItems().addAll("STANDARD", "BY_YEAR", "PREFIXED");
        localizeEnumCombo(numberingCombo, "numbering");
        numberingCombo.getSelectionModel().select(existing == null ? "BY_YEAR" : existing.numberingType());
        numberingCombo.getStyleClass().add("form-input");

        TextField formatField = new TextField(existing == null
                ? "{CODE}-{YYYY}-{0000}"
                : (existing.formatTemplate() == null ? "" : existing.formatTemplate()));
        formatField.setPromptText(t("billing.series.editor.format.prompt"));
        formatField.getStyleClass().add("form-input");

        TextField nextNumberField = new TextField(existing == null ? "1" : String.valueOf(existing.nextNumber()));
        nextNumberField.getStyleClass().add("form-input");
        nextNumberField.setDisable(existing != null);

        Label nextNumberHint = new Label(existing == null
                ? t("billing.series.editor.next.hint.create")
                : t("billing.series.editor.next.hint.edit"));
        nextNumberHint.setWrapText(true);
        nextNumberHint.getStyleClass().add("settings-hint");

        Label autoLockHint = new Label(t("billing.series.editor.autolock.hint"));
        autoLockHint.setWrapText(true);
        autoLockHint.getStyleClass().add("settings-hint");

        GridPane grid = formGrid();
        addFormRow(grid, 0, t("billing.series.editor.field.code"), codeField);
        addFormRow(grid, 1, t("billing.series.editor.field.kind"), kindFixedLabel);
        addFormRow(grid, 2, t("billing.series.editor.field.numbering"), numberingCombo);
        addFormRow(grid, 3, t("billing.series.editor.field.format"), formatField);
        addFormRow(grid, 4, t("billing.series.editor.field.next"), nextNumberField);

        VBox dialogBody = new VBox(12, grid, nextNumberHint, autoLockHint);
        dialogBody.setPadding(new Insets(8));
        installDialog(dialog, dialogBody);

        ButtonType saveBtn = new ButtonType(existing == null ? t("billing.series.editor.btn.create") : t("billing.series.editor.btn.save"), ButtonBar.ButtonData.OK_DONE);
        dialog.getDialogPane().getButtonTypes().addAll(saveBtn, ButtonType.CANCEL);

        // Validacion local antes de cerrar el dialogo: codigo no vacio
        // y, si es CREATE, proximo numero entero >= 1.
        Node saveButton = dialog.getDialogPane().lookupButton(saveBtn);
        saveButton.addEventFilter(javafx.event.ActionEvent.ACTION, ev -> {
            if (codeField.getText().trim().isBlank()) {
                ev.consume();
                showError(t("billing.series.editor.error.no_code.title"), t("billing.series.editor.error.no_code.body"));
                return;
            }
            if (existing == null) {
                try {
                    int n = Integer.parseInt(nextNumberField.getText().trim());
                    if (n < 1) throw new NumberFormatException();
                } catch (NumberFormatException ex) {
                    ev.consume();
                    showError(t("billing.series.editor.error.bad_number.title"), t("billing.series.editor.error.bad_number.body"));
                }
            }
        });

        dialog.setResultConverter(bt -> bt == saveBtn);
        Optional<Boolean> result = dialog.showAndWait();
        if (result.isEmpty() || !result.get()) {
            return;
        }

        String code = codeField.getText().trim();
        String kind = "STANDARD"; // El usuario solo define su STANDARD.
        String numbering = numberingCombo.getValue();
        String format = formatField.getText();
        // El locked desaparece del editor: se infiere de las emisiones
        // (countValidatedInYear > 0 → no editable). Asi por convencion.
        Integer initialNext = null;
        if (existing == null) {
            try {
                initialNext = Integer.parseInt(nextNumberField.getText().trim());
            } catch (NumberFormatException ignored) {
                return;
            }
        }
        final Integer finalInitialNext = initialNext;

        Task<SeriesEntry> task = new Task<>() {
            @Override
            protected SeriesEntry call() throws Exception {
                if (existing == null) {
                    return billingApiClient.createSeries(code, kind, numbering, format, finalInitialNext, false);
                }
                return billingApiClient.updateSeries(existing.id(), code, kind, numbering, format, false);
            }
        };
        task.setOnSucceeded(ev -> {
            // Refrescamos toda la pantalla de Facturacion para que tanto el
            // listado de series como el combo del editor de facturas vean
            // la serie nueva/actualizada inmediatamente. Aterrizamos en la
            // pestaña Configuracion para que el usuario vea su cambio
            // reflejado sin tener que cambiar de tab.
            pendingBillingTab = "config";
            billingRefresh.run();
        });
        task.setOnFailed(ev -> showError(
                existing == null ? t("billing.series.editor.fail.create.title") : t("billing.series.editor.fail.save.title"),
                t("billing.series.editor.fail.body")));
        start(task, "billing-series-save");
    }

    /**
     * Rellena los textos legales VACÍOS con redacciones estándar que citan la
     * ley aplicable (editables después). No machaca lo que el usuario ya haya
     * escrito. Contenido en español (la factura española es en español).
     */
    private void loadStandardLegalTexts() {
        fillIfBlank(textExemptArea,
                "Operación exenta del IVA conforme al artículo 20 de la Ley 37/1992, de 28 de "
                + "diciembre, del Impuesto sobre el Valor Añadido.");
        fillIfBlank(textReverseChargeArea,
                "Operación con inversión del sujeto pasivo (artículo 84.Uno.2º de la Ley 37/1992 "
                + "del IVA). Esta factura no incluye IVA; su autoliquidación corresponde al destinatario.");
        fillIfBlank(textReducedVatArea,
                "Tipo impositivo reducido aplicado conforme al artículo 91 de la Ley 37/1992 del IVA.");
        fillIfBlank(textRectifyingArea,
                "Factura rectificativa expedida conforme al artículo 15 del Real Decreto 1619/2012, "
                + "por el que se aprueba el Reglamento que regula las obligaciones de facturación.");
        fillIfBlank(textLegalTermsArea,
                "El impago a su vencimiento devengará intereses de demora conforme a la Ley 3/2004, "
                + "de 29 de diciembre, de lucha contra la morosidad en las operaciones comerciales.");
        fillIfBlank(textPieArea,
                "En cumplimiento del Reglamento (UE) 2016/679 (RGPD) y la Ley Orgánica 3/2018 "
                + "(LOPDGDD), los datos personales se tratan para la gestión de la relación comercial. "
                + "Puede ejercer sus derechos dirigiéndose a la dirección de la empresa.");
        toast(root == null || root.getScene() == null ? null : root.getScene().getWindow(),
                t("billing.config.texts.load_standard.done"));
    }

    private void fillIfBlank(javafx.scene.control.TextArea area, String standard) {
        if (area != null && (area.getText() == null || area.getText().isBlank())) {
            area.setText(standard);
        }
    }

    private void saveInvoiceTexts() {
        InvoiceTexts payload = new InvoiceTexts(
                textPieArea.getText(),
                textExemptArea.getText(),
                textReverseChargeArea.getText(),
                textReducedVatArea.getText(),
                textRectifyingArea.getText(),
                textLegalTermsArea.getText(),
                showIbanCheck.isSelected()
        );
        Task<InvoiceTexts> task = new Task<>() {
            @Override
            protected InvoiceTexts call() throws Exception {
                return billingApiClient.updateInvoiceTexts(payload);
            }
        };
        task.setOnSucceeded(event -> {
            Alert ok = new Alert(Alert.AlertType.INFORMATION,
                    t("billing.texts.save.success"), ButtonType.OK);
            ok.setHeaderText(null);
            ok.showAndWait();
        });
        task.setOnFailed(event -> showError(t("billing.texts.save.fail.title"),
                t("billing.texts.save.fail.body")));
        start(task, "billing-texts-save");
    }

