    // Mapas de Label por fila para las columnas calculadas (Subtotal/Total
    // de cada linea). Los rellena la cellFactory cuando bindea, los lee el
    // listener del decimalColumn al teclear. Asi actualizamos los importes
    // visibles de la linea SIN llamar a editorLinesTable.refresh() (que
    // pierde el foco del TextField que estaba editando). IdentityHashMap
    // porque la clave es el objeto fila por identidad, no por equals.
    private final java.util.Map<InvoiceLineDraft, Label> rowSubtotalLabels = new java.util.IdentityHashMap<>();
    private final java.util.Map<InvoiceLineDraft, Label> rowLineTotalLabels = new java.util.IdentityHashMap<>();

    /**
     * MULTI-ALLOCATION — dialog para registrar un pago real que se
     * reparte entre 1..N facturas VALIDATED pendientes del mismo cliente.
     */
    private void showMultiAllocationDialog() {
        Stage dlg = new Stage();
        dlg.setTitle(t("multi_alloc.title"));
        dlg.initModality(javafx.stage.Modality.APPLICATION_MODAL);

        Label hint = new Label(t("multi_alloc.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        Label clientLbl = label(t("multi_alloc.field.client"), "form-label");
        javafx.scene.control.ComboBox<String> clientCombo = new javafx.scene.control.ComboBox<>();
        clientCombo.getStyleClass().add("form-input");
        clientCombo.setPrefWidth(300);

        TableView<MultiAllocRow> table = new TableView<>();
        table.getStyleClass().add("data-table");
        table.setEditable(true);
        table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        table.setPlaceholder(new Label(t("multi_alloc.empty")));
        table.setPrefHeight(260);

        TableColumn<MultiAllocRow, Boolean> colSel = new TableColumn<>(t("multi_alloc.col.pay"));
        colSel.setCellValueFactory(c -> c.getValue().selectedProperty);
        colSel.setCellFactory(javafx.scene.control.cell.CheckBoxTableCell.forTableColumn(colSel));
        colSel.setEditable(true);
        colSel.setPrefWidth(60);

        TableColumn<MultiAllocRow, String> colNum = new TableColumn<>(t("multi_alloc.col.invoice"));
        colNum.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().invoiceNumber));
        colNum.setPrefWidth(130);

        TableColumn<MultiAllocRow, String> colDate = new TableColumn<>(t("multi_alloc.col.date"));
        colDate.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().invoiceDate));
        colDate.setComparator(ISO_DATE_COMPARATOR);
        colDate.setPrefWidth(110);

        TableColumn<MultiAllocRow, String> colTotal = new TableColumn<>(t("multi_alloc.col.total"));
        colTotal.setCellValueFactory(c -> new SimpleStringProperty(money(c.getValue().total.toPlainString())));
        colTotal.setPrefWidth(120);
        colTotal.setComparator(NUMERIC_STRING_COMPARATOR);

        TableColumn<MultiAllocRow, String> colPending = new TableColumn<>(t("multi_alloc.col.pending"));
        colPending.setCellValueFactory(c -> new SimpleStringProperty(money(c.getValue().pending.toPlainString())));
        colPending.setPrefWidth(120);
        colPending.setComparator(NUMERIC_STRING_COMPARATOR);

        // Columna de reparto: SOLO LECTURA. El importe asignado a cada factura lo
        // calcula el dialogo a partir del importe del pago + la factura elegida
        // para completar (no se teclea a mano, evita cuadres manuales).
        TableColumn<MultiAllocRow, String> colAmount = new TableColumn<>(t("multi_alloc.col.allocate"));
        colAmount.setCellValueFactory(c -> c.getValue().amountTextProperty);
        colAmount.setCellFactory(col -> new javafx.scene.control.TableCell<>() {
            @Override
            protected void updateItem(String v, boolean empty) {
                super.updateItem(v, empty);
                if (empty || v == null) { setText(null); return; }
                try { setText(money(new BigDecimal(v.replace(",", ".")).toPlainString())); }
                catch (NumberFormatException e) { setText(v); }
            }
        });
        colAmount.setComparator(NUMERIC_STRING_COMPARATOR);
        colAmount.setPrefWidth(140);

        table.getColumns().addAll(List.of(colSel, colNum, colDate, colTotal, colPending, colAmount));

        Label totalLbl = label(t("multi_alloc.field.total"), "form-label");
        TextField totalField = new TextField();
        totalField.getStyleClass().add("form-input");
        totalField.setPromptText("0,00");

        Label dateLbl = label(t("multi_alloc.field.date"), "form-label");
        javafx.scene.control.DatePicker datePicker = new javafx.scene.control.DatePicker(LocalDate.now());

        Label methodLbl = label(t("multi_alloc.field.method"), "form-label");
        javafx.scene.control.ComboBox<String> methodCombo = new javafx.scene.control.ComboBox<>();
        methodCombo.getItems().addAll("BANK_TRANSFER", "CASH", "CARD", "CHECK", "DIRECT_DEBIT", "OTHER");
        localizeEnumCombo(methodCombo, "payment_method");
        methodCombo.getSelectionModel().selectFirst();
        methodCombo.getStyleClass().add("form-input");

        Label refLbl = label(t("multi_alloc.field.reference"), "form-label");
        TextField refField = new TextField();
        refField.getStyleClass().add("form-input");

        Label notesLbl = label(t("multi_alloc.field.notes"), "form-label");
        TextField notesField = new TextField();
        notesField.getStyleClass().add("form-input");

        Label sumLbl = new Label("");
        sumLbl.getStyleClass().add("settings-hint");

        Runnable recalcSum = () -> {
            BigDecimal sum = BigDecimal.ZERO;
            for (MultiAllocRow r : table.getItems()) {
                if (!r.selectedProperty.get()) continue;
                try {
                    sum = sum.add(new BigDecimal(
                            r.amountTextProperty.get().replace(",", ".")));
                } catch (NumberFormatException ignored) { /* skip */ }
            }
            sumLbl.setText(t("multi_alloc.field.selected_sum") + " "
                    + money(sum.toPlainString()));
        };
        table.itemsProperty().addListener((obs, o, n) -> recalcSum.run());

        // Cargar facturas pendientes
        Task<List<SalesInvoiceSummary>> load = new Task<>() {
            @Override
            protected List<SalesInvoiceSummary> call() throws Exception {
                List<SalesInvoiceSummary> a = billingApiClient.listInvoices(
                        "VALIDATED", "PENDING", null, 500);
                List<SalesInvoiceSummary> b = billingApiClient.listInvoices(
                        "VALIDATED", "PARTIAL", null, 500);
                List<SalesInvoiceSummary> out = new ArrayList<>();
                out.addAll(a); out.addAll(b);
                return out;
            }
        };
        load.setOnSucceeded(ev -> {
            List<SalesInvoiceSummary> all = load.getValue();
            java.util.TreeSet<String> clients = new java.util.TreeSet<>();
            for (SalesInvoiceSummary inv : all) {
                if (inv.customerLegalName() != null) clients.add(inv.customerLegalName());
            }
            clientCombo.getItems().setAll(clients);
            clientCombo.setOnAction(av -> {
                String sel = clientCombo.getValue();
                if (sel == null) return;
                List<MultiAllocRow> rows = new ArrayList<>();
                for (SalesInvoiceSummary inv : all) {
                    if (!sel.equals(inv.customerLegalName())) continue;
                    BigDecimal total = inv.total() == null ? BigDecimal.ZERO : inv.total();
                    BigDecimal paid = inv.paidAmount() == null ? BigDecimal.ZERO : inv.paidAmount();
                    BigDecimal pending = total.subtract(paid);
                    if (pending.signum() <= 0) continue;
                    MultiAllocRow r = new MultiAllocRow();
                    r.invoiceId = inv.id();
                    r.invoiceNumber = inv.invoiceNumber();
                    r.invoiceDate = inv.invoiceDate();
                    r.total = total;
                    r.pending = pending;
                    r.amountTextProperty.set(pending.toPlainString());
                    r.selectedProperty.addListener((o2, oV, nV) -> recalcSum.run());
                    r.amountTextProperty.addListener((o2, oV, nV) -> recalcSum.run());
                    rows.add(r);
                }
                table.setItems(FXCollections.observableArrayList(rows));
                recalcSum.run();
            });
            if (!clients.isEmpty()) {
                clientCombo.getSelectionModel().selectFirst();
                clientCombo.fireEvent(new javafx.event.ActionEvent());
            }
        });
        load.setOnFailed(ev -> showError(t("multi_alloc.load.fail"),
                load.getException() == null ? "" : load.getException().getMessage()));
        start(load, "multi-alloc-load");

        Button confirm = new Button(t("multi_alloc.btn.confirm"));
        confirm.setGraphic(icon("fas-check"));
        confirm.getStyleClass().add("primary-button");
        confirm.setOnAction(ev -> {
            BigDecimal payment;
            try {
                payment = new BigDecimal(totalField.getText().replace(",", "."));
                if (payment.signum() <= 0) throw new NumberFormatException();
            } catch (Exception ex) {
                showError(t("multi_alloc.error.title"), t("multi_alloc.error.total")); return;
            }
            final BigDecimal fPayment = payment.setScale(2, java.math.RoundingMode.HALF_UP);
            final LocalDate date = datePicker.getValue();
            if (date == null) {
                showError(t("multi_alloc.error.title"), t("multi_alloc.error.date")); return;
            }
            // Facturas marcadas (las que entran en el pago).
            List<MultiAllocRow> checked = new ArrayList<>();
            for (MultiAllocRow r : table.getItems()) {
                if (r.selectedProperty.get()) checked.add(r);
            }
            if (checked.isEmpty()) {
                showError(t("multi_alloc.error.title"), t("multi_alloc.error.no_rows")); return;
            }
            BigDecimal pendingSum = BigDecimal.ZERO;
            for (MultiAllocRow r : checked) pendingSum = pendingSum.add(r.pending);
            pendingSum = pendingSum.setScale(2, java.math.RoundingMode.HALF_UP);

            // No se puede cobrar mas de lo que se debe.
            if (fPayment.compareTo(pendingSum) > 0) {
                showError(t("multi_alloc.error.title"),
                        t("multi_alloc.error.exceeds_selected")
                        + " (" + money(fPayment.toPlainString()) + " > "
                        + money(pendingSum.toPlainString()) + ")");
                return;
            }

            // Helper: envia un reparto concreto al backend.
            java.util.function.Consumer<List<com.benjagest.ui.service.BillingApiClient.AllocationDraft>> doSave = allocs -> {
                if (allocs.isEmpty()) {
                    showError(t("multi_alloc.error.title"), t("multi_alloc.error.no_rows")); return;
                }
                Task<String> save = new Task<>() {
                    @Override
                    protected String call() throws Exception {
                        return billingApiClient.registerMultiAllocation(
                                date.toString(), fPayment,
                                methodCombo.getValue(), refField.getText(), notesField.getText(),
                                allocs);
                    }
                };
                save.setOnSucceeded(s -> {
                    showInfo(t("multi_alloc.ok.title"),
                            t("multi_alloc.ok.body") + " " + allocs.size());
                    com.benjagest.ui.support.RefreshBus.emit(
                            com.benjagest.ui.support.RefreshBus.TOPIC_SALES);
                    dlg.close();
                });
                save.setOnFailed(s -> showError(t("multi_alloc.save.fail"),
                        save.getException() == null ? "" : save.getException().getMessage()));
                start(save, "multi-alloc-save");
            };

            if (fPayment.compareTo(pendingSum) == 0) {
                // El pago cubre exactamente el pendiente de TODAS: se pagan enteras.
                List<com.benjagest.ui.service.BillingApiClient.AllocationDraft> allocs = new ArrayList<>();
                for (MultiAllocRow r : checked) {
                    allocs.add(new com.benjagest.ui.service.BillingApiClient.AllocationDraft(
                            r.invoiceId, r.pending.setScale(2, java.math.RoundingMode.HALF_UP)));
                }
                doSave.accept(allocs);
                return;
            }

            // payment < pendingSum -> el pago no llega a todas: preguntar cuales completar.
            askWhichInvoicesToComplete(checked, fPayment, toComplete -> {
                List<com.benjagest.ui.service.BillingApiClient.AllocationDraft> allocs =
                        distributePayment(checked, toComplete, fPayment);
                // Reflejar el reparto en la tabla antes de enviar (transparencia).
                java.util.Map<String, BigDecimal> byId = new java.util.HashMap<>();
                for (var a : allocs) byId.put(a.invoiceId(), a.amount());
                for (MultiAllocRow r : table.getItems()) {
                    BigDecimal a = byId.get(r.invoiceId);
                    if (a == null) {
                        r.selectedProperty.set(false);
                        r.amountTextProperty.set("0");
                    } else {
                        r.selectedProperty.set(true);
                        r.amountTextProperty.set(a.toPlainString());
                    }
                }
                recalcSum.run();
                doSave.accept(allocs);
            });
        });

        Button cancel = new Button(t("dialog.cancel"));
        cancel.setOnAction(ev -> dlg.close());

        HBox btns = new HBox(10, cancel, confirm);
        btns.setAlignment(Pos.CENTER_RIGHT);

        javafx.scene.layout.GridPane grid = new javafx.scene.layout.GridPane();
        grid.setHgap(10); grid.setVgap(8);
        grid.add(clientLbl, 0, 0); grid.add(clientCombo, 1, 0);
        grid.add(dateLbl, 0, 1); grid.add(datePicker, 1, 1);
        grid.add(totalLbl, 0, 2); grid.add(totalField, 1, 2);
        grid.add(methodLbl, 0, 3); grid.add(methodCombo, 1, 3);
        grid.add(refLbl, 0, 4); grid.add(refField, 1, 4);
        grid.add(notesLbl, 0, 5); grid.add(notesField, 1, 5);

        VBox root = new VBox(12, hint, grid, table, sumLbl, btns);
        root.setPadding(new javafx.geometry.Insets(16));
        root.setPrefWidth(900);
        Scene scene = new Scene(root);
        scene.getStylesheets().add(
                getClass().getResource("/com/benjagest/ui/app.css").toExternalForm());
        com.benjagest.ui.support.EditableCells.enableDateMaskOnFocus(scene);
        dlg.setScene(scene);
        dlg.showAndWait();
    }

    /**
     * MULTI-ALLOCATION — cuando el importe del pago no cubre el pendiente de
     * todas las facturas marcadas, pregunta CUALES se quieren COMPLETAR (pagar
     * enteras). Se pueden marcar varias mientras su suma no supere el pago; el
     * resto del importe se reparte luego en {@link #distributePayment} de mas
     * antigua a mas nueva, y lo que falte queda pendiente (PARTIAL).
     */
    private void askWhichInvoicesToComplete(
            List<MultiAllocRow> checked,
            BigDecimal payment,
            java.util.function.Consumer<List<MultiAllocRow>> onConfirm) {
        Stage dlg = new Stage();
        dlg.setTitle(t("multi_alloc.complete.title"));
        dlg.initModality(javafx.stage.Modality.APPLICATION_MODAL);

        Label hint = new Label(t("multi_alloc.complete.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        // Mas antigua primero (coherente con el reparto del resto).
        List<MultiAllocRow> ordered = new ArrayList<>(checked);
        ordered.sort(java.util.Comparator.comparing(r -> r.invoiceDate == null ? "" : r.invoiceDate));

        java.util.List<javafx.scene.control.CheckBox> boxes = new ArrayList<>();
        VBox options = new VBox(8);
        // Preseleccion greedy: marca las mas antiguas mientras quepan en el pago.
        BigDecimal acc = BigDecimal.ZERO;
        for (MultiAllocRow r : ordered) {
            javafx.scene.control.CheckBox cb = new javafx.scene.control.CheckBox(
                    r.invoiceNumber + "   ·   " + t("multi_alloc.col.pending") + " "
                    + money(r.pending.toPlainString()));
            cb.setUserData(r);
            if (acc.add(r.pending).compareTo(payment) <= 0) {
                cb.setSelected(true);
                acc = acc.add(r.pending);
            }
            boxes.add(cb);
            options.getChildren().add(cb);
        }

        Label tally = new Label();
        tally.getStyleClass().add("settings-hint");
        Runnable refreshTally = () -> {
            BigDecimal sum = BigDecimal.ZERO;
            for (var cb : boxes) if (cb.isSelected())
                sum = sum.add(((MultiAllocRow) cb.getUserData()).pending);
            BigDecimal rest = payment.subtract(sum);
            tally.setText(t("multi_alloc.complete.tally")
                    .replace("{done}", money(sum.toPlainString()))
                    .replace("{pay}", money(payment.toPlainString()))
                    .replace("{rest}", money(rest.max(BigDecimal.ZERO).toPlainString())));
            // Rojo si lo marcado para completar supera el importe del pago.
            tally.setStyle(sum.compareTo(payment) > 0 ? "-fx-text-fill: #c0392b;" : "");
        };
        for (var cb : boxes) cb.selectedProperty().addListener((o, ov, nv) -> refreshTally.run());
        refreshTally.run();

        Button ok = new Button(t("multi_alloc.complete.btn"));
        ok.setGraphic(icon("fas-check"));
        ok.getStyleClass().add("primary-button");
        ok.setOnAction(e -> {
            List<MultiAllocRow> toComplete = new ArrayList<>();
            BigDecimal sum = BigDecimal.ZERO;
            for (var cb : boxes) if (cb.isSelected()) {
                MultiAllocRow r = (MultiAllocRow) cb.getUserData();
                toComplete.add(r);
                sum = sum.add(r.pending);
            }
            if (sum.compareTo(payment) > 0) {
                showError(t("multi_alloc.error.title"),
                        t("multi_alloc.complete.too_much")
                        + " (" + money(sum.toPlainString()) + " > " + money(payment.toPlainString()) + ")");
                return;
            }
            dlg.close();
            onConfirm.accept(toComplete);
        });
        Button cancel = new Button(t("dialog.cancel"));
        cancel.setOnAction(e -> dlg.close());
        HBox btns = new HBox(10, cancel, ok);
        btns.setAlignment(Pos.CENTER_RIGHT);

        VBox root = new VBox(12, hint, options, tally, btns);
        root.setPadding(new javafx.geometry.Insets(16));
        root.setPrefWidth(560);
        Scene scene = new Scene(root);
        scene.getStylesheets().add(
                getClass().getResource("/com/benjagest/ui/app.css").toExternalForm());
        dlg.setScene(scene);
        dlg.showAndWait();
    }

    /**
     * Reparte {@code payment} entre las facturas seleccionadas: primero las
     * marcadas para COMPLETAR (enteras; su suma ya se validó &le; payment), luego
     * el resto del importe a las demas de mas antigua a mas nueva. Lo que no
     * llegue queda con menos de su pendiente (PARTIAL) o sin pago (sigue pendiente).
     */
    private static List<com.benjagest.ui.service.BillingApiClient.AllocationDraft> distributePayment(
            List<MultiAllocRow> selected, List<MultiAllocRow> toComplete, BigDecimal payment) {
        java.util.Comparator<MultiAllocRow> byDate =
                java.util.Comparator.comparing(r -> r.invoiceDate == null ? "" : r.invoiceDate);
        java.util.Set<MultiAllocRow> completeSet = new java.util.HashSet<>(toComplete);
        List<com.benjagest.ui.service.BillingApiClient.AllocationDraft> allocs = new ArrayList<>();
        BigDecimal remaining = payment;
        // 1) Las marcadas para completar: enteras (de mas antigua a mas nueva).
        List<MultiAllocRow> completeOrdered = new ArrayList<>(toComplete);
        completeOrdered.sort(byDate);
        for (MultiAllocRow r : completeOrdered) {
            BigDecimal a = r.pending.min(remaining);
            if (a.signum() <= 0) continue;
            allocs.add(new com.benjagest.ui.service.BillingApiClient.AllocationDraft(
                    r.invoiceId, a.setScale(2, java.math.RoundingMode.HALF_UP)));
            remaining = remaining.subtract(a);
        }
        // 2) El resto del importe, a las NO completadas, de mas antigua a mas nueva.
        List<MultiAllocRow> others = new ArrayList<>();
        for (MultiAllocRow r : selected) if (!completeSet.contains(r)) others.add(r);
        others.sort(byDate);
        for (MultiAllocRow r : others) {
            if (remaining.signum() <= 0) break;
            BigDecimal a = r.pending.min(remaining);
            if (a.signum() <= 0) continue;
            allocs.add(new com.benjagest.ui.service.BillingApiClient.AllocationDraft(
                    r.invoiceId, a.setScale(2, java.math.RoundingMode.HALF_UP)));
            remaining = remaining.subtract(a);
        }
        return allocs;
    }

    private static class MultiAllocRow {
        String invoiceId, invoiceNumber, invoiceDate;
        BigDecimal total = BigDecimal.ZERO;
        BigDecimal pending = BigDecimal.ZERO;
        // Las facturas arrancan DESMARCADAS — el asesor elige cuales
        // entran en el pago. Si fuera por defecto true, el usuario
        // tendria que desmarcar las que no quiere y se llevaria la
        // sensacion de "no me deja marcar varias" al pulsar la 1ª
        // (que en realidad se estaria desmarcando).
        final javafx.beans.property.SimpleBooleanProperty selectedProperty =
                new javafx.beans.property.SimpleBooleanProperty(false);
        final javafx.beans.property.SimpleStringProperty amountTextProperty =
                new javafx.beans.property.SimpleStringProperty("0");
    }

    /**
     * REC-BANCARIA — dialogo con sugerencias de match entre
     * movimientos bancarios no conciliados y facturas pendientes.
     */
    private void showBankReconciliationDialog() {
        Stage dlg = new Stage();
        dlg.setTitle(t("bank_rec.title"));
        dlg.initModality(javafx.stage.Modality.APPLICATION_MODAL);

        Label hint = new Label(t("bank_rec.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        TableView<com.benjagest.ui.service.AltaApiClient.BankSuggestionEntry> table = new TableView<>();
        table.getStyleClass().add("data-table");
        table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        table.setPlaceholder(new Label(t("bank_rec.empty")));
        VBox.setVgrow(table, Priority.ALWAYS);

        TableColumn<com.benjagest.ui.service.AltaApiClient.BankSuggestionEntry, String> colDate =
                new TableColumn<>(t("bank_rec.col.date"));
        colDate.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().operationDate()));
        colDate.setPrefWidth(110);
        colDate.setComparator(ISO_DATE_COMPARATOR);

        TableColumn<com.benjagest.ui.service.AltaApiClient.BankSuggestionEntry, String> colDesc =
                new TableColumn<>(t("bank_rec.col.movement"));
        colDesc.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().description()));
        colDesc.setPrefWidth(260);

        TableColumn<com.benjagest.ui.service.AltaApiClient.BankSuggestionEntry, String> colAmount =
                new TableColumn<>(t("bank_rec.col.amount"));
        colAmount.setCellValueFactory(c -> new SimpleStringProperty(money(c.getValue().amount().toPlainString())));
        colAmount.setPrefWidth(110);
        colAmount.setComparator(NUMERIC_STRING_COMPARATOR);

        TableColumn<com.benjagest.ui.service.AltaApiClient.BankSuggestionEntry, String> colInv =
                new TableColumn<>(t("bank_rec.col.invoice"));
        colInv.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().invoiceNumber()));
        colInv.setPrefWidth(120);

        TableColumn<com.benjagest.ui.service.AltaApiClient.BankSuggestionEntry, String> colCust =
                new TableColumn<>(t("bank_rec.col.customer"));
        colCust.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().customerLegalName()));
        colCust.setPrefWidth(220);

        TableColumn<com.benjagest.ui.service.AltaApiClient.BankSuggestionEntry, String> colScore =
                new TableColumn<>(t("bank_rec.col.score"));
        colScore.setCellValueFactory(c -> new SimpleStringProperty(
                String.format("%.0f%%", c.getValue().score() * 100)));
        colScore.setPrefWidth(80);
        colScore.setComparator(NUMERIC_STRING_COMPARATOR);

        table.getColumns().addAll(List.of(colDate, colDesc, colAmount, colInv, colCust, colScore));

        Runnable load = () -> {
            Task<List<com.benjagest.ui.service.AltaApiClient.BankSuggestionEntry>> task = new Task<>() {
                @Override
                protected List<com.benjagest.ui.service.AltaApiClient.BankSuggestionEntry> call() throws Exception {
                    return altaApiClient.listBankSuggestions();
                }
            };
            task.setOnSucceeded(ev -> table.setItems(FXCollections.observableArrayList(task.getValue())));
            task.setOnFailed(ev -> showError(t("bank_rec.load.fail"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "bank-rec-load");
        };

        Button refresh = new Button(t("bank_rec.btn.refresh"));
        refresh.setGraphic(icon("fas-sync-alt"));
        refresh.setOnAction(ev -> load.run());

        Button accept = new Button(t("bank_rec.btn.accept"));
        accept.setGraphic(icon("fas-check"));
        accept.getStyleClass().add("primary-button");
        accept.setDisable(true);
        accept.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null) return;
            Task<Void> task = new Task<>() {
                @Override
                protected Void call() throws Exception {
                    altaApiClient.linkBankMovement(sel.movementId(), sel.invoiceId());
                    return null;
                }
            };
            task.setOnSucceeded(s -> {
                load.run();
                // REFRESH-AUDIT — conciliar crea asiento (journal_entries) y marca
                // la factura cobrada: avisar a Contabilidad, bancos y facturas.
                com.benjagest.ui.support.RefreshBus.emit(
                        com.benjagest.ui.support.RefreshBus.TOPIC_JOURNAL,
                        com.benjagest.ui.support.RefreshBus.TOPIC_BANK_ACCOUNTS,
                        com.benjagest.ui.support.RefreshBus.TOPIC_SALES,
                        com.benjagest.ui.support.RefreshBus.TOPIC_PURCHASES);
            });
            task.setOnFailed(s -> showError(t("bank_rec.accept.fail"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "bank-rec-link");
        });

        Button ignoreBtn = new Button(t("bank_rec.btn.ignore"));
        ignoreBtn.setGraphic(icon("fas-times"));
        ignoreBtn.setDisable(true);
        ignoreBtn.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null) return;
            Task<Void> task = new Task<>() {
                @Override
                protected Void call() throws Exception {
                    altaApiClient.ignoreBankMovement(sel.movementId(), "user-ignored-from-rec-ui");
                    return null;
                }
            };
            task.setOnSucceeded(s -> {
                load.run();
                com.benjagest.ui.support.RefreshBus.emit(
                        com.benjagest.ui.support.RefreshBus.TOPIC_BANK_ACCOUNTS);
            });
            task.setOnFailed(s -> showError(t("bank_rec.ignore.fail"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "bank-rec-ignore");
        });

        table.getSelectionModel().selectedItemProperty().addListener((obs, o, n) -> {
            accept.setDisable(n == null);
            ignoreBtn.setDisable(n == null);
        });

        Button close = new Button(t("dialog.close"));
        close.setOnAction(ev -> dlg.close());

        HBox btns = new HBox(10, refresh, accept, ignoreBtn);
        btns.setAlignment(Pos.CENTER_LEFT);
        HBox closeRow = new HBox(close);
        closeRow.setAlignment(Pos.CENTER_RIGHT);

        load.run();

        VBox root = new VBox(12, hint, btns, table, closeRow);
        root.setPadding(new javafx.geometry.Insets(16));
        root.setPrefSize(1000, 600);
        Scene scene = new Scene(root);
        scene.getStylesheets().add(
                getClass().getResource("/com/benjagest/ui/app.css").toExternalForm());
        com.benjagest.ui.support.EditableCells.enableDateMaskOnFocus(scene);
        dlg.setScene(scene);
        dlg.showAndWait();
    }

    private void showInvoiceEditor(String existingInvoiceId) {
        recordNav(() -> showInvoiceEditor(existingInvoiceId));
        // TIPO-IVA-CLIENTE: cada apertura del editor parte de 21/0 hasta que se
        // elija cliente (si no, conservaríamos el tipo del cliente anterior).
        editorDefaultVat = new java.math.BigDecimal("21");
        editorDefaultRetention = java.math.BigDecimal.ZERO;
        Task<EditorBundle> task = new Task<>() {
            @Override
            protected EditorBundle call() throws Exception {
                List<CustomerSummary> customers = customerApiClient.list();
                List<SeriesEntry> series = billingApiClient.listSeries();
                SalesInvoiceSummary existing = null;
                List<InvoiceLineDraft> lines = new java.util.ArrayList<>();
                if (existingInvoiceId != null) {
                    existing = billingApiClient.getInvoiceById(existingInvoiceId);
                    lines = billingApiClient.getInvoiceLines(existingInvoiceId);
                }
                return new EditorBundle(customers, series, existing, lines);
            }
        };
        task.setOnSucceeded(event -> {
            EditorBundle bundle = task.getValue();
            // Guardas de precondicion: sin clientes o sin series no tiene
            // sentido abrir el editor. Mensaje accionable en vez de un
            // formulario en blanco que despues falla al guardar.
            if (existingInvoiceId == null && bundle.customers().isEmpty()) {
                // TPB-CLIENT-SETUP F1: en vez de bloquear sin accion,
                // ofrecemos crear el cliente-receptor aqui mismo. Tras
                // crearlo, reabrimos el editor (ya habra >=1 customer).
                setCenterAnimated(scroll(prerequisitePanel(
                        t("prereq.no_customers.title"),
                        t("prereq.no_customers.body"),
                        t("prereq.no_customers.create"),
                        "fas-user-plus",
                        () -> openNewCustomerDialog(() -> showInvoiceEditor(null)))));
                return;
            }
            if (existingInvoiceId == null && bundle.series().isEmpty()) {
                setCenterAnimated(scroll(prerequisitePanel(
                        t("prereq.no_series.title"),
                        t("prereq.no_series.body"))));
                return;
            }
            setCenterAnimated(scroll(invoiceEditorView(bundle, existingInvoiceId)));
        });
        task.setOnFailed(event -> setCenterAnimated(scroll(errorPanel(
                existingInvoiceId == null
                        ? t("prereq.editor_failed")
                        : t("prereq.invoice_load_failed")))));
        start(task, "billing-editor-load");
    }

    private record EditorBundle(List<CustomerSummary> customers,
                                List<SeriesEntry> series,
                                SalesInvoiceSummary existing,
                                List<InvoiceLineDraft> existingLines) {
    }

    private VBox invoiceEditorView(EditorBundle bundle, String existingId) {
        VBox content = content();
        editorPendingWorkLogIds.clear();

        // ----- Header -----
        // NAV-CLIENT-BACK: "Volver" vuelve al cliente si la asesoria
        // esta actuando-como uno; si no, a la facturacion normal.
        Button back = new Button(t("editor.back"));
        back.setGraphic(icon("fas-arrow-left"));
        back.setOnAction(event -> returnToClientOrBilling());

        Label title = new Label(existingId == null ? t("editor.title.new") : t("editor.title.edit"));
        title.getStyleClass().add("module-detail-title");
        Label subtitle = new Label(existingId == null
                ? t("editor.subtitle.new")
                : t("editor.subtitle.edit"));
        subtitle.getStyleClass().add("module-detail-description");

        // Pill grande con el numero que se asignara al validar. Se mantiene
        // igual aunque guardes varios borradores: solo "Validar y emitir"
        // consume el correlativo. Cuando cambias de serie en el combo se
        // recalcula en vivo.
        Label nextNumberBadgeLabel = label(t("editor.next_number.caption"), "invoice-next-number-caption");
        Label nextNumberBadgeValue = new Label("—");
        nextNumberBadgeValue.getStyleClass().add("invoice-next-number-value");
        VBox nextNumberBadge = new VBox(2, nextNumberBadgeLabel, nextNumberBadgeValue);
        nextNumberBadge.getStyleClass().add("invoice-next-number-badge");

        VBox titleBox = new VBox(4, title, subtitle);
        Region headerSpacer = new Region();
        HBox.setHgrow(headerSpacer, Priority.ALWAYS);
        StackPane moduleIcon = iconBubble("fas-file-invoice", "module-title-icon");
        HBox header = new HBox(16, back, titleBox, headerSpacer, nextNumberBadge, moduleIcon);
        header.setAlignment(Pos.CENTER_LEFT);
        header.getStyleClass().add("module-detail-header");

        // ----- Setup widgets (mismos nombres de campo: persistDraft sigue
        //  funcionando sin tocarlo) -----
        editorCustomerCombo = new ComboBox<>();
        editorCustomerCombo.getItems().addAll(bundle.customers());
        editorCustomerCombo.getStyleClass().add("invoice-input");
        editorCustomerCombo.setMaxWidth(Double.MAX_VALUE);
        configureCustomerCombo(editorCustomerCombo);
        if (existingId != null && bundle.existing() != null) {
            for (CustomerSummary c : bundle.customers()) {
                if (c.legalName() != null && c.legalName().equals(bundle.existing().customerLegalName())) {
                    editorCustomerCombo.getSelectionModel().select(c);
                    break;
                }
            }
        } else if (!bundle.customers().isEmpty()) {
            editorCustomerCombo.getSelectionModel().selectFirst();
        }

        // Ya no exponemos un combo "Serie" al usuario. La serie se elige
        // en el servidor segun el invoice_type (NORMAL → STANDARD). El
        // editor solo crea facturas normales — proformas/rectificativas
        // tienen flujo aparte (proximamente). De este modo cumplimos
        // RD 1619/2012 Art.13 por construccion: el usuario no puede
        // mezclar series por error.
        //
        // TPB-2: si la sesion esta actuando-como cliente y existe una
        // serie con expedited_by_company_id = asesoria real, esa es la
        // serie que el backend usara al validar. La mostramos en el
        // badge "PROXIMO Nº AL VALIDAR" para que el numero del banner
        // coincida con el que se asignara.
        String myRealAdvisoryId = com.benjagest.ui.service.AuthSession.get().activeCompanyId();
        boolean actingAsClient = com.benjagest.ui.service.AuthSession.get().isActingForClient();
        SeriesEntry tpbSeries = actingAsClient && myRealAdvisoryId != null
                ? bundle.series().stream()
                        .filter(s -> "STANDARD".equals(s.invoiceKind()))
                        .filter(s -> myRealAdvisoryId.equals(s.expeditedByCompanyId()))
                        .findFirst()
                        .orElse(null)
                : null;
        SeriesEntry standardSeries = tpbSeries != null
                ? tpbSeries
                : bundle.series().stream()
                        .filter(s -> "STANDARD".equals(s.invoiceKind()))
                        .filter(s -> s.expeditedByCompanyId() == null
                                || s.expeditedByCompanyId().isBlank())
                        .findFirst()
                        .orElse(null);

        editorInvoiceDate = new javafx.scene.control.DatePicker(
                bundle.existing() == null || bundle.existing().invoiceDate() == null || bundle.existing().invoiceDate().isBlank()
                        ? LocalDate.now()
                        : LocalDate.parse(bundle.existing().invoiceDate()));
        editorInvoiceDate.getStyleClass().add("invoice-input");
        editorInvoiceDate.setMaxWidth(Double.MAX_VALUE);
        com.benjagest.ui.support.EditableCells.installFlexibleConverter(editorInvoiceDate);

        editorDueDate = new javafx.scene.control.DatePicker(
                bundle.existing() == null || bundle.existing().dueDate() == null || bundle.existing().dueDate().isBlank()
                        ? LocalDate.now().plusDays(30)
                        : LocalDate.parse(bundle.existing().dueDate()));
        editorDueDate.getStyleClass().add("invoice-input");
        editorDueDate.setMaxWidth(Double.MAX_VALUE);
        com.benjagest.ui.support.EditableCells.installFlexibleConverter(editorDueDate);

        editorNotesArea = new javafx.scene.control.TextArea();
        editorNotesArea.setPromptText(t("editor.notes.prompt"));
        editorNotesArea.setPrefRowCount(5);
        editorNotesArea.setWrapText(true);
        editorNotesArea.getStyleClass().add("invoice-input");

        // ----- Card 1: Cabecera -----
        // Detalle del cliente seleccionado (NIF + email + telefono).
        VBox clientDetail = new VBox(3);
        clientDetail.getStyleClass().add("invoice-client-detail");
        Runnable refreshClientDetail = () -> {
            clientDetail.getChildren().clear();
            CustomerSummary c = editorCustomerCombo.getValue();
            if (c == null) {
                clientDetail.setVisible(false);
                clientDetail.setManaged(false);
                return;
            }
            clientDetail.setVisible(true);
            clientDetail.setManaged(true);
            Label datos = label(t("editor.client.detail_title"), "invoice-detail-title");
            Label nif = new Label(t("editor.client.tax_id_prefix")
                    + (c.taxIdentifier() == null || c.taxIdentifier().isBlank() ? "—" : c.taxIdentifier()));
            nif.getStyleClass().add("invoice-detail-line");
            clientDetail.getChildren().addAll(datos, nif);
            // Tarde 2026-06-10: pintar también dirección postal si está
            // rellena. Antes el editor solo mostraba NIF/email/teléfono
            // aunque el cliente ya tuviera dirección en BD → el bloque
            // del PDF salía completo pero el "preview" en el editor no.
            StringBuilder addrBuf = new StringBuilder();
            for (String part : new String[]{c.address(), c.postalCode(),
                                             c.city(), c.province()}) {
                if (part != null && !part.isBlank()) {
                    if (addrBuf.length() > 0) addrBuf.append(", ");
                    addrBuf.append(part);
                }
            }
            String fullAddress = addrBuf.toString();
            if (!fullAddress.isBlank()) {
                Label addr = new Label(fullAddress);
                addr.getStyleClass().add("invoice-detail-line");
                addr.setWrapText(true);
                clientDetail.getChildren().add(addr);
            }
            if (c.country() != null && !c.country().isBlank()
                    && !"España".equalsIgnoreCase(c.country().trim())) {
                Label cou = new Label(c.country());
                cou.getStyleClass().add("invoice-detail-line");
                clientDetail.getChildren().add(cou);
            }
            if (c.email() != null && !c.email().isBlank()) {
                Label em = new Label(t("editor.client.email_prefix") + c.email());
                em.getStyleClass().add("invoice-detail-line");
                clientDetail.getChildren().add(em);
            }
            if (c.phone() != null && !c.phone().isBlank()) {
                Label tel = new Label(t("editor.client.phone_prefix") + c.phone());
                tel.getStyleClass().add("invoice-detail-line");
                clientDetail.getChildren().add(tel);
            }
        };
        editorCustomerCombo.valueProperty().addListener((obs, oldV, newV) -> {
            // TIPO-IVA-CLIENTE: al elegir cliente, las líneas adoptan su IVA/retención.
            // Solo se "voltean" las líneas no tocadas y solo en factura NUEVA (editar
            // una factura existente no debe alterar sus tipos ya guardados).
            applyCustomerVatDefaults(newV, existingId == null);
            refreshClientDetail.run();
        });
        refreshClientDetail.run();

        // Tipo de factura. Si es RECTIFYING (borrador creado via "Anular"),
        // mostramos pill informativa (no editable — el tipo es consecuencia
        // del acto legal y no se puede cambiar). Si es NORMAL/PROFORMA,
        // mostramos un ComboBox para que el usuario elija. La serie la
        // resuelve el server por invoice_type; el usuario no elige serie.
        boolean isRectifying = bundle.existing() != null
                && "RECTIFYING".equals(bundle.existing().invoiceType());

        Node kindControl;
        if (isRectifying) {
            kindControl = label(
                    t("editor.rectifying.pill_prefix") + shortId(bundle.existing().originalInvoiceId()),
                    "invoice-pill");
            editorInvoiceTypeCombo = null;
        } else {
            editorInvoiceTypeCombo = new ComboBox<>();
            editorInvoiceTypeCombo.getItems().addAll("NORMAL", "PROFORMA");
            // Texto traducido en items y selected; valor interno = código.
            editorInvoiceTypeCombo.setCellFactory(lv -> new javafx.scene.control.ListCell<>() {
                @Override protected void updateItem(String item, boolean empty) {
                    super.updateItem(item, empty);
                    setText(empty || item == null ? "" : localizedInvoiceTypeLabel(item));
                }
            });
            editorInvoiceTypeCombo.setButtonCell(new javafx.scene.control.ListCell<>() {
                @Override protected void updateItem(String item, boolean empty) {
                    super.updateItem(item, empty);
                    setText(empty || item == null ? "" : localizedInvoiceTypeLabel(item));
                }
            });
            String currentType = bundle.existing() == null
                    ? "NORMAL" : (bundle.existing().invoiceType() == null
                            ? "NORMAL" : bundle.existing().invoiceType());
            if (!editorInvoiceTypeCombo.getItems().contains(currentType)) {
                currentType = "NORMAL";
            }
            editorInvoiceTypeCombo.getSelectionModel().select(currentType);
            editorInvoiceTypeCombo.getStyleClass().add("invoice-input");
            // Al cambiar el tipo, actualizamos el badge del header con
            // el próximo número de la serie correspondiente — feedback
            // inmediato de qué pasaría al validar.
            final var finalSeries = bundle.series();
            editorInvoiceTypeCombo.valueProperty().addListener((obs, oldV, newV) -> {
                if (newV == null) return;
                SeriesEntry seriesForType = pickSeriesForInvoiceType(newV, finalSeries, standardSeries);
                nextNumberBadgeValue.setText(seriesForType == null ? "—" : previewNextNumber(seriesForType));
                // Re-preguntar al backend la serie real para este kind
                // (mantiene el badge sincronizado con la logica TPB del
                // server cuando el usuario cambia NORMAL/PROFORMA).
                Task<SeriesEntry> retask = new Task<>() {
                    @Override
                    protected SeriesEntry call() throws Exception {
                        return billingApiClient.previewNextSeries(newV);
                    }
                };
                retask.setOnSucceeded(e -> {
                    SeriesEntry s2 = retask.getValue();
                    if (s2 != null) nextNumberBadgeValue.setText(previewNextNumber(s2));
                });
                start(retask, "editor-preview-next-type");
            });
            kindControl = editorInvoiceTypeCombo;
        }

        // Badge del header con el próximo número de la serie que tocará
        // al validar: STANDARD para NORMAL, PROFORMA para Proforma, RECT
        // para rectificativas.
        SeriesEntry badgeSeries = isRectifying
                ? bundle.series().stream()
                        .filter(s -> "RECTIFYING".equals(s.invoiceKind()))
                        .findFirst()
                        .orElse(standardSeries)
                : pickSeriesForInvoiceType(
                        editorInvoiceTypeCombo == null ? "NORMAL" : editorInvoiceTypeCombo.getValue(),
                        bundle.series(), standardSeries);
        if (badgeSeries != null) {
            nextNumberBadgeValue.setText(previewNextNumber(badgeSeries));
        } else {
            nextNumberBadgeValue.setText("—");
        }
        // TPB-2: en lugar de adivinar la serie del bundle, preguntamos
        // al backend la serie real que usaria al validar (aplica logica
        // TPB cuando la asesoria actua-como cliente). Asi el badge no
        // depende de filtros en el frontend que pueden no detectar la
        // serie TPB. Asincrono — al volver, machaca el badge.
        Task<SeriesEntry> previewTask = new Task<>() {
            @Override
            protected SeriesEntry call() throws Exception {
                String kind = isRectifying ? "RECTIFYING"
                        : (editorInvoiceTypeCombo == null
                            ? "NORMAL" : editorInvoiceTypeCombo.getValue());
                return billingApiClient.previewNextSeries(kind);
            }
        };
        previewTask.setOnSucceeded(ev -> {
            SeriesEntry s = previewTask.getValue();
            if (s != null) {
                nextNumberBadgeValue.setText(previewNextNumber(s));
            }
        });
        previewTask.setOnFailed(ev -> { /* fallback al badge calculado arriba */ });
        start(previewTask, "editor-preview-next");

        VBox colCliente = new VBox(8,
                label(t("editor.field.customer"), "invoice-field-label"),
                editorCustomerCombo,
                clientDetail
        );
        // Checkbox "Sin vencimiento" — para facturas que se cobran al
        // contado (sin fecha de pago aplazado). Al marcarse, deshabilita
        // el DatePicker y al guardar enviamos dueDate=null al backend.
        CheckBox noDueDateChk = new CheckBox(t("editor.field.due_date.none"));
        noDueDateChk.setSelected(bundle.existing() != null
                && (bundle.existing().dueDate() == null
                        || bundle.existing().dueDate().isBlank()));
        editorDueDate.setDisable(noDueDateChk.isSelected());
        noDueDateChk.selectedProperty().addListener((obs, oldV, newV) -> {
            editorDueDate.setDisable(Boolean.TRUE.equals(newV));
            if (Boolean.TRUE.equals(newV)) editorDueDate.setValue(null);
        });
        // Lo guardamos como campo para que el flujo de "save" lo lea.
        editorNoDueDateChk = noDueDateChk;

        VBox colFechas = new VBox(8,
                label(t("editor.field.invoice_date"), "invoice-field-label"),
                editorInvoiceDate,
                label(t("editor.field.due_date"), "invoice-field-label"),
                editorDueDate,
                noDueDateChk
        );
        VBox colTipo = new VBox(8,
                label(t("editor.field.kind"), "invoice-field-label"),
                kindControl
        );
        HBox.setHgrow(colCliente, Priority.ALWAYS);
        HBox.setHgrow(colFechas, Priority.ALWAYS);
        HBox.setHgrow(colTipo, Priority.ALWAYS);
        colCliente.setMinWidth(0);
        colFechas.setMinWidth(0);
        colTipo.setMinWidth(0);
        HBox cabeceraGrid = new HBox(20, colCliente, colFechas, colTipo);
        Node cabeceraCard = invoiceCard(t("editor.card.header"), "fas-info-circle", cabeceraGrid);

        // ----- Card 2: Lineas -----
        editorLinesTable = buildEditorLinesTable(bundle.existingLines());
        // Para una factura nueva, arrancamos con una linea vacia: evita la
        // sensacion de "pantalla rota" sin filas y replica el patron de
        // CONTENDO al abrir Nueva Factura.
        if (existingId == null && editorLinesTable.getItems().isEmpty()) {
            // TIPO-IVA-CLIENTE: la línea inicial nace con el IVA/retención del
            // cliente preseleccionado (selectFirst de arriba, anterior al listener).
            CustomerSummary preCust = editorCustomerCombo.getValue();
            if (preCust != null) {
                editorDefaultVat = preCust.defaultVatPercent() != null
                        ? preCust.defaultVatPercent() : new java.math.BigDecimal("21");
                editorDefaultRetention = preCust.defaultRetentionPercent() != null
                        ? preCust.defaultRetentionPercent() : java.math.BigDecimal.ZERO;
            }
            editorLinesTable.getItems().add(newEditorLine());
        }

        Button addLine = new Button(t("editor.line.add"));
        addLine.setGraphic(icon("fas-plus"));
        addLine.getStyleClass().add("invoice-primary-action");
        addLine.setOnAction(event -> {
            editorLinesTable.getItems().add(newEditorLine());
            recomputeEditorTotals();
        });

        Button removeLine = new Button(t("editor.line.remove"));
        removeLine.setGraphic(icon("fas-trash-alt"));
        removeLine.setOnAction(event -> {
            InvoiceLineDraft sel = editorLinesTable.getSelectionModel().getSelectedItem();
            if (sel != null) {
                editorLinesTable.getItems().remove(sel);
                recomputeEditorTotals();
            }
        });

        // TRB — Importar trabajos pendientes del cliente seleccionado como líneas.
        Button importWorks = new Button(t("editor.line.import_works"));
        importWorks.setGraphic(icon("fas-briefcase"));
        importWorks.getStyleClass().add("button-secondary");
        importWorks.setOnAction(event -> {
            CustomerSummary cust = editorCustomerCombo.getValue();
            if (cust == null) { showError(t("editor.error.no_customer.title"), t("editor.error.no_customer.body")); return; }
            showImportWorkLogsToInvoice(cust);
        });

        HBox lineasActions = new HBox(8, importWorks, addLine, removeLine);
        lineasActions.setAlignment(Pos.CENTER_RIGHT);
        Node lineasCard = invoiceCardWithActions(t("editor.card.lines"), "fas-calculator",
                lineasActions, editorLinesTable);

        // ----- Card 3: Totales y observaciones -----
        editorSubtotalLabel = new Label("0,00 €");
        editorVatLabel = new Label("0,00 €");
        editorRetentionLabel = new Label("0,00 €");
        editorTotalLabel = new Label("0,00 €");
        editorSubtotalLabel.getStyleClass().add("invoice-totals-value");
        editorVatLabel.getStyleClass().add("invoice-totals-value");
        editorRetentionLabel.getStyleClass().add("invoice-totals-retention");
        editorTotalLabel.getStyleClass().add("invoice-total-big");

        VBox totalsRows = new VBox(2,
                invoiceTotalsRow(t("editor.total.subtotal"), editorSubtotalLabel),
                invoiceTotalsRow(t("editor.total.vat"), editorVatLabel),
                invoiceTotalsRow(t("editor.total.retention"), editorRetentionLabel)
        );

        Label totalLabel = label(t("editor.total.total"), "invoice-total-label");
        Region totalSpacer = new Region();
        HBox.setHgrow(totalSpacer, Priority.ALWAYS);
        HBox totalBigBox = new HBox(12, totalLabel, totalSpacer, editorTotalLabel);
        totalBigBox.setAlignment(Pos.CENTER_LEFT);
        totalBigBox.getStyleClass().add("invoice-total-card");

        VBox rightTotals = new VBox(14, totalsRows, totalBigBox);
        rightTotals.setMinWidth(320);
        rightTotals.setMaxWidth(420);

        VBox notesCol = new VBox(8,
                label(t("editor.notes.label"), "invoice-field-label"),
                editorNotesArea
        );
        HBox.setHgrow(notesCol, Priority.ALWAYS);
        notesCol.setMinWidth(0);
        VBox.setVgrow(editorNotesArea, Priority.ALWAYS);

        HBox totalesGrid = new HBox(24, notesCol, rightTotals);
        Node totalesCard = invoiceCard(t("editor.card.totals"), "fas-euro-sign", totalesGrid);

        recomputeEditorTotals();

        // ----- Footer bar -----
        Button cancel = new Button(t("editor.action.cancel"));
        cancel.setOnAction(event -> returnToClientOrBilling());

        Button saveDraft = new Button(existingId == null ? t("editor.action.save_draft") : t("editor.action.save_changes"));
        saveDraft.setGraphic(icon("fas-save"));
        saveDraft.getStyleClass().add("invoice-primary-action");
        saveDraft.setOnAction(event -> persistDraft(existingId, false));

        Button validate = new Button(t("editor.action.validate"));
        validate.setGraphic(icon("fas-check"));
        validate.getStyleClass().add("invoice-validate-action");
        validate.setOnAction(event -> persistDraft(existingId, true));

        Region footerSpacer = new Region();
        HBox.setHgrow(footerSpacer, Priority.ALWAYS);
        HBox footerBar = new HBox(10, cancel, footerSpacer, saveDraft, validate);
        footerBar.setAlignment(Pos.CENTER_LEFT);
        footerBar.getStyleClass().add("invoice-footer-bar");

        content.getChildren().addAll(header, cabeceraCard, lineasCard, totalesCard, footerBar);
        return content;
    }

