    /**
     * Extrae el código PGC de la selección del ComboBox de cuenta. El
     * usuario puede haber:
     *   (a) elegido una opción del desplegable → "Etiqueta  ·  642"
     *   (b) escrito el código directamente → "642"
     * Soporta ambos: si la cadena contiene "·" agarra lo que viene
     * después; si no, devuelve la cadena trimeada (que debería ser
     * un código numérico).
     */
    private String extractAccountCode(javafx.scene.control.ComboBox<String> cb) {
        String raw = cb.getValue();
        if (raw == null) return "";
        raw = raw.trim();
        int sep = raw.lastIndexOf('·');
        if (sep >= 0) return raw.substring(sep + 1).trim();
        return raw;
    }

    /**
     * Crea un Tooltip con texto LEGIBLE (color claro sobre fondo
     * oscuro y padding razonable). Los Tooltips por defecto en
     * JavaFX 21 heredan colores de la paleta que en BENJAGEST tira a
     * gris oscuro sobre gris oscuro — ilegible. Este helper se
     * aplica a todos los tooltips de los botones de la columna de
     * acciones (Slice 3H-2).
     */
    private javafx.scene.control.Tooltip legibleTooltip(String text) {
        javafx.scene.control.Tooltip tip = new javafx.scene.control.Tooltip(text);
        tip.setStyle("-fx-background-color: #1f2937; "
                + "-fx-text-fill: #ffffff; "
                + "-fx-font-size: 12px; "
                + "-fx-padding: 6 10; "
                + "-fx-background-radius: 4;");
        tip.setShowDelay(javafx.util.Duration.millis(300));
        return tip;
    }

    /**
     * Lanza una tarea recurrente ahora (botón ▶). Pide confirmación
     * (un click accidental genera un asiento real) y al terminar
     * refresca el listado + EMITE RefreshBus para que los listados de
     * Ventas/Compras/Diario también se actualicen instantáneamente
     * (Slice 3H-3). Si falla, muestra el error completo del backend
     * (Slice 3H-4 — diagnóstico).
     */
    private void runRecurringTaskNow(
            com.benjagest.ui.model.AccountingModels.RecurringTask task,
            Runnable onDone) {
        javafx.scene.control.Alert confirm = new javafx.scene.control.Alert(
                javafx.scene.control.Alert.AlertType.CONFIRMATION,
                t("recurring.confirm.run_now") + "\n\n" + task.name(),
                javafx.scene.control.ButtonType.OK,
                javafx.scene.control.ButtonType.CANCEL);
        confirm.setHeaderText(t("recurring.action.run_now"));
        var res = confirm.showAndWait();
        if (res.isEmpty() || res.get() != javafx.scene.control.ButtonType.OK) return;
        new Thread(() -> {
            try {
                accountingApiClient.runRecurringNow(task.id(), LocalDate.now());
                javafx.application.Platform.runLater(() -> {
                    if (onDone != null) onDone.run();
                    // Slice 3H-3 — Notificar a TODOS los listados que
                    // dependan del documento generado para que se
                    // refresquen sin necesidad de cambiar de pestaña:
                    //   - SALES_INVOICE → factura DRAFT en Facturación
                    //   - PURCHASE → gasto DRAFT en Compras
                    //   - JOURNAL_ENTRY → asiento DRAFT en Contabilidad
                    com.benjagest.ui.support.RefreshBus.emit(
                            com.benjagest.ui.support.RefreshBus.TOPIC_SALES,
                            com.benjagest.ui.support.RefreshBus.TOPIC_PURCHASES,
                            com.benjagest.ui.support.RefreshBus.TOPIC_JOURNAL);
                    new javafx.scene.control.Alert(
                            javafx.scene.control.Alert.AlertType.INFORMATION,
                            t("recurring.run_now.success") + "\n\n"
                                    + t("recurring.run_now.success_hint"))
                            .show();
                });
            } catch (Exception ex) {
                // Diagnóstico mejorado: el mensaje del backend (causa
                // real) más el nombre de la tarea para que el asesor
                // sepa cuál falló. Incluimos el stack stem para ver
                // si es 400, 500, NPE, etc.
                String reason = ex.getMessage();
                if (reason == null || reason.isBlank()) {
                    reason = ex.getClass().getSimpleName();
                }
                final String finalReason = reason;
                javafx.application.Platform.runLater(() -> {
                    javafx.scene.control.Alert err = new javafx.scene.control.Alert(
                            javafx.scene.control.Alert.AlertType.ERROR,
                            t("recurring.run_now.error") + ":\n\n"
                                    + task.name() + "\n\n"
                                    + finalReason);
                    err.setResizable(true);
                    err.getDialogPane().setMinWidth(520);
                    err.showAndWait();
                });
            }
        }, "recurring-run-now").start();
    }

    /**
     * Conmuta el estado activo/inactivo de la tarea (botón ⏸/▶ junto al
     * ejecutar). Refresca el listado al terminar.
     */
    private void toggleRecurringTaskActive(
            com.benjagest.ui.model.AccountingModels.RecurringTask task,
            Runnable onDone) {
        new Thread(() -> {
            try {
                accountingApiClient.setRecurringActive(task.id(), !task.active());
                javafx.application.Platform.runLater(() -> {
                    if (onDone != null) onDone.run();
                });
            } catch (Exception ex) {
                javafx.application.Platform.runLater(() -> new javafx.scene.control.Alert(
                        javafx.scene.control.Alert.AlertType.ERROR,
                        t("recurring.toggle.error") + ": " + ex.getMessage()).show());
            }
        }, "recurring-toggle-active").start();
    }

    /**
     * Slice 3N — Elimina físicamente la plantilla recurrente tras
     * confirmar (la operación NO afecta a los documentos ya generados
     * por ella, solo evita que vuelva a ejecutarse en el futuro).
     * Refresca el listado y emite RefreshBus por si algún otro tab
     * dependía de la lista de recurrentes.
     */
    private void deleteRecurringTask(
            com.benjagest.ui.model.AccountingModels.RecurringTask task,
            Runnable onDone) {
        Alert confirm = new Alert(Alert.AlertType.CONFIRMATION,
                t("recurring.confirm.delete") + "\n\n" + task.name(),
                ButtonType.OK, ButtonType.CANCEL);
        confirm.setHeaderText(t("recurring.action.delete"));
        var res = confirm.showAndWait();
        if (res.isEmpty() || res.get() != ButtonType.OK) return;
        new Thread(() -> {
            try {
                accountingApiClient.deleteRecurring(task.id());
                javafx.application.Platform.runLater(() -> {
                    if (onDone != null) onDone.run();
                });
            } catch (Exception ex) {
                String reason = ex.getMessage() == null
                        ? ex.getClass().getSimpleName() : ex.getMessage();
                javafx.application.Platform.runLater(() -> {
                    javafx.scene.control.Alert err = new javafx.scene.control.Alert(
                            javafx.scene.control.Alert.AlertType.ERROR,
                            t("recurring.delete.error") + ":\n\n" + reason);
                    err.setResizable(true);
                    err.getDialogPane().setMinWidth(480);
                    err.showAndWait();
                });
            }
        }, "recurring-delete").start();
    }

    /**
     * Diálogo modal con el historial de ejecuciones de la tarea
     * (las últimas 50). Tabla con fecha programada, estado, mensaje.
     */
    private void showRecurringHistory(
            com.benjagest.ui.model.AccountingModels.RecurringTask task) {
        javafx.scene.control.Dialog<Void> dlg = new javafx.scene.control.Dialog<>();
        dlg.setTitle(t("recurring.action.history") + " — " + task.name());
        dlg.getDialogPane().getButtonTypes().add(javafx.scene.control.ButtonType.CLOSE);

        javafx.scene.control.TableView<com.benjagest.ui.model.AccountingModels.RecurringTaskRun> runsTable =
                new javafx.scene.control.TableView<>();
        runsTable.setPlaceholder(new Label(t("recurring.history.empty")));
        runsTable.setPrefSize(640, 360);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringTaskRun, LocalDate> cDate =
                new javafx.scene.control.TableColumn<>(t("recurring.history.col.date"));
        cDate.setCellValueFactory(c -> new javafx.beans.property.SimpleObjectProperty<>(
                c.getValue() == null ? null : c.getValue().scheduledDate()));
        cDate.setPrefWidth(110);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringTaskRun, String> cStatus =
                new javafx.scene.control.TableColumn<>(t("recurring.history.col.status"));
        cStatus.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(
                c.getValue() == null ? "" : c.getValue().status()));
        cStatus.setPrefWidth(100);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringTaskRun, String> cMsg =
                new javafx.scene.control.TableColumn<>(t("recurring.history.col.message"));
        cMsg.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(
                c.getValue() == null ? "" : c.getValue().message()));
        cMsg.setPrefWidth(380);

        runsTable.getColumns().add(cDate);
        runsTable.getColumns().add(cStatus);
        runsTable.getColumns().add(cMsg);

        new Thread(() -> {
            try {
                java.util.List<com.benjagest.ui.model.AccountingModels.RecurringTaskRun> runs =
                        accountingApiClient.listRecurringRuns(task.id(), 50);
                javafx.application.Platform.runLater(() -> runsTable.getItems().setAll(runs));
            } catch (Exception ex) {
                javafx.application.Platform.runLater(() -> runsTable.setPlaceholder(
                        new Label(t("recurring.history.error") + ": " + ex.getMessage())));
            }
        }, "recurring-history").start();

        dlg.getDialogPane().setContent(runsTable);
        dlg.showAndWait();
    }

    /**
     * Editor crear/editar tarea recurrente. El mismo diálogo sirve para
     * SALES_INVOICE y PURCHASE; cambia el bloque de "datos del documento"
     * según {@code kind}. Si {@code existing} es null, modo crear; si
     * no, modo editar (con campos prellenados). Al guardar llama a la
     * API y dispara {@code onSaved} para que el listado se refresque.
     *
     * <p>Para SALES_INVOICE el payload generado es:
     * <pre>
     * {
     *   customerNif, customerLegalName, concept,
     *   lines: [{description, quantity, unitPrice, vatPercent, retentionPercent}]
     * }
     * </pre>
     *
     * <p>Para PURCHASE el payload es:
     * <pre>
     * {
     *   supplierNif, supplierName, invoiceNumber, concept,
     *   baseAmount, vatPercent, vatAmount, totalAmount
     * }
     * </pre>
     */
    private void showRecurringEditor(
            String kind,
            com.benjagest.ui.model.AccountingModels.RecurringTask existing,
            Runnable onSaved) {
        boolean isSales = "SALES_INVOICE".equals(kind);
        javafx.scene.control.Dialog<javafx.scene.control.ButtonType> dlg = new javafx.scene.control.Dialog<>();
        // existing.id()==null → candidato pre-rellenado (Slice 3D), va
        // por el flujo CREAR. Solo "Editar" cuando hay id real.
        dlg.setTitle(existing == null || existing.id() == null
                ? (isSales ? t("recurring.new.sales") : t("recurring.new.expense"))
                : t("recurring.edit") + " — " + existing.name());

        javafx.scene.control.ButtonType saveType = new javafx.scene.control.ButtonType(
                t("button.save"), javafx.scene.control.ButtonBar.ButtonData.OK_DONE);
        dlg.getDialogPane().getButtonTypes().addAll(saveType,
                javafx.scene.control.ButtonType.CANCEL);

        // ------------ Campos comunes (cualquier kind) ------------
        TextField nameField = new TextField(existing == null ? "" : existing.name());
        nameField.setPromptText(isSales
                ? "Iguala mensual Acme SL" : "Alquiler oficina mensual");

        TextField descField = new TextField(existing == null ? "" : nullSafe(existing.description()));
        descField.setPromptText(t("recurring.field.description.hint"));

        javafx.scene.control.ComboBox<String> freqCombo =
                new javafx.scene.control.ComboBox<>();
        freqCombo.getItems().addAll("MONTHLY", "QUARTERLY", "YEARLY", "WEEKLY", "CUSTOM");
        localizeEnumCombo(freqCombo, "frequency");
        freqCombo.setValue(existing == null ? "MONTHLY" : existing.frequency());

        javafx.scene.control.Spinner<Integer> domSpinner = new javafx.scene.control.Spinner<>(1, 31,
                existing == null || existing.dayOfMonth() == null ? 1 : existing.dayOfMonth());
        domSpinner.setEditable(true);

        javafx.scene.control.Spinner<Integer> dowSpinner = new javafx.scene.control.Spinner<>(1, 7,
                existing == null || existing.dayOfWeek() == null ? 1 : existing.dayOfWeek());
        dowSpinner.setEditable(true);

        javafx.scene.control.Spinner<Integer> monthsSpinner = new javafx.scene.control.Spinner<>(1, 24,
                existing == null ? 1 : Math.max(1, existing.monthsBetween()));
        monthsSpinner.setEditable(true);

        DatePicker firstRunDate = new DatePicker(
                existing == null ? LocalDate.now().plusDays(1) : existing.nextRunDate());

        // ------------ Campos específicos según kind ------------
        TextField partyNifField = new TextField();
        TextField partyNameField = new TextField();
        TextField conceptField = new TextField();
        conceptField.setPromptText(t("recurring.field.concept.hint"));

        // SALES_INVOICE: una línea simple (descripción, cantidad, precio, IVA, retención)
        TextField lineDescField = new TextField();
        javafx.scene.control.Spinner<Double> qtySpinner = new javafx.scene.control.Spinner<>(0.01, 9999.0, 1.0, 1.0);
        qtySpinner.setEditable(true);
        javafx.scene.control.Spinner<Double> priceSpinner = new javafx.scene.control.Spinner<>(0.0, 999999.0, 0.0, 10.0);
        priceSpinner.setEditable(true);
        javafx.scene.control.Spinner<Double> vatSpinner = new javafx.scene.control.Spinner<>(0.0, 21.0, 21.0, 0.5);
        vatSpinner.setEditable(true);
        javafx.scene.control.Spinner<Double> retSpinner = new javafx.scene.control.Spinner<>(0.0, 30.0, 0.0, 1.0);
        retSpinner.setEditable(true);

        // PURCHASE: importe base / IVA / total
        TextField invoiceNumberField = new TextField();
        invoiceNumberField.setPromptText("ALQ-{YYYY}{MM}");
        javafx.scene.control.Spinner<Double> baseSpinner = new javafx.scene.control.Spinner<>(0.0, 999999.0, 0.0, 10.0);
        baseSpinner.setEditable(true);
        javafx.scene.control.Spinner<Double> vatPctSpinner = new javafx.scene.control.Spinner<>(0.0, 21.0, 21.0, 0.5);
        vatPctSpinner.setEditable(true);

        // Si estamos editando, prellenar desde payloadJson
        if (existing != null && existing.payloadJson() != null) {
            try {
                String pj = existing.payloadJson();
                if (isSales) {
                    partyNifField.setText(extractStringField(pj, "customerNif"));
                    partyNameField.setText(extractStringField(pj, "customerLegalName"));
                    conceptField.setText(extractStringField(pj, "concept"));
                    // primera línea: extracción superficial
                    int li = pj.indexOf("\"lines\"");
                    if (li > 0) {
                        String tail = pj.substring(li);
                        lineDescField.setText(extractStringField(tail, "description"));
                        Double q = extractDoubleField(tail, "quantity");
                        if (q != null) qtySpinner.getValueFactory().setValue(q);
                        Double up = extractDoubleField(tail, "unitPrice");
                        if (up != null) priceSpinner.getValueFactory().setValue(up);
                        Double vp = extractDoubleField(tail, "vatPercent");
                        if (vp != null) vatSpinner.getValueFactory().setValue(vp);
                        Double rp = extractDoubleField(tail, "retentionPercent");
                        if (rp != null) retSpinner.getValueFactory().setValue(rp);
                    }
                } else {
                    partyNifField.setText(extractStringField(pj, "supplierNif"));
                    partyNameField.setText(extractStringField(pj, "supplierName"));
                    conceptField.setText(extractStringField(pj, "concept"));
                    invoiceNumberField.setText(extractStringField(pj, "invoiceNumber"));
                    Double b = extractDoubleField(pj, "baseAmount");
                    if (b != null) baseSpinner.getValueFactory().setValue(b);
                    Double vp = extractDoubleField(pj, "vatPercent");
                    if (vp != null) vatPctSpinner.getValueFactory().setValue(vp);
                }
            } catch (Exception ignored) {
                // si el JSON viene raro, dejamos campos vacíos — el asesor
                // los rellena de cero
            }
        }

        // ------------ Layout ------------
        GridPane grid = new GridPane();
        grid.setHgap(10);
        grid.setVgap(8);
        grid.setPadding(new Insets(16));

        int r = 0;
        grid.add(new Label(t("recurring.field.name")), 0, r);
        grid.add(nameField, 1, r++, 3, 1);
        grid.add(new Label(t("recurring.field.description")), 0, r);
        grid.add(descField, 1, r++, 3, 1);

        // Slice 3H-1 — Mostrar las opciones del ComboBox traducidas
        // (en el ComboBox van los códigos técnicos para no romper el
        // payload del backend, pero el render se traduce con
        // localizedFrequency).
        applyFrequencyComboCells(freqCombo);

        // Las etiquetas "Día del mes" y los Spinners dow/monthsBetween
        // dependen de la frecuencia elegida. En lugar de mostrar
        // "DoW / N meses" siempre, mostramos lo apropiado y ocultamos
        // lo que no aplica.
        Label dayLabel = new Label(t("recurring.freq.day"));
        Label dowLabel = new Label(t("recurring.field.day_of_week"));
        Label monthsLabel = new Label(t("recurring.field.months_between"));
        Runnable applyFreqVisibility = () -> {
            String f = freqCombo.getValue();
            boolean monthly = "MONTHLY".equals(f) || "CUSTOM".equals(f);
            boolean weekly = "WEEKLY".equals(f);
            boolean custom = "CUSTOM".equals(f);
            dayLabel.setManaged(monthly); dayLabel.setVisible(monthly);
            domSpinner.setManaged(monthly); domSpinner.setVisible(monthly);
            dowLabel.setManaged(weekly); dowLabel.setVisible(weekly);
            dowSpinner.setManaged(weekly); dowSpinner.setVisible(weekly);
            monthsLabel.setManaged(custom); monthsLabel.setVisible(custom);
            monthsSpinner.setManaged(custom); monthsSpinner.setVisible(custom);
        };
        freqCombo.valueProperty().addListener((o, a, b) -> applyFreqVisibility.run());
        applyFreqVisibility.run();

        grid.add(new Label(t("recurring.field.frequency")), 0, r);
        grid.add(freqCombo, 1, r);
        grid.add(dayLabel, 2, r);
        grid.add(domSpinner, 3, r++);

        grid.add(dowLabel, 0, r);
        grid.add(dowSpinner, 1, r);
        grid.add(monthsLabel, 2, r);
        grid.add(monthsSpinner, 3, r++);

        grid.add(new Label(t("recurring.field.first_run")), 0, r);
        grid.add(firstRunDate, 1, r++, 3, 1);

        Label sep = new Label(isSales
                ? t("recurring.section.sale_data") : t("recurring.section.expense_data"));
        sep.getStyleClass().add("text-bold");
        grid.add(sep, 0, r++, 4, 1);

        grid.add(new Label(isSales
                ? t("recurring.field.customer_nif")
                : t("recurring.field.supplier_nif")), 0, r);
        grid.add(partyNifField, 1, r++, 3, 1);

        grid.add(new Label(isSales
                ? t("recurring.field.customer_name")
                : t("recurring.field.supplier_name")), 0, r);
        grid.add(partyNameField, 1, r++, 3, 1);

        grid.add(new Label(t("recurring.field.concept")), 0, r);
        grid.add(buildConceptWithPlaceholders(conceptField), 1, r++, 3, 1);

        if (isSales) {
            grid.add(new Label(t("recurring.field.line_desc")), 0, r);
            grid.add(lineDescField, 1, r++, 3, 1);
            grid.add(new Label(t("recurring.field.quantity")), 0, r);
            grid.add(qtySpinner, 1, r);
            grid.add(new Label(t("recurring.field.unit_price")), 2, r);
            grid.add(priceSpinner, 3, r++);
            grid.add(new Label(t("recurring.field.vat_percent")), 0, r);
            grid.add(vatSpinner, 1, r);
            grid.add(new Label(t("recurring.field.retention_percent")), 2, r);
            grid.add(retSpinner, 3, r++);
        } else {
            grid.add(new Label(t("recurring.field.invoice_number")), 0, r);
            grid.add(invoiceNumberField, 1, r++, 3, 1);
            grid.add(new Label(t("recurring.field.base_amount")), 0, r);
            grid.add(baseSpinner, 1, r);
            grid.add(new Label(t("recurring.field.vat_percent")), 2, r);
            grid.add(vatPctSpinner, 3, r++);
        }

        Label placeholderHint = new Label(t("recurring.placeholders.hint"));
        placeholderHint.getStyleClass().addAll("muted", "small");
        placeholderHint.setWrapText(true);
        grid.add(placeholderHint, 0, r++, 4, 1);

        ScrollPane scroll = new ScrollPane(grid);
        scroll.setFitToWidth(true);
        scroll.setPrefSize(640, 560);
        dlg.getDialogPane().setContent(scroll);

        // ------------ Guardar ------------
        dlg.setResultConverter(bt -> bt);
        var result = dlg.showAndWait();
        if (result.isEmpty() || result.get() != saveType) return;

        // Slice 3O — Forzar commit de TODOS los Spinners del editor.
        // Sin esto, si el usuario escribió un importe a mano y no
        // tabuló antes de Guardar, getValue() devolvía 0 → el
        // recurrente se guardaba con base=0 y al ejecutar el cron
        // generaba líneas vacías ("Línea 1: la línea está vacía"
        // del backend). Aplica a SALES (qty/price/vat/ret) y a
        // PURCHASE (base/vatPct), además de los comunes (domSpinner,
        // dowSpinner, monthsSpinner).
        commitSpinner(domSpinner);
        commitSpinner(dowSpinner);
        commitSpinner(monthsSpinner);
        if (isSales) {
            commitSpinner(qtySpinner);
            commitSpinner(priceSpinner);
            commitSpinner(vatSpinner);
            commitSpinner(retSpinner);
        } else {
            commitSpinner(baseSpinner);
            commitSpinner(vatPctSpinner);
        }

        // Slice 3I — Validar campos críticos ANTES de mandar al
        // backend para evitar el round-trip 422 con mensajes
        // técnicos. El backend del recurrente SALES_INVOICE necesita
        // sí o sí customerNif + customerLegalName cuando no hay
        // customerId. Si falta el NIF, paramos aquí con alert claro.
        if (!validateSalesRecurringNif(kind,
                partyNifField.getText(), partyNameField.getText())) {
            return;
        }

        // Slice 3O — Validar también el importe base > 0 (PURCHASE)
        // o precio unitario > 0 (SALES). Sin esto, todas las líneas
        // del payload serían 0 y el backend devolvería "línea vacía".
        double checkAmount = isSales
                ? priceSpinner.getValue() * qtySpinner.getValue()
                : baseSpinner.getValue();
        if (checkAmount <= 0.0) {
            Alert a = new Alert(Alert.AlertType.WARNING,
                    t("recurring.validate.amount_required"),
                    ButtonType.OK);
            a.setHeaderText(t("recurring.validate.amount_required_header"));
            a.showAndWait();
            return;
        }

        // Construir JSON request
        StringBuilder body = new StringBuilder();
        body.append('{');
        appendJsonField(body, "kind", kind, true);
        appendJsonField(body, "name", nameField.getText(), false);
        if (!descField.getText().isBlank()) appendJsonField(body, "description", descField.getText(), false);
        appendJsonField(body, "frequency", freqCombo.getValue(), false);
        if ("MONTHLY".equals(freqCombo.getValue()) || "CUSTOM".equals(freqCombo.getValue())) {
            body.append(",\"dayOfMonth\":").append(domSpinner.getValue());
        }
        if ("WEEKLY".equals(freqCombo.getValue())) {
            body.append(",\"dayOfWeek\":").append(dowSpinner.getValue());
        }
        if ("CUSTOM".equals(freqCombo.getValue())) {
            body.append(",\"monthsBetween\":").append(monthsSpinner.getValue());
        }
        body.append(",\"firstRunDate\":\"").append(firstRunDate.getValue()).append('"');

        // Payload anidado según kind
        body.append(",\"payload\":{");
        if (isSales) {
            appendJsonField(body, "customerNif", partyNifField.getText(), true);
            appendJsonField(body, "customerLegalName", partyNameField.getText(), false);
            if (!conceptField.getText().isBlank())
                appendJsonField(body, "concept", conceptField.getText(), false);
            body.append(",\"lines\":[{");
            body.append("\"description\":").append(jsonString(lineDescField.getText()));
            body.append(",\"quantity\":").append(qtySpinner.getValue());
            body.append(",\"unitPrice\":").append(priceSpinner.getValue());
            body.append(",\"vatPercent\":").append(vatSpinner.getValue());
            body.append(",\"retentionPercent\":").append(retSpinner.getValue());
            body.append("}]");
        } else {
            appendJsonField(body, "supplierNif", partyNifField.getText(), true);
            appendJsonField(body, "supplierName", partyNameField.getText(), false);
            appendJsonField(body, "invoiceNumber", invoiceNumberField.getText(), false);
            if (!conceptField.getText().isBlank())
                appendJsonField(body, "concept", conceptField.getText(), false);
            double base = baseSpinner.getValue();
            double vatPct = vatPctSpinner.getValue();
            double vatAmt = Math.round(base * vatPct) / 100.0;
            double total = Math.round((base + vatAmt) * 100.0) / 100.0;
            body.append(",\"baseAmount\":").append(base);
            body.append(",\"vatPercent\":").append(vatPct);
            body.append(",\"vatAmount\":").append(vatAmt);
            body.append(",\"totalAmount\":").append(total);
        }
        body.append("}}");

        String jsonBody = body.toString();
        new Thread(() -> {
            try {
                // existing==null → modo crear puro (botón Nuevo).
                // existing!=null && id==null → modo crear desde candidato
                // pre-rellenado (Slice 3D); existing!=null && id!=null →
                // modo editar real (PUT).
                if (existing == null || existing.id() == null) {
                    accountingApiClient.createRecurring(jsonBody);
                } else {
                    accountingApiClient.updateRecurring(existing.id(), jsonBody);
                }
                // Slice 3X — emitir RefreshBus.TOPIC_RECURRING para que
                // cualquier sub-tab Recurrentes abierto se refresque sin
                // depender del callback onSaved (que solo conoce el sub
                // -tab desde el que abrieron el editor).
                com.benjagest.ui.support.RefreshBus.emit(
                        com.benjagest.ui.support.RefreshBus.TOPIC_RECURRING);
                javafx.application.Platform.runLater(() -> {
                    if (onSaved != null) onSaved.run();
                });
            } catch (Exception ex) {
                javafx.application.Platform.runLater(() -> new javafx.scene.control.Alert(
                        javafx.scene.control.Alert.AlertType.ERROR,
                        t("recurring.save.error") + ": " + ex.getMessage()).show());
            }
        }, "recurring-save").start();
    }

    private String nullSafe(String s) { return s == null ? "" : s; }

    /**
     * Slice 3M — Fuerza el commit del texto pendiente en un Spinner
     * editable. JavaFX no commitea hasta que el campo pierde el foco,
     * así que si el usuario escribe "295" y pulsa Guardar sin tabular
     * antes, getValue() devuelve el valor anterior (típicamente 0).
     * Esto causaba "Línea 1: la línea está vacía" en el backend.
     */
    private void commitSpinner(javafx.scene.control.Spinner<?> spinner) {
        if (spinner == null) return;
        var editor = spinner.getEditor();
        if (editor == null) return;
        try {
            String text = editor.getText();
            if (text == null || text.isBlank()) return;
            var converter = spinner.getValueFactory() == null
                    ? null : spinner.getValueFactory().getConverter();
            if (converter == null) return;
            Object parsed = converter.fromString(text);
            if (parsed != null) {
                @SuppressWarnings({"unchecked", "rawtypes"})
                javafx.scene.control.SpinnerValueFactory vf = spinner.getValueFactory();
                vf.setValue(parsed);
            }
        } catch (Exception ignored) {
            // si el texto no es parseable (ej. usuario escribió "abc"),
            // dejamos el valor anterior y la validación posterior se
            // encarga de avisar.
        }
    }

    /**
     * Slice 3I — Envuelve el TextField de Concepto con un MenuButton
     * de placeholders predictivos. El usuario pulsa "Insertar" y
     * elige el placeholder (mes, año, día, trimestre...) que se
     * inserta donde tenga el cursor.
     *
     * <p>Los placeholders se expanden en runtime en el backend al
     * ejecutar el cron — ver
     * {@code RecurringTaskService#expandPlaceholders}. Sincronizado
     * con la lista del backend.
     */
    private HBox buildConceptWithPlaceholders(TextField concept) {
        javafx.scene.control.MenuButton insertBtn =
                new javafx.scene.control.MenuButton("➕ " + t("recurring.placeholders.insert"));
        insertBtn.setTooltip(legibleTooltip(t("recurring.placeholders.hint")));
        // Slice 3R-fix — trackear la última posición conocida del
        // caret MIENTRAS el TextField tiene foco. Sin esto, si el
        // usuario nunca enfocó el TextField (abre editor → click
        // directo en MenuButton), getCaretPosition() devuelve 0 y
        // el placeholder se inserta al principio.
        final int[] lastCaret = { -1 };
        concept.caretPositionProperty().addListener((obs, oldV, newV) -> {
            if (concept.isFocused() && newV != null) {
                lastCaret[0] = newV.intValue();
            }
        });
        concept.focusedProperty().addListener((obs, was, isNow) -> {
            if (isNow) lastCaret[0] = concept.getCaretPosition();
        });
        String[][] phs = {
                {"{MES}", "junio (nombre del mes en minúsculas)"},
                {"{MES_MAY}", "Junio (capitalizado)"},
                {"{MM}", "06 (mes con cero)"},
                {"{M}", "6 (mes sin cero)"},
                {"{YYYY}", "2026 (año largo)"},
                {"{YY}", "26 (año corto)"},
                {"{AÑO}", "2026 (alias de {YYYY})"},
                {"{DD}", "07 (día con cero)"},
                {"{D}", "7 (día sin cero)"},
                {"{T}", "T2 (trimestre, T1-T4)"},
                {"{Q}", "Q2 (trimestre, Q1-Q4)"}};
        for (String[] ph : phs) {
            javafx.scene.control.MenuItem item =
                    new javafx.scene.control.MenuItem(ph[0] + "  →  " + ph[1]);
            item.setOnAction(e -> {
                String text = concept.getText() == null ? "" : concept.getText();
                // Si el usuario nunca tocó el TextField, insertar al
                // FINAL (no al principio) — es lo que la mayoría
                // espera al pulsar "Insertar placeholder" sin haber
                // posicionado el cursor antes.
                int caret = lastCaret[0] >= 0 ? lastCaret[0] : text.length();
                if (caret > text.length()) caret = text.length();
                concept.setText(text.substring(0, caret) + ph[0] + text.substring(caret));
                int newCaret = caret + ph[0].length();
                lastCaret[0] = newCaret;
                concept.positionCaret(newCaret);
                concept.requestFocus();
            });
            insertBtn.getItems().add(item);
        }
        HBox row = new HBox(6, concept, insertBtn);
        HBox.setHgrow(concept, Priority.ALWAYS);
        return row;
    }

    /**
     * Slice 3I — Validador del NIF cliente antes de guardar una venta
     * recurrente. Evita el round-trip al backend que devolvía 422
     * cuando el NIF estaba vacío. Llamado desde showRecurringEditor.
     */
    private boolean validateSalesRecurringNif(String kind, String partyNif, String partyName) {
        if (!"SALES_INVOICE".equals(kind)) return true;
        if (partyNif != null && !partyNif.isBlank()) return true;
        if (partyName == null || partyName.isBlank()) return true; // ya da otro error
        Alert a = new Alert(Alert.AlertType.WARNING,
                t("recurring.validate.nif_required"),
                ButtonType.OK);
        a.setHeaderText(t("recurring.validate.nif_required_header"));
        a.showAndWait();
        return false;
    }

    /**
     * Slice 3F — Editor de "Pago periódico sin factura". Pensado para
     * gastos que se cargan en el banco sin que llegue factura ni recibo:
     * cuota autónomo TGSS, comisiones bancarias mensuales, modelos AEAT,
     * cuotas de préstamo, etc.
     *
     * <p>Genera un RecurringTask de kind=JOURNAL_ENTRY cuyo payload
     * tiene 2 líneas balanceadas:
     * <pre>
     *   DEBE  gastoCode      importe
     *   HABER bancoCode      importe
     * </pre>
     * El backend resuelve los códigos a IDs reales del PGC del tenant
     * en runtime (Slice 3F-1a).
     *
     * <p>Campos: nombre + descripción + frecuencia (combo) + día +
     * primera ejecución + concepto + cuenta gasto (código) + cuenta
     * banco (código) + importe.
     */
    private void showJournalEntryRecurringEditor(
            com.benjagest.ui.model.AccountingModels.RecurringTask existing,
            Runnable onSaved) {
        javafx.scene.control.Dialog<javafx.scene.control.ButtonType> dlg = new javafx.scene.control.Dialog<>();
        dlg.setTitle(existing == null || existing.id() == null
                ? t("recurring.new.journal_entry")
                : t("recurring.edit") + " — " + existing.name());

        javafx.scene.control.ButtonType saveType = new javafx.scene.control.ButtonType(
                t("button.save"), javafx.scene.control.ButtonBar.ButtonData.OK_DONE);
        dlg.getDialogPane().getButtonTypes().addAll(saveType,
                javafx.scene.control.ButtonType.CANCEL);

        // Campos comunes
        TextField nameField = new TextField(existing == null ? "" : nullSafe(existing.name()));
        nameField.setPromptText("Cuota autónomo mensual");

        TextField descField = new TextField(existing == null ? "" : nullSafe(existing.description()));
        descField.setPromptText(t("recurring.field.description.hint"));

        javafx.scene.control.ComboBox<String> freqCombo = new javafx.scene.control.ComboBox<>();
        freqCombo.getItems().addAll("MONTHLY", "QUARTERLY", "YEARLY", "WEEKLY", "CUSTOM");
        localizeEnumCombo(freqCombo, "frequency");
        freqCombo.setValue(existing == null ? "MONTHLY" : existing.frequency());
        applyFrequencyComboCells(freqCombo);

        javafx.scene.control.Spinner<Integer> domSpinner = new javafx.scene.control.Spinner<>(
                1, 31, existing == null || existing.dayOfMonth() == null ? 1 : existing.dayOfMonth());
        domSpinner.setEditable(true);

        DatePicker firstRunDate = new DatePicker(
                existing == null ? LocalDate.now().plusDays(1) : existing.nextRunDate());

        TextField conceptField = new TextField();
        conceptField.setPromptText(t("recurring.field.concept.hint"));

        // Slice 3H-5 — En lugar de pedir el código PGC en un TextField
        // (que el empresario no conoce), ofrecemos un ComboBox editable
        // con TODAS las cuentas habituales para pagos sin factura, ya
        // etiquetadas en lenguaje natural. El asesor que prefiera
        // escribir el código directamente también puede.
        javafx.scene.control.ComboBox<String> expenseAccountField =
                buildExpenseAccountCombo();
        javafx.scene.control.ComboBox<String> bankAccountField =
                buildBankAccountCombo();

        javafx.scene.control.Spinner<Double> amountSpinner =
                new javafx.scene.control.Spinner<>(0.0, 999999.0, 0.0, 10.0);
        amountSpinner.setEditable(true);

        // Slice 3J — IVA y retención. Muchos pagos sin factura sí los
        // llevan: una iguala de asesoría tiene IVA 21% + retención IRPF
        // 15%; un alquiler tiene IVA 21% + retención 19%. La cuota
        // autónomo no lleva ni uno ni otro (default 0).
        javafx.scene.control.Spinner<Double> vatPercentSpinner =
                new javafx.scene.control.Spinner<>(0.0, 21.0, 0.0, 0.5);
        vatPercentSpinner.setEditable(true);
        javafx.scene.control.Spinner<Double> retentionPercentSpinner =
                new javafx.scene.control.Spinner<>(0.0, 30.0, 0.0, 1.0);
        retentionPercentSpinner.setEditable(true);

        // Label "Total a pagar" que recalcula dinámicamente.
        Label totalLabel = new Label("0,00 €");
        totalLabel.getStyleClass().add("text-bold");
        Runnable recomputeTotal = () -> {
            double base = amountSpinner.getValue() == null ? 0 : amountSpinner.getValue();
            double vat = vatPercentSpinner.getValue() == null ? 0 : vatPercentSpinner.getValue();
            double ret = retentionPercentSpinner.getValue() == null ? 0 : retentionPercentSpinner.getValue();
            double total = base + Math.round(base * vat) / 100.0 - Math.round(base * ret) / 100.0;
            totalLabel.setText(String.format("%.2f €", total));
        };
        amountSpinner.valueProperty().addListener((o, a, b) -> recomputeTotal.run());
        vatPercentSpinner.valueProperty().addListener((o, a, b) -> recomputeTotal.run());
        retentionPercentSpinner.valueProperty().addListener((o, a, b) -> recomputeTotal.run());

        // Pre-rellenar desde payloadJson si estamos editando.
        if (existing != null && existing.payloadJson() != null) {
            String pj = existing.payloadJson();
            conceptField.setText(extractStringField(pj, "concept"));
            // El payload lleva: baseAmount, vatPercent, retentionPercent,
            // expenseAccountCode, bankAccountCode. Si encuentro estos
            // campos, los uso (formato nuevo). Si no, caigo al formato
            // antiguo basado en lines[].
            String base = extractStringField(pj, "baseAmount");
            if (base != null && !base.isBlank()) {
                try { amountSpinner.getValueFactory().setValue(Double.parseDouble(base)); }
                catch (NumberFormatException ignored) {}
                Double vp = extractDoubleField(pj, "vatPercent");
                if (vp != null) vatPercentSpinner.getValueFactory().setValue(vp);
                Double rp = extractDoubleField(pj, "retentionPercent");
                if (rp != null) retentionPercentSpinner.getValueFactory().setValue(rp);
                String exp = extractStringField(pj, "expenseAccountCode");
                String bnk = extractStringField(pj, "bankAccountCode");
                if (exp != null && !exp.isBlank()) expenseAccountField.setValue(exp);
                if (bnk != null && !bnk.isBlank()) bankAccountField.setValue(bnk);
            } else {
                // Formato antiguo: extraer desde lines[]
                int firstLine = pj.indexOf("\"lines\"");
                if (firstLine > 0) {
                    String tail = pj.substring(firstLine);
                    int firstAcc = tail.indexOf("accountCode");
                    if (firstAcc > 0) {
                        expenseAccountField.setValue(extractStringField(
                                tail.substring(firstAcc), "accountCode"));
                        int lastAcc = tail.lastIndexOf("accountCode");
                        if (lastAcc > firstAcc) {
                            bankAccountField.setValue(extractStringField(
                                    tail.substring(lastAcc), "accountCode"));
                        }
                    }
                    Double d = extractDoubleField(tail, "debit");
                    if (d != null && d > 0) amountSpinner.getValueFactory().setValue(d);
                }
            }
            recomputeTotal.run();
        }

        GridPane grid = new GridPane();
        grid.setHgap(10); grid.setVgap(8); grid.setPadding(new Insets(16));
        int r = 0;
        grid.add(new Label(t("recurring.field.name")), 0, r);
        grid.add(nameField, 1, r++, 3, 1);
        grid.add(new Label(t("recurring.field.description")), 0, r);
        grid.add(descField, 1, r++, 3, 1);
        grid.add(new Label(t("recurring.field.frequency")), 0, r);
        grid.add(freqCombo, 1, r);
        grid.add(new Label(t("recurring.freq.day")), 2, r);
        grid.add(domSpinner, 3, r++);
        grid.add(new Label(t("recurring.field.first_run")), 0, r);
        grid.add(firstRunDate, 1, r++, 3, 1);

        Label sep = new Label(t("recurring.section.payment_data"));
        sep.getStyleClass().add("text-bold");
        grid.add(sep, 0, r++, 4, 1);

        grid.add(new Label(t("recurring.field.concept")), 0, r);
        grid.add(buildConceptWithPlaceholders(conceptField), 1, r++, 3, 1);
        grid.add(new Label(t("recurring.field.expense_account")), 0, r);
        grid.add(expenseAccountField, 1, r++, 3, 1);
        grid.add(new Label(t("recurring.field.bank_account")), 0, r);
        grid.add(bankAccountField, 1, r++, 3, 1);
        grid.add(new Label(t("recurring.field.amount") + " (base)"), 0, r);
        grid.add(amountSpinner, 1, r);
        grid.add(new Label(t("recurring.field.vat_percent")), 2, r);
        grid.add(vatPercentSpinner, 3, r++);

        grid.add(new Label(t("recurring.field.retention_percent")), 0, r);
        grid.add(retentionPercentSpinner, 1, r);
        grid.add(new Label(t("recurring.field.total_to_pay")), 2, r);
        grid.add(totalLabel, 3, r++);

        Label hint = new Label(t("recurring.journal_entry.hint"));
        hint.getStyleClass().addAll("muted", "small");
        hint.setWrapText(true);
        grid.add(hint, 0, r++, 4, 1);

        ScrollPane scroll = new ScrollPane(grid);
        scroll.setFitToWidth(true);
        scroll.setPrefSize(620, 480);
        dlg.getDialogPane().setContent(scroll);
        dlg.setResultConverter(bt -> bt);
        var result = dlg.showAndWait();
        if (result.isEmpty() || result.get() != saveType) return;

        // Slice 3M — Forzar commit del texto pendiente en los Spinners
        // ANTES de leer getValue(). JavaFX no commitea el texto editado
        // hasta que el campo pierde el foco; si el usuario escribe
        // "295" y pulsa "Guardar" sin tabular, getValue() devuelve el
        // valor anterior (0.0) → líneas vacías y el backend dice
        // "Línea 1: la línea está vacía".
        commitSpinner(amountSpinner);
        commitSpinner(vatPercentSpinner);
        commitSpinner(retentionPercentSpinner);
        commitSpinner(domSpinner);

        // Validar que el importe es > 0 — si no, alert claro en lugar
        // de mandar al backend con 0 y recibir el mensaje genérico.
        if (amountSpinner.getValue() == null
                || amountSpinner.getValue() <= 0.0) {
            Alert a = new Alert(Alert.AlertType.WARNING,
                    t("recurring.validate.amount_required"),
                    ButtonType.OK);
            a.setHeaderText(t("recurring.validate.amount_required_header"));
            a.showAndWait();
            return;
        }

        // Slice 3J-2 — Build JSON request con IVA y retención.
        // Genera 2/3/4 líneas en el asiento según los porcentajes:
        //
        //   base                                → DEBE cuenta gasto
        //   if (iva > 0): vatAmount             → DEBE 472 IVA soportado
        //   if (ret > 0): retAmount             → HABER 4751 H.P. retenc.
        //   total a pagar (base + iva - ret)    → HABER cuenta banco
        //
        // El backend resuelve los códigos a UUIDs reales con
        // resolveAccountIdByCode (Slice 3F-1a). 472 y 4751 son
        // estándar PGC PYMES (sembrados por V46).
        double base = amountSpinner.getValue();
        double vatPct = vatPercentSpinner.getValue();
        double retPct = retentionPercentSpinner.getValue();
        double vatAmount = Math.round(base * vatPct) / 100.0;
        double retAmount = Math.round(base * retPct) / 100.0;
        double totalToPay = base + vatAmount - retAmount;
        String expAcc = extractAccountCode(expenseAccountField);
        String bankAcc = extractAccountCode(bankAccountField);
        String concept = conceptField.getText();
        String conceptStr = concept == null ? "" : concept;

        StringBuilder body = new StringBuilder();
        body.append('{');
        appendJsonField(body, "kind", "JOURNAL_ENTRY", true);
        appendJsonField(body, "name", nameField.getText(), false);
        if (!descField.getText().isBlank())
            appendJsonField(body, "description", descField.getText(), false);
        appendJsonField(body, "frequency", freqCombo.getValue(), false);
        if ("MONTHLY".equals(freqCombo.getValue()) || "CUSTOM".equals(freqCombo.getValue())) {
            body.append(",\"dayOfMonth\":").append(domSpinner.getValue());
        }
        body.append(",\"firstRunDate\":\"").append(firstRunDate.getValue()).append('"');
        body.append(",\"payload\":{");
        appendJsonField(body, "concept", conceptStr, true);
        // Metadatos para que el editor pueda re-prellenar los campos al
        // editar (Slice 3J-2). El backend los ignora — solo lee "lines".
        body.append(",\"baseAmount\":\"").append(base).append('"');
        body.append(",\"vatPercent\":").append(vatPct);
        body.append(",\"retentionPercent\":").append(retPct);
        appendJsonField(body, "expenseAccountCode", expAcc, false);
        appendJsonField(body, "bankAccountCode", bankAcc, false);

        body.append(",\"lines\":[");
        boolean firstLine = true;
        // Línea 1: DEBE cuenta gasto, importe = base
        body.append("{\"accountCode\":").append(jsonString(expAcc))
                .append(",\"description\":").append(jsonString(conceptStr))
                .append(",\"debit\":").append(base).append(",\"credit\":0}");
        firstLine = false;
        // Línea 2 (opcional): DEBE 472 IVA soportado
        if (vatAmount > 0) {
            body.append(",{\"accountCode\":\"472\"")
                    .append(",\"description\":").append(jsonString(conceptStr + " (IVA " + vatPct + "%)"))
                    .append(",\"debit\":").append(vatAmount).append(",\"credit\":0}");
        }
        // Línea 3 (opcional): HABER 4751 H.P. retenciones
        if (retAmount > 0) {
            body.append(",{\"accountCode\":\"4751\"")
                    .append(",\"description\":").append(jsonString(conceptStr + " (Retención " + retPct + "%)"))
                    .append(",\"debit\":0,\"credit\":").append(retAmount).append('}');
        }
        // Línea final: HABER cuenta banco, importe = total a pagar
        body.append(",{\"accountCode\":").append(jsonString(bankAcc))
                .append(",\"description\":").append(jsonString(conceptStr))
                .append(",\"debit\":0,\"credit\":").append(totalToPay).append('}');
        body.append(']');
        body.append("}}");

        String jsonBody = body.toString();
        new Thread(() -> {
            try {
                if (existing == null || existing.id() == null) {
                    accountingApiClient.createRecurring(jsonBody);
                } else {
                    accountingApiClient.updateRecurring(existing.id(), jsonBody);
                }
                com.benjagest.ui.support.RefreshBus.emit(
                        com.benjagest.ui.support.RefreshBus.TOPIC_RECURRING);
                javafx.application.Platform.runLater(() -> {
                    if (onSaved != null) onSaved.run();
                });
            } catch (Exception ex) {
                javafx.application.Platform.runLater(() -> new javafx.scene.control.Alert(
                        javafx.scene.control.Alert.AlertType.ERROR,
                        t("recurring.save.error") + ": " + ex.getMessage()).show());
            }
        }, "recurring-save-je").start();
    }

    /**
     * Slice 3S — Editor de recurrentes contables puros para shadow
     * companies. Genera kind=ACCOUNTING_INCOME o ACCOUNTING_EXPENSE
     * con payload completo (partyNif, partyName, base, vat, ret,
     * counterAccountCode). El backend construye el asiento de N líneas
     * con la cuenta del tercero auto-resuelta.
     *
     * <p>Diferencia clave con {@link #showJournalEntryRecurringEditor}:
     * éste lleva NIF + Nombre del tercero (cliente o proveedor) → la
     * cuenta 430.XXX o 410.XXX se crea automáticamente. Y NO lleva
     * cuenta de banco — el asiento NO se cobra/paga aún, solo se
     * devenga. El cobro/pago se hace después contra el banco vía
     * otro asiento o conciliación bancaria.
     */
    private void showAccountingRecurringEditor(
            String kind,
            com.benjagest.ui.model.AccountingModels.RecurringTask existing,
            Runnable onSaved) {
        boolean income = "ACCOUNTING_INCOME".equals(kind);
        javafx.scene.control.Dialog<javafx.scene.control.ButtonType> dlg = new javafx.scene.control.Dialog<>();
        dlg.setTitle(existing == null || existing.id() == null
                ? (income ? t("recurring.new.accounting_income")
                          : t("recurring.new.accounting_expense"))
                : t("recurring.edit") + " — " + existing.name());

        javafx.scene.control.ButtonType saveType = new javafx.scene.control.ButtonType(
                t("button.save"), javafx.scene.control.ButtonBar.ButtonData.OK_DONE);
        dlg.getDialogPane().getButtonTypes().addAll(saveType,
                javafx.scene.control.ButtonType.CANCEL);

        TextField nameField = new TextField(existing == null ? "" : nullSafe(existing.name()));
        nameField.setPromptText(income ? "Iguala mensual cliente X" : "Alquiler oficina");

        TextField descField = new TextField(existing == null ? "" : nullSafe(existing.description()));
        descField.setPromptText(t("recurring.field.description.hint"));

        javafx.scene.control.ComboBox<String> freqCombo = new javafx.scene.control.ComboBox<>();
        freqCombo.getItems().addAll("MONTHLY", "QUARTERLY", "YEARLY", "WEEKLY", "CUSTOM");
        localizeEnumCombo(freqCombo, "frequency");
        freqCombo.setValue(existing == null ? "MONTHLY" : existing.frequency());
        applyFrequencyComboCells(freqCombo);

        javafx.scene.control.Spinner<Integer> domSpinner = new javafx.scene.control.Spinner<>(
                1, 31, existing == null || existing.dayOfMonth() == null ? 1 : existing.dayOfMonth());
        domSpinner.setEditable(true);

        DatePicker firstRunDate = new DatePicker(
                existing == null ? LocalDate.now().plusDays(1) : existing.nextRunDate());

        TextField partyNifField = new TextField();
        partyNifField.setPromptText("B12345678");
        TextField partyNameField = new TextField();
        partyNameField.setPromptText(income ? "Razón social del cliente" : "Razón social del proveedor");

        TextField conceptField = new TextField();
        conceptField.setPromptText(t("recurring.field.concept.hint"));

        javafx.scene.control.ComboBox<String> counterAccountField =
                income ? buildIncomeAccountCombo() : buildExpenseAccountCombo();

        javafx.scene.control.Spinner<Double> baseSpinner =
                new javafx.scene.control.Spinner<>(0.0, 999999.0, 0.0, 10.0);
        baseSpinner.setEditable(true);
        javafx.scene.control.Spinner<Double> vatPercentSpinner =
                new javafx.scene.control.Spinner<>(0.0, 21.0, 21.0, 0.5);
        vatPercentSpinner.setEditable(true);
        javafx.scene.control.Spinner<Double> retentionPercentSpinner =
                new javafx.scene.control.Spinner<>(0.0, 30.0, 0.0, 1.0);
        retentionPercentSpinner.setEditable(true);

        Label totalLabel = new Label("0,00 €");
        totalLabel.getStyleClass().add("text-bold");
        Runnable recomputeTotal = () -> {
            double base = baseSpinner.getValue() == null ? 0 : baseSpinner.getValue();
            double vat = vatPercentSpinner.getValue() == null ? 0 : vatPercentSpinner.getValue();
            double ret = retentionPercentSpinner.getValue() == null ? 0 : retentionPercentSpinner.getValue();
            double total = base + Math.round(base * vat) / 100.0 - Math.round(base * ret) / 100.0;
            totalLabel.setText(String.format("%.2f €", total));
        };
        baseSpinner.valueProperty().addListener((o, a, b) -> recomputeTotal.run());
        vatPercentSpinner.valueProperty().addListener((o, a, b) -> recomputeTotal.run());
        retentionPercentSpinner.valueProperty().addListener((o, a, b) -> recomputeTotal.run());

        // Pre-rellenar desde payloadJson si estamos editando.
        if (existing != null && existing.payloadJson() != null) {
            String pj = existing.payloadJson();
            partyNifField.setText(nullSafe(extractStringField(pj, "partyNif")));
            partyNameField.setText(nullSafe(extractStringField(pj, "partyName")));
            conceptField.setText(nullSafe(extractStringField(pj, "concept")));
            String counterCode = extractStringField(pj, "counterAccountCode");
            if (counterCode != null && !counterCode.isBlank()) counterAccountField.setValue(counterCode);
            String base = extractStringField(pj, "baseAmount");
            if (base != null && !base.isBlank()) {
                try { baseSpinner.getValueFactory().setValue(Double.parseDouble(base)); }
                catch (NumberFormatException ignored) {}
            }
            Double vp = extractDoubleField(pj, "vatPercent");
            if (vp != null) vatPercentSpinner.getValueFactory().setValue(vp);
            Double rp = extractDoubleField(pj, "retentionPercent");
            if (rp != null) retentionPercentSpinner.getValueFactory().setValue(rp);
            recomputeTotal.run();
        }

        GridPane grid = new GridPane();
        grid.setHgap(10); grid.setVgap(8); grid.setPadding(new Insets(16));
        int r = 0;
        grid.add(new Label(t("recurring.field.name")), 0, r);
        grid.add(nameField, 1, r++, 3, 1);
        grid.add(new Label(t("recurring.field.description")), 0, r);
        grid.add(descField, 1, r++, 3, 1);
        grid.add(new Label(t("recurring.field.frequency")), 0, r);
        grid.add(freqCombo, 1, r);
        grid.add(new Label(t("recurring.freq.day")), 2, r);
        grid.add(domSpinner, 3, r++);
        grid.add(new Label(t("recurring.field.first_run")), 0, r);
        grid.add(firstRunDate, 1, r++, 3, 1);

        Label sepParty = new Label(income
                ? t("recurring.section.customer_data")
                : t("recurring.section.supplier_data"));
        sepParty.getStyleClass().add("text-bold");
        grid.add(sepParty, 0, r++, 4, 1);
        grid.add(new Label(t("recurring.field.party_nif")), 0, r);
        grid.add(partyNifField, 1, r);
        grid.add(new Label(t("recurring.field.party_name")), 2, r);
        grid.add(partyNameField, 3, r++);

        Label sepFiscal = new Label(t("recurring.section.fiscal_data"));
        sepFiscal.getStyleClass().add("text-bold");
        grid.add(sepFiscal, 0, r++, 4, 1);
        grid.add(new Label(t("recurring.field.concept")), 0, r);
        grid.add(buildConceptWithPlaceholders(conceptField), 1, r++, 3, 1);
        grid.add(new Label(income
                ? t("recurring.field.income_account")
                : t("recurring.field.expense_account")), 0, r);
        grid.add(counterAccountField, 1, r++, 3, 1);
        grid.add(new Label(t("recurring.field.base_amount")), 0, r);
        grid.add(baseSpinner, 1, r);
        grid.add(new Label(t("recurring.field.vat_percent")), 2, r);
        grid.add(vatPercentSpinner, 3, r++);
        grid.add(new Label(t("recurring.field.retention_percent")), 0, r);
        grid.add(retentionPercentSpinner, 1, r);
        grid.add(new Label(income
                ? t("recurring.field.total_to_collect")
                : t("recurring.field.total_to_pay")), 2, r);
        grid.add(totalLabel, 3, r++);

        Label hint = new Label(income
                ? t("recurring.accounting_income.hint")
                : t("recurring.accounting_expense.hint"));
        hint.getStyleClass().addAll("muted", "small");
        hint.setWrapText(true);
        grid.add(hint, 0, r++, 4, 1);

        ScrollPane scroll = new ScrollPane(grid);
        scroll.setFitToWidth(true);
        scroll.setPrefSize(700, 540);
        dlg.getDialogPane().setContent(scroll);
        dlg.setResultConverter(bt -> bt);
        var result = dlg.showAndWait();
        if (result.isEmpty() || result.get() != saveType) return;

        commitSpinner(baseSpinner);
        commitSpinner(vatPercentSpinner);
        commitSpinner(retentionPercentSpinner);
        commitSpinner(domSpinner);

        // Validaciones mínimas
        if (partyNameField.getText() == null || partyNameField.getText().isBlank()) {
            new Alert(Alert.AlertType.WARNING,
                    t("recurring.validate.party_name_required"),
                    ButtonType.OK).showAndWait();
            return;
        }
        if (baseSpinner.getValue() == null || baseSpinner.getValue() <= 0.0) {
            new Alert(Alert.AlertType.WARNING,
                    t("recurring.validate.amount_required"),
                    ButtonType.OK).showAndWait();
            return;
        }

        double base = baseSpinner.getValue();
        double vatPct = vatPercentSpinner.getValue();
        double retPct = retentionPercentSpinner.getValue();
        String counterCode = extractAccountCode(counterAccountField);
        if (counterCode == null || counterCode.isBlank()) {
            counterCode = income ? "705" : "629";
        }
        String concept = conceptField.getText() == null ? "" : conceptField.getText();

        StringBuilder body = new StringBuilder();
        body.append('{');
        appendJsonField(body, "kind", kind, true);
        appendJsonField(body, "name", nameField.getText(), false);
        if (!descField.getText().isBlank())
            appendJsonField(body, "description", descField.getText(), false);
        appendJsonField(body, "frequency", freqCombo.getValue(), false);
        if ("MONTHLY".equals(freqCombo.getValue()) || "CUSTOM".equals(freqCombo.getValue())) {
            body.append(",\"dayOfMonth\":").append(domSpinner.getValue());
        }
        body.append(",\"firstRunDate\":\"").append(firstRunDate.getValue()).append('"');
        body.append(",\"payload\":{");
        appendJsonField(body, "partyNif", partyNifField.getText(), true);
        appendJsonField(body, "partyName", partyNameField.getText(), false);
        appendJsonField(body, "concept", concept, false);
        appendJsonField(body, "counterAccountCode", counterCode, false);
        body.append(",\"baseAmount\":\"").append(base).append('"');
        body.append(",\"vatPercent\":").append(vatPct);
        body.append(",\"retentionPercent\":").append(retPct);
        body.append("}}");

        String jsonBody = body.toString();
        new Thread(() -> {
            try {
                if (existing == null || existing.id() == null) {
                    accountingApiClient.createRecurring(jsonBody);
                } else {
                    accountingApiClient.updateRecurring(existing.id(), jsonBody);
                }
                com.benjagest.ui.support.RefreshBus.emit(
                        com.benjagest.ui.support.RefreshBus.TOPIC_RECURRING);
                javafx.application.Platform.runLater(() -> {
                    if (onSaved != null) onSaved.run();
                });
            } catch (Exception ex) {
                javafx.application.Platform.runLater(() -> new javafx.scene.control.Alert(
                        javafx.scene.control.Alert.AlertType.ERROR,
                        t("recurring.save.error") + ": " + ex.getMessage()).show());
            }
        }, "recurring-save-acc").start();
    }

    private String jsonString(String raw) {
        if (raw == null) return "\"\"";
        StringBuilder sb = new StringBuilder("\"");
        for (char c : raw.toCharArray()) {
            switch (c) {
                case '"' -> sb.append("\\\"");
                case '\\' -> sb.append("\\\\");
                case '\n' -> sb.append("\\n");
                case '\r' -> sb.append("\\r");
                case '\t' -> sb.append("\\t");
                default -> sb.append(c);
            }
        }
        sb.append('"');
        return sb.toString();
    }

    private void appendJsonField(StringBuilder b, String key, String value, boolean first) {
        if (!first) b.append(',');
        b.append('"').append(key).append("\":").append(jsonString(value));
    }

    private String extractStringField(String json, String key) {
        if (json == null) return "";
        java.util.regex.Matcher m = java.util.regex.Pattern.compile(
                "\"" + java.util.regex.Pattern.quote(key) + "\"\\s*:\\s*\"((?:[^\"\\\\]|\\\\.)*)\""
        ).matcher(json);
        return m.find() ? m.group(1).replace("\\\"", "\"") : "";
    }

    private Double extractDoubleField(String json, String key) {
        if (json == null) return null;
        java.util.regex.Matcher m = java.util.regex.Pattern.compile(
                "\"" + java.util.regex.Pattern.quote(key) + "\"\\s*:\\s*([-\\d.]+)"
        ).matcher(json);
        try { return m.find() ? Double.valueOf(m.group(1)) : null; }
        catch (NumberFormatException ex) { return null; }
    }

    /**
     * Banner accionable (Slice 3D-2) que aparece arriba del listado de
     * Facturas / Compras cuando el backend detecta facturas repetidas
     * con el mismo NIF + mismo importe. Patrón visual del Slice 3B
     * (Hyperlinks azules). Si no hay candidatos, el banner se oculta
     * solo (managed=false → no ocupa hueco).
     *
     * @param kind  "SALES_INVOICE" para arriba de Facturas, "PURCHASE"
     *              para arriba de Compras.
     */
    private Node buildRecurringCandidatesBanner(String kind) {
        // Tarde 2026-06-10 (feedback Benjamin): el Hyperlink antes
        // siempre se veía como "siempre activo" porque el banner ocultaba
        // el contenedor pero no quedaba claro al usuario. Lo cambiamos
        // por un Button con estilo destacado, y el banner ENTERO solo
        // aparece cuando hay candidatos (managed/visible coordinados).
        Label icon = new Label("🔁");
        icon.setStyle("-fx-font-size: 18px;");
        Label msg = new Label();
        msg.getStyleClass().add("muted");
        msg.setWrapText(true);
        HBox.setHgrow(msg, Priority.ALWAYS);
        Button reviewBtn = new Button(t("recurring.candidates.review"));
        reviewBtn.setGraphic(icon("fas-search"));
        reviewBtn.getStyleClass().add("button-primary");
        HBox content = new HBox(8, icon, msg, reviewBtn);
        content.setAlignment(javafx.geometry.Pos.CENTER_LEFT);
        content.setPadding(new Insets(8, 12, 8, 12));
        content.setStyle("-fx-background-color: #eef3f8; -fx-background-radius: 8;");
        content.setManaged(false);
        content.setVisible(false);

        Runnable[] refreshHolder = new Runnable[1];
        refreshHolder[0] = () -> new Thread(() -> {
            try {
                var list = accountingApiClient.listRecurringCandidates(kind, 180);
                javafx.application.Platform.runLater(() -> {
                    if (list.isEmpty()) {
                        content.setManaged(false);
                        content.setVisible(false);
                    } else {
                        msg.setText(t("recurring.candidates.banner_text")
                                .replace("{n}", String.valueOf(list.size())));
                        reviewBtn.setOnAction(e ->
                                showRecurringCandidatesDialog(list, refreshHolder[0]));
                        content.setManaged(true);
                        content.setVisible(true);
                    }
                });
            } catch (Exception ex) {
                javafx.application.Platform.runLater(() -> {
                    content.setManaged(false);
                    content.setVisible(false);
                });
            }
        }, "recurring-candidates-refresh").start();

        refreshHolder[0].run();
        return content;
    }

    /**
     * Diálogo que lista los candidatos detectados. Cada fila tiene
     * un botón "Crear recurrente" que abre el editor pre-rellenado.
     * Al cerrar el editor con éxito, refresca este diálogo y el
     * banner.
     */
    private void showRecurringCandidatesDialog(
            java.util.List<com.benjagest.ui.model.AccountingModels.RecurringCandidate> candidates,
            Runnable bannerRefresh) {
        javafx.scene.control.Dialog<Void> dlg = new javafx.scene.control.Dialog<>();
        dlg.setTitle(t("recurring.candidates.title"));
        dlg.getDialogPane().getButtonTypes().add(javafx.scene.control.ButtonType.CLOSE);

        javafx.scene.control.TableView<com.benjagest.ui.model.AccountingModels.RecurringCandidate> table =
                new javafx.scene.control.TableView<>();
        table.setPlaceholder(new Label(t("recurring.candidates.empty")));
        table.setPrefSize(820, 380);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringCandidate, String> cParty =
                new javafx.scene.control.TableColumn<>(t("recurring.candidates.col.party"));
        cParty.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(
                c.getValue() == null ? "" :
                        (nullSafe(c.getValue().partyName())
                                + (c.getValue().partyNif() == null || c.getValue().partyNif().isBlank()
                                        ? "" : " (" + c.getValue().partyNif() + ")"))));
        cParty.setPrefWidth(280);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringCandidate, String> cAmount =
                new javafx.scene.control.TableColumn<>(t("recurring.candidates.col.amount"));
        cAmount.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(
                c.getValue() == null || c.getValue().totalAmount() == null ? ""
                        : c.getValue().totalAmount().toPlainString() + " €"));
        cAmount.setComparator(NUMERIC_STRING_COMPARATOR);
        cAmount.setPrefWidth(110);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringCandidate, Integer> cOcc =
                new javafx.scene.control.TableColumn<>(t("recurring.candidates.col.occurrences"));
        cOcc.setCellValueFactory(c -> new javafx.beans.property.SimpleObjectProperty<>(
                c.getValue() == null ? 0 : c.getValue().occurrences()));
        cOcc.setPrefWidth(90);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringCandidate, String> cFreq =
                new javafx.scene.control.TableColumn<>(t("recurring.candidates.col.freq"));
        cFreq.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(
                c.getValue() == null ? "" : localizedFrequency(c.getValue().suggestedFrequency())));
        cFreq.setPrefWidth(120);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringCandidate, Void> cAction =
                new javafx.scene.control.TableColumn<>(t("recurring.candidates.col.action"));
        cAction.setCellFactory(c -> new javafx.scene.control.TableCell<com.benjagest.ui.model.AccountingModels.RecurringCandidate, Void>() {
            private final Button create = new Button(t("recurring.candidates.create"));
            private final Button silence = new Button(t("recurring.candidates.silence"));
            private final HBox box2 = new HBox(6, create, silence);
            {
                create.setGraphic(icon("fas-plus"));
                create.getStyleClass().add("button-primary");
                silence.setGraphic(icon("fas-volume-mute"));
                silence.getStyleClass().add("button-secondary");
            }
            @Override protected void updateItem(Void v, boolean empty) {
                super.updateItem(v, empty);
                if (empty || getIndex() < 0 || getIndex() >= getTableView().getItems().size()) {
                    setGraphic((javafx.scene.Node) null);
                    return;
                }
                var cand = getTableView().getItems().get(getIndex());
                create.setOnAction(e -> {
                    dlg.close();
                    showRecurringEditorFromCandidate(cand, () -> {
                        if (bannerRefresh != null) bannerRefresh.run();
                    });
                });
                silence.setOnAction(e -> {
                    showRecurringSilenceDialog(cand, () -> {
                        // Reabre el diálogo con la lista actualizada.
                        dlg.close();
                        if (bannerRefresh != null) bannerRefresh.run();
                        reloadAndShowCandidatesDialog(cand.kind(), bannerRefresh);
                    });
                });
                setGraphic(box2);
            }
        });
        cAction.setPrefWidth(230);

        table.getColumns().add(cParty);
        table.getColumns().add(cAmount);
        table.getColumns().add(cOcc);
        table.getColumns().add(cFreq);
        table.getColumns().add(cAction);
        table.getItems().setAll(candidates);

        Label hint = new Label(t("recurring.candidates.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().addAll("muted", "small");

        Button viewIgnored = new Button(t("recurring.ignored.view"));
        viewIgnored.setGraphic(icon("fas-volume-mute"));
        viewIgnored.setOnAction(e -> showRecurringIgnoredDialog(() -> {
            // Si el usuario rehabilita algo, volvemos a cargar candidatos.
            String kind = candidates.isEmpty() ? "PURCHASE" : candidates.get(0).kind();
            dlg.close();
            if (bannerRefresh != null) bannerRefresh.run();
            reloadAndShowCandidatesDialog(kind, bannerRefresh);
        }));
        HBox topBar = new HBox(8, hint, new Region(), viewIgnored);
        HBox.setHgrow(topBar.getChildren().get(1), Priority.ALWAYS);

        VBox box = new VBox(8, topBar, table);
        box.setPadding(new Insets(8));
        dlg.getDialogPane().setContent(box);
        dlg.showAndWait();
    }

    /**
     * Recarga los candidatos del kind y reabre el diálogo principal.
     * Lo usamos tras silenciar / rehabilitar para que el usuario vea el
     * efecto inmediato sin tener que abrir y cerrar a mano.
     */
    private void reloadAndShowCandidatesDialog(String kind, Runnable bannerRefresh) {
        new Thread(() -> {
            try {
                var list = accountingApiClient.listRecurringCandidates(kind, 180);
                javafx.application.Platform.runLater(() ->
                        showRecurringCandidatesDialog(list, bannerRefresh));
            } catch (Exception ex) {
                javafx.application.Platform.runLater(() ->
                        showError(t("recurring.candidates.reload.fail.title"),
                                ex.getMessage()));
            }
        }, "recurring-candidates-reload").start();
    }

    /**
     * Modal "Silenciar candidato": elige rango (1/3/6/12 meses /
     * indefinido) y razón opcional. Tras OK, llama al endpoint y
     * dispara {@code onDone}.
     */
    private void showRecurringSilenceDialog(
            com.benjagest.ui.model.AccountingModels.RecurringCandidate cand,
            Runnable onDone) {
        if (cand == null) return;
        javafx.scene.control.Dialog<javafx.scene.control.ButtonType> dlg =
                new javafx.scene.control.Dialog<>();
        dlg.setTitle(t("recurring.silence.title"));
        dlg.getDialogPane().getButtonTypes().addAll(
                javafx.scene.control.ButtonType.OK,
                javafx.scene.control.ButtonType.CANCEL);

        Label sub = new Label(t("recurring.silence.subtitle")
                + " " + nullSafe(cand.partyName())
                + " · " + (cand.totalAmount() == null ? "" : cand.totalAmount().toPlainString() + " €"));
        sub.setWrapText(true);

        javafx.scene.control.ComboBox<String> range = new javafx.scene.control.ComboBox<>();
        range.getItems().addAll("M1", "M3", "M6", "M12", "INF");
        range.setValue("M6");
        range.setCellFactory(lv -> new javafx.scene.control.ListCell<>() {
            @Override protected void updateItem(String it, boolean empty) {
                super.updateItem(it, empty);
                setText(empty || it == null ? "" : silenceRangeLabel(it));
            }
        });
        range.setButtonCell(new javafx.scene.control.ListCell<>() {
            @Override protected void updateItem(String it, boolean empty) {
                super.updateItem(it, empty);
                setText(empty || it == null ? "" : silenceRangeLabel(it));
            }
        });

        javafx.scene.control.TextArea reason = new javafx.scene.control.TextArea();
        reason.setPromptText(t("recurring.silence.reason.prompt"));
        reason.setPrefRowCount(3);

        GridPane grid = new GridPane();
        grid.setHgap(10);
        grid.setVgap(8);
        grid.add(new Label(t("recurring.silence.range")), 0, 0);
        grid.add(range, 1, 0);
        grid.add(new Label(t("recurring.silence.reason")), 0, 1);
        grid.add(reason, 1, 1);

        VBox box = new VBox(10, sub, grid);
        box.setPadding(new Insets(8));
        dlg.getDialogPane().setContent(box);

        dlg.showAndWait().ifPresent(bt -> {
            if (bt != javafx.scene.control.ButtonType.OK) return;
            java.time.LocalDate until = switch (range.getValue()) {
                case "M1"  -> LocalDate.now().plusMonths(1);
                case "M3"  -> LocalDate.now().plusMonths(3);
                case "M6"  -> LocalDate.now().plusMonths(6);
                case "M12" -> LocalDate.now().plusMonths(12);
                default    -> null;
            };
            new Thread(() -> {
                try {
                    accountingApiClient.ignoreRecurringCandidate(
                            cand.kind(), cand.partyNif(), cand.partyName(),
                            cand.totalAmount(), until, reason.getText());
                    javafx.application.Platform.runLater(() -> {
                        if (onDone != null) onDone.run();
                    });
                } catch (Exception ex) {
                    javafx.application.Platform.runLater(() ->
                            showError(t("recurring.silence.fail.title"), ex.getMessage()));
                }
            }, "recurring-silence").start();
        });
    }

    private String silenceRangeLabel(String code) {
        return switch (code) {
            case "M1"  -> "1 " + t("recurring.silence.range.month");
            case "M3"  -> "3 " + t("recurring.silence.range.months");
            case "M6"  -> "6 " + t("recurring.silence.range.months");
            case "M12" -> "12 " + t("recurring.silence.range.months");
            case "INF" -> t("recurring.silence.range.indefinite");
            default    -> code;
        };
    }

    /**
     * Diálogo "Silenciados activos": tabla con columna "Rehabilitar"
     * por fila. Al rehabilitar uno, vuelve a aparecer en el detector.
     */
    private void showRecurringIgnoredDialog(Runnable onChanged) {
        javafx.scene.control.Dialog<Void> dlg = new javafx.scene.control.Dialog<>();
        dlg.setTitle(t("recurring.ignored.title"));
        dlg.getDialogPane().getButtonTypes().add(javafx.scene.control.ButtonType.CLOSE);

        javafx.scene.control.TableView<com.benjagest.ui.model.RecurringCandidateIgnoredEntry> table =
                new javafx.scene.control.TableView<>();
        table.setPlaceholder(new Label(t("recurring.ignored.empty")));
        table.setPrefSize(760, 320);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.RecurringCandidateIgnoredEntry, String> cKind =
                new javafx.scene.control.TableColumn<>(t("recurring.ignored.col.kind"));
        cKind.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(
                c.getValue() == null ? "" : kindLabel(c.getValue().kind())));
        cKind.setPrefWidth(110);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.RecurringCandidateIgnoredEntry, String> cParty =
                new javafx.scene.control.TableColumn<>(t("recurring.ignored.col.party"));
        cParty.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(
                c.getValue() == null ? "" :
                        nullSafe(c.getValue().partyNameNorm())
                                + (c.getValue().partyNif() == null || c.getValue().partyNif().isBlank()
                                        ? "" : " (" + c.getValue().partyNif() + ")")));
        cParty.setPrefWidth(240);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.RecurringCandidateIgnoredEntry, String> cAmt =
                new javafx.scene.control.TableColumn<>(t("recurring.ignored.col.amount"));
        cAmt.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(
                c.getValue() == null || c.getValue().totalAmount() == null ? ""
                        : c.getValue().totalAmount().toPlainString() + " €"));
        cAmt.setComparator(NUMERIC_STRING_COMPARATOR);
        cAmt.setPrefWidth(100);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.RecurringCandidateIgnoredEntry, String> cUntil =
                new javafx.scene.control.TableColumn<>(t("recurring.ignored.col.until"));
        cUntil.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(
                c.getValue() == null ? "" :
                        (c.getValue().ignoreUntil() == null
                                ? t("recurring.silence.range.indefinite")
                                : c.getValue().ignoreUntil().toString())));
        cUntil.setComparator(ISO_DATE_COMPARATOR);
        cUntil.setPrefWidth(120);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.RecurringCandidateIgnoredEntry, Void> cBtn =
                new javafx.scene.control.TableColumn<>(t("recurring.ignored.col.action"));
        cBtn.setCellFactory(c -> new javafx.scene.control.TableCell<com.benjagest.ui.model.RecurringCandidateIgnoredEntry, Void>() {
            private final Button rehab = new Button(t("recurring.ignored.rehabilitate"));
            { rehab.setGraphic(icon("fas-undo")); }
            @Override protected void updateItem(Void v, boolean empty) {
                super.updateItem(v, empty);
                if (empty || getIndex() < 0 || getIndex() >= getTableView().getItems().size()) {
                    setGraphic((javafx.scene.Node) null);
                    return;
                }
                var row = getTableView().getItems().get(getIndex());
                rehab.setOnAction(e -> {
                    new Thread(() -> {
                        try {
                            accountingApiClient.unignoreRecurringCandidate(row.id());
                            javafx.application.Platform.runLater(() -> {
                                table.getItems().remove(row);
                                if (onChanged != null) onChanged.run();
                            });
                        } catch (Exception ex) {
                            javafx.application.Platform.runLater(() ->
                                    showError(t("recurring.ignored.fail.title"),
                                            ex.getMessage()));
                        }
                    }, "recurring-unignore").start();
                });
                setGraphic(rehab);
            }
        });
        cBtn.setPrefWidth(140);

        table.getColumns().add(cKind);
        table.getColumns().add(cParty);
        table.getColumns().add(cAmt);
        table.getColumns().add(cUntil);
        table.getColumns().add(cBtn);

        VBox box = new VBox(8, table);
        box.setPadding(new Insets(8));
        dlg.getDialogPane().setContent(box);

        new Thread(() -> {
            try {
                var list = accountingApiClient.listIgnoredRecurringCandidates();
                javafx.application.Platform.runLater(() -> table.getItems().setAll(list));
            } catch (Exception ex) {
                javafx.application.Platform.runLater(() ->
                        showError(t("recurring.ignored.fail.title"), ex.getMessage()));
            }
        }, "recurring-ignored-load").start();

        dlg.showAndWait();
    }

    private String kindLabel(String kind) {
        if (kind == null) return "";
        return switch (kind) {
            case "SALES_INVOICE" -> t("recurring.kind.sales");
            case "PURCHASE"      -> t("recurring.kind.purchase");
            default              -> kind;
        };
    }

    /**
     * Aplica cellFactory + buttonCell a un ComboBox de frecuencias
     * para que muestre las etiquetas traducidas (Mensual/Trimestral/…)
     * en lugar de los códigos técnicos (MONTHLY/QUARTERLY/…). El
     * valor interno del ComboBox sigue siendo el código técnico para
     * que el payload del backend no cambie.
     */
    private void applyFrequencyComboCells(javafx.scene.control.ComboBox<String> combo) {
        combo.setCellFactory(lv -> new javafx.scene.control.ListCell<>() {
            @Override protected void updateItem(String item, boolean empty) {
                super.updateItem(item, empty);
                setText(empty || item == null ? "" : localizedFrequency(item));
            }
        });
        combo.setButtonCell(new javafx.scene.control.ListCell<>() {
            @Override protected void updateItem(String item, boolean empty) {
                super.updateItem(item, empty);
                setText(empty || item == null ? "" : localizedFrequency(item));
            }
        });
    }

    /**
     * Devuelve la traducción legible del código de frecuencia
     * (WEEKLY → "Semanal", MONTHLY → "Mensual", …). Reutilizable
     * desde diálogos y banners.
     */
    private String localizedFrequency(String freq) {
        if (freq == null) return "";
        return switch (freq.toUpperCase()) {
            case "WEEKLY" -> t("recurring.freq.weekly");
            case "MONTHLY" -> t("recurring.freq.monthly");
            case "QUARTERLY" -> t("recurring.freq.quarterly");
            case "YEARLY" -> t("recurring.freq.yearly");
            case "CUSTOM" -> t("recurring.freq.every") + " 6 " + t("recurring.freq.months");
            default -> freq;
        };
    }

    /**
     * Construye un RecurringTask "sintético" (id=null) con el payload
     * JSON pre-rellenado para que {@link #showRecurringEditor} lo trate
     * como modo CREAR pero con los campos ya escritos. Reutilizado por
     * los dos flujos del Slice 3D: desde candidato detectado y desde
     * "Hacer recurrente" tras validar.
     */
    private com.benjagest.ui.model.AccountingModels.RecurringTask
            buildPrefilledRecurringTask(String kind, String partyNif, String partyName,
                                         java.math.BigDecimal totalAmount,
                                         Integer dayOfMonth,
                                         String suggestedFrequency,
                                         String suggestedName) {
        boolean isSales = "SALES_INVOICE".equals(kind);
        String name = suggestedName != null && !suggestedName.isBlank()
                ? suggestedName
                : ((isSales
                        ? t("recurring.candidates.default_name_sales")
                        : t("recurring.candidates.default_name_expense"))
                    + " " + nullSafe(partyName));
        String amount = totalAmount == null ? "0" : totalAmount.toPlainString();
        String payload;
        if (isSales) {
            payload = "{\"customerNif\":" + jsonString(nullSafe(partyNif))
                    + ",\"customerLegalName\":" + jsonString(nullSafe(partyName))
                    + ",\"lines\":[{"
                    + "\"description\":" + jsonString(name)
                    + ",\"quantity\":1"
                    + ",\"unitPrice\":" + amount
                    + ",\"vatPercent\":21"
                    + ",\"retentionPercent\":0"
                    + "}]}";
        } else {
            payload = "{\"supplierNif\":" + jsonString(nullSafe(partyNif))
                    + ",\"supplierName\":" + jsonString(nullSafe(partyName))
                    + ",\"baseAmount\":" + amount
                    + ",\"vatPercent\":21"
                    + "}";
        }
        String freq = suggestedFrequency == null ? "MONTHLY" : suggestedFrequency;
        int monthsBetween = "CUSTOM".equals(freq) ? 6 : 1;
        LocalDate first = LocalDate.now().plusMonths(1);
        return new com.benjagest.ui.model.AccountingModels.RecurringTask(
                null, kind, name, "", freq,
                dayOfMonth, null, monthsBetween, first,
                null, null, 0, 0, true, payload);
    }

    /**
     * Overload del editor pre-rellenado a partir de un candidato
     * detectado por el banner (Slice 3D-2).
     */
    private void showRecurringEditorFromCandidate(
            com.benjagest.ui.model.AccountingModels.RecurringCandidate cand,
            Runnable onSaved) {
        if (cand == null) return;
        var synthetic = buildPrefilledRecurringTask(
                cand.kind(), cand.partyNif(), cand.partyName(),
                cand.totalAmount(),
                cand.lastDate() == null ? null : cand.lastDate().getDayOfMonth(),
                cand.suggestedFrequency(), null);
        showRecurringEditor(cand.kind(), synthetic, onSaved);
    }

    /**
     * Slice 3D-3 — Tras validar una venta o un gasto, ofrecer "¿hacer
     * recurrente?". Muestra un alert con dos botones; si el usuario
     * elige sí, abre el editor pre-rellenado.
     */
    private void promptMakeRecurringAfterValidation(
            String kind, String partyNif, String partyName,
            java.math.BigDecimal totalAmount, LocalDate invoiceDate) {
        Alert ask = new Alert(Alert.AlertType.CONFIRMATION,
                t("recurring.post_validate.body"),
                ButtonType.NO, ButtonType.YES);
        ask.setHeaderText(t("recurring.post_validate.title"));
        Optional<ButtonType> ans = ask.showAndWait();
        if (ans.isEmpty() || ans.get() != ButtonType.YES) {
            // Si dijo NO explícitamente, silenciar este tercero+importe para no
            // volver a preguntar (petición Benjamin 2026-06-25). Best-effort,
            // off-thread; ignoreUntil=null = indefinido.
            if (ans.isPresent() && ans.get() == ButtonType.NO) {
                new Thread(() -> {
                    try {
                        accountingApiClient.ignoreRecurringCandidate(
                                kind, partyNif, partyName, totalAmount, null,
                                "Descartado al validar");
                    } catch (Exception ignored) { /* no bloquea la validación */ }
                }, "recurring-ignore-dismiss").start();
            }
            return;
        }
        openRecurringEditorFromInvoice(kind, partyNif, partyName, totalAmount, invoiceDate);
    }

    /**
     * Slice 3E — Abre directamente el editor pre-rellenado con los
     * datos de una factura ya validada. Sin alert previo: el botón
     * "Hacer recurrente" del listado YA es una acción explícita.
     */
    private void openRecurringEditorFromInvoice(
            String kind, String partyNif, String partyName,
            java.math.BigDecimal totalAmount, LocalDate invoiceDate) {
        // Slice 3T — En shadow company (cliente sin vínculo desde
        // asesoría), las recurrentes SALES_INVOICE/PURCHASE no tienen
        // sentido porque no hay serie de facturación. Redirigir al
        // editor contable nuevo (ACCOUNTING_INCOME/EXPENSE) que genera
        // asiento directo con metadata fiscal completa.
        if (appMode == AppMode.ADVISORY
                && AuthSession.get().isActingForClient()
                && !actingForClientLinked) {
            String accountingKind = "SALES_INVOICE".equals(kind)
                    ? "ACCOUNTING_INCOME" : "ACCOUNTING_EXPENSE";
            var synthetic = buildPrefilledAccountingTask(
                    accountingKind, partyNif, partyName, totalAmount,
                    invoiceDate == null ? null : invoiceDate.getDayOfMonth());
            showAccountingRecurringEditor(accountingKind, synthetic, null);
            return;
        }
        var synthetic = buildPrefilledRecurringTask(
                kind, partyNif, partyName, totalAmount,
                invoiceDate == null ? null : invoiceDate.getDayOfMonth(),
                "MONTHLY", null);
        showRecurringEditor(kind, synthetic, null);
    }

    /**
     * Slice 3T — Construye una RecurringTask sintética pre-rellenada
     * para el editor contable (ACCOUNTING_INCOME / ACCOUNTING_EXPENSE).
     * Pensado para abrir el editor desde un botón "Hacer recurrente"
     * en el listado de facturas/gastos del cliente sin vínculo.
     */
    private com.benjagest.ui.model.AccountingModels.RecurringTask
            buildPrefilledAccountingTask(String kind, String partyNif,
                                          String partyName,
                                          java.math.BigDecimal totalAmount,
                                          Integer dayOfMonth) {
        boolean income = "ACCOUNTING_INCOME".equals(kind);
        String name = (income
                ? t("recurring.candidates.default_name_sales")
                : t("recurring.candidates.default_name_expense"))
                + " " + nullSafe(partyName);
        String amount = totalAmount == null ? "0" : totalAmount.toPlainString();
        // Heurística simple: si el importe es el TOTAL, asumir IVA 21%
        // → base = total / 1.21. El usuario lo edita en el editor.
        java.math.BigDecimal base = totalAmount == null
                ? java.math.BigDecimal.ZERO
                : totalAmount.divide(new java.math.BigDecimal("1.21"),
                        2, java.math.RoundingMode.HALF_UP);
        String counterCode = income ? "705" : "629";
        String payload = "{\"partyNif\":" + jsonString(nullSafe(partyNif))
                + ",\"partyName\":" + jsonString(nullSafe(partyName))
                + ",\"concept\":" + jsonString(name)
                + ",\"counterAccountCode\":" + jsonString(counterCode)
                + ",\"baseAmount\":\"" + base.toPlainString() + "\""
                + ",\"vatPercent\":21"
                + ",\"retentionPercent\":0"
                + "}";
        LocalDate first = LocalDate.now().plusMonths(1);
        return new com.benjagest.ui.model.AccountingModels.RecurringTask(
                null, kind, name, "", "MONTHLY",
                dayOfMonth, null, 1, first,
                null, null, 0, 0, true, payload);
    }

    /** Devuelve nombre del día de la semana 1=lunes..7=domingo. */
    private String dayName(int dow) {
        return switch (dow) {
            case 1 -> t("date.day.monday");
            case 2 -> t("date.day.tuesday");
            case 3 -> t("date.day.wednesday");
            case 4 -> t("date.day.thursday");
            case 5 -> t("date.day.friday");
            case 6 -> t("date.day.saturday");
            case 7 -> t("date.day.sunday");
            default -> "?";
        };
    }

    private Node buildClientSalesArchivedTab(
            javafx.beans.property.ObjectProperty<LocalDate> fromProp,
            javafx.beans.property.ObjectProperty<LocalDate> toProp,
            String selfTaxId) {
        javafx.scene.control.TableView<com.benjagest.ui.model.AccountingModels.DiaryEntry> table =
                new javafx.scene.control.TableView<>();
        table.getStyleClass().add("data-table");
        table.setPlaceholder(new Label(t("list.placeholder.empty")));

        // Cache cliente-side del listado COMPLETO del periodo. Los
        // filtros (texto, estado, tipo) se aplican sobre este cache
        // sin recargar del backend.
        final java.util.List<com.benjagest.ui.model.AccountingModels.DiaryEntry> cache =
                new java.util.ArrayList<>();
        // Set de SHA-256 vistos más de una vez en el cache. Usado por
        // la columna de duplicados y el banner de avisos. Se recalcula
        // cada vez que el cache cambia (recomputeIssues, más abajo).
        final java.util.Set<String> duplicateShas = new java.util.HashSet<>();

        // Slice 3B + acciones — banner de avisos con LINKS clickables.
        // Cada incidencia abre un diálogo con la lista afectada y
        // acciones contextuales (eliminar duplicados, editar nº, etc.).
        javafx.scene.control.Hyperlink dupLink = new javafx.scene.control.Hyperlink();
        javafx.scene.control.Hyperlink missLink = new javafx.scene.control.Hyperlink();
        javafx.scene.control.Hyperlink unbLink = new javafx.scene.control.Hyperlink();
        for (javafx.scene.control.Hyperlink h : new javafx.scene.control.Hyperlink[]{dupLink, missLink, unbLink}) {
            h.setStyle("-fx-text-fill: #6d4c00; -fx-underline: true;");
        }
        Label warningsIcon = new Label("⚠");
        Label sep1 = new Label("  ·  ");
        Label sep2 = new Label("  ·  ");
        sep1.setStyle("-fx-text-fill: #6d4c00;");
        sep2.setStyle("-fx-text-fill: #6d4c00;");

        HBox warningsBanner = new HBox(4, warningsIcon, dupLink, sep1, missLink, sep2, unbLink);
        warningsBanner.setStyle("-fx-background-color: #fff8e1;"
                + "-fx-background-radius: 4;"
                + "-fx-padding: 8 12 8 12;"
                + "-fx-border-color: #f0d56d;"
                + "-fx-border-radius: 4;"
                + "-fx-border-width: 1;");
        warningsBanner.setAlignment(Pos.CENTER_LEFT);
        warningsBanner.setVisible(false);
        warningsBanner.setManaged(false);

        // Click handlers — pasan el cache directamente, el filtro está
        // hecho cliente-side dentro del diálogo.
        dupLink.setOnAction(e -> showDuplicatesDialog(cache, duplicateShas));
        missLink.setOnAction(e -> showMissingNumberDialog(cache));
        unbLink.setOnAction(e -> showUnbalancedDialog(cache));

        // Columna Nº: muestra ÍNDICE DE FILA visual (1, 2, 3, …) según
        // el orden actual del listado, NO el entry_number real del
        // asiento. Esto evita que el asesor vea huecos (1, 3, 4, 9…)
        // cuando se borran asientos por duplicado. El entry_number
        // real se mantiene intacto en BD por trazabilidad contable.
        // Como no representa el asiento real, no es ordenable.
        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.DiaryEntry, Void> colNum =
                new javafx.scene.control.TableColumn<>(t("accounting.col.num"));
        colNum.setCellFactory(c -> new javafx.scene.control.TableCell<>() {
            @Override protected void updateItem(Void v, boolean empty) {
                super.updateItem(v, empty);
                if (empty || getIndex() < 0 || getIndex() >= getTableView().getItems().size()) {
                    setText("");
                } else {
                    setText(String.valueOf(getIndex() + 1));
                }
            }
        });
        colNum.setSortable(false);
        colNum.setPrefWidth(60);

        addColSorted(table, t("accounting.col.date"),
                v -> v.entryDate() == null ? "" : v.entryDate().toString(), 110, ISO_DATE_COMPARATOR);
        addCol(table, t("accounting.col.concept"),
                v -> v.concept() == null ? "" : v.concept(), 320);
        addColSorted(table, t("accounting.col.debit_total"),
                v -> v.totalDebit() == null ? "" : v.totalDebit().toString(), 110, NUMERIC_STRING_COMPARATOR);
        addCol(table, t("accounting.col.status"),
                v -> v.status() == null ? "" : t("accounting.status." + v.status()), 110);

        table.getColumns().add(0, colNum);

        // Filtros internos (Slice 2B):
        //   - Buscar: matchea sobre concepto + nº.
        //   - Estado: TODOS | DRAFT (por validar) | POSTED (validado) | VOIDED.
        //   - Tipo:   TODOS | NORMAL | RECTIFICATIVA (total negativo
        //             o concepto con "rectific"/"abono").
        TextField search = new TextField();
        search.setPromptText(t("client.filter.search_prompt"));
        search.setPrefColumnCount(20);

        ComboBox<String> statusFilter = new ComboBox<>(javafx.collections.FXCollections.observableArrayList(
                "", "DRAFT", "POSTED", "VOIDED"));
        statusFilter.setValue("");
        statusFilter.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(String s) {
                return s == null || s.isBlank()
                        ? t("client.filter.status.all")
                        : t("accounting.status." + s);
            }
            @Override public String fromString(String s) { return s; }
        });

        ComboBox<String> typeFilter = new ComboBox<>(javafx.collections.FXCollections.observableArrayList(
                "", "NORMAL", "RECT"));
        typeFilter.setValue("");
        typeFilter.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(String s) {
                return s == null || s.isBlank() ? t("client.filter.type.all")
                        : "RECT".equals(s) ? t("client.filter.type.rectifying")
                        : t("client.filter.type.normal");
            }
            @Override public String fromString(String s) { return s; }
        });

        Runnable applyFilters = () -> {
            // Recalcular duplicados + métricas para el banner de avisos
            // antes de filtrar. Es barato (O(n) sobre cache de 50-200).
            duplicateShas.clear();
            java.util.Map<String, Integer> shaCount = new java.util.HashMap<>();
            int missingNumber = 0;
            int unbalanced = 0;
            for (var e : cache) {
                if (e.sourcePdfSha256() != null && !e.sourcePdfSha256().isBlank()) {
                    shaCount.merge(e.sourcePdfSha256(), 1, Integer::sum);
                }
                String concept = e.concept() == null ? "" : e.concept();
                boolean noNum = concept.toLowerCase().startsWith("venta importada")
                        || (concept.contains("Fra.")
                                && !concept.matches(".*Fra\\.\\s*[A-Z0-9].*\\d.*"));
                if (noNum) missingNumber++;
                if (e.totalDebit() != null && e.totalCredit() != null) {
                    var diff = e.totalDebit().subtract(e.totalCredit()).abs();
                    if (diff.compareTo(new java.math.BigDecimal("0.01")) > 0) {
                        unbalanced++;
                    }
                }
            }
            int dupCount = 0;
            for (var en : shaCount.entrySet()) {
                if (en.getValue() > 1) {
                    duplicateShas.add(en.getKey());
                    dupCount += en.getValue();
                }
            }
            // Actualizar banner — cada link visible solo si tiene cuenta > 0.
            final int dupCountF = dupCount;
            final int missF = missingNumber;
            final int unbF = unbalanced;
            dupLink.setText(t("client.warnings.duplicates")
                    .replace("{n}", String.valueOf(dupCountF)));
            dupLink.setVisible(dupCountF > 0);
            dupLink.setManaged(dupCountF > 0);
            missLink.setText(t("client.warnings.missing_number")
                    .replace("{n}", String.valueOf(missF)));
            missLink.setVisible(missF > 0);
            missLink.setManaged(missF > 0);
            unbLink.setText(t("client.warnings.unbalanced")
                    .replace("{n}", String.valueOf(unbF)));
            unbLink.setVisible(unbF > 0);
            unbLink.setManaged(unbF > 0);
            // Separadores: solo visibles si flanquean dos links activos.
            sep1.setVisible(dupCountF > 0 && missF > 0);
            sep1.setManaged(sep1.isVisible());
            sep2.setVisible((dupCountF > 0 || missF > 0) && unbF > 0);
            sep2.setManaged(sep2.isVisible());
            boolean anyIssue = dupCountF > 0 || missF > 0 || unbF > 0;
            warningsBanner.setVisible(anyIssue);
            warningsBanner.setManaged(anyIssue);

            // Filtrado de la tabla con los criterios del usuario.
            String q = search.getText() == null ? ""
                    : search.getText().trim().toLowerCase();
            String st = statusFilter.getValue();
            String tp = typeFilter.getValue();
            javafx.collections.ObservableList<com.benjagest.ui.model.AccountingModels.DiaryEntry> filtered =
                    javafx.collections.FXCollections.observableArrayList();
            for (var e : cache) {
                if (!q.isEmpty()) {
                    String haystack =
                            (e.concept() == null ? "" : e.concept().toLowerCase())
                            + " " + e.entryNumber();
                    if (!haystack.contains(q)) continue;
                }
                if (st != null && !st.isBlank()
                        && !st.equalsIgnoreCase(e.status())) continue;
                if (tp != null && !tp.isBlank()) {
                    boolean isRect = isLikelyRectifying(e);
                    if ("RECT".equals(tp) && !isRect) continue;
                    if ("NORMAL".equals(tp) && isRect) continue;
                }
                filtered.add(e);
            }
            table.setItems(filtered);
        };
        search.textProperty().addListener((o, a, b) -> applyFilters.run());
        statusFilter.valueProperty().addListener((o, a, b) -> applyFilters.run());
        typeFilter.valueProperty().addListener((o, a, b) -> applyFilters.run());

        Button refresh = new Button(t("accounting.action.refresh"));
        refresh.setOnAction(e -> loadClientSalesArchived(table, cache,
                fromProp.get(), toProp.get(), applyFilters));

        // Slice 2C: si tenemos el NIF del cliente activo, el botón hace
        // auto-detección por PDF (venta vs gasto comparando NIF emisor).
        // Sin NIF (callsite legacy), se mantiene el comportamiento solo
        // venta.
        Button importBtn = new Button(selfTaxId == null || selfTaxId.isBlank()
                ? t("sales.action.import_pdfs")
                : t("client.action.import_pdfs_auto"));
        importBtn.setGraphic(icon("fas-file-import"));
        importBtn.getStyleClass().add("button-primary");
        if (selfTaxId == null || selfTaxId.isBlank()) {
            importBtn.setOnAction(e -> importSalesPdfsMulti());
        } else {
            importBtn.setOnAction(e -> importPdfsAuto(selfTaxId));
        }

        Region spacer = new Region();
        HBox.setHgrow(spacer, Priority.ALWAYS);
        // Slice 3T — Botón "Hacer recurrente" para asientos de venta
        // POSTED del cliente NO vinculado. Como aquí ya estamos dentro
        // de la asesoría actuando como cliente shadow, openRecurring
        // EditorFromInvoice redirigirá automáticamente al editor
        // contable nuevo (ACCOUNTING_INCOME).
        Button makeRecurringBtnSales = new Button(t("list.action.make_recurring"));
        makeRecurringBtnSales.setGraphic(icon("fas-arrows-rotate"));
        makeRecurringBtnSales.setDisable(true);
        table.getSelectionModel().selectedItemProperty().addListener((o, ov, nv) -> {
            boolean ok = nv != null && "POSTED".equalsIgnoreCase(nv.status());
            makeRecurringBtnSales.setDisable(!ok);
        });
        makeRecurringBtnSales.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null) return;
            openRecurringEditorFromInvoice(
                    "SALES_INVOICE",
                    null,
                    sel.concept(), // tampoco hay legalName, usamos concept como hint
                    sel.totalDebit(),
                    sel.entryDate());
        });

        HBox filtersRow = new HBox(8,
                new Label(t("client.filter.search")), search,
                new Label(t("client.filter.status")), statusFilter,
                new Label(t("client.filter.type")), typeFilter,
                spacer, makeRecurringBtnSales, refresh, importBtn);
        filtersRow.setAlignment(Pos.CENTER_LEFT);

        com.benjagest.ui.support.RefreshBus.subscribe(
                com.benjagest.ui.support.RefreshBus.TOPIC_JOURNAL,
                () -> loadClientSalesArchived(table, cache,
                        fromProp.get(), toProp.get(), applyFilters), table);
        com.benjagest.ui.support.RefreshBus.subscribe(
                com.benjagest.ui.support.RefreshBus.TOPIC_SALES,
                () -> loadClientSalesArchived(table, cache,
                        fromProp.get(), toProp.get(), applyFilters), table);

        // Cuando cambia el periodo de los KPIs, recargamos.
        fromProp.addListener((o, a, b) -> loadClientSalesArchived(
                table, cache, fromProp.get(), toProp.get(), applyFilters));
        toProp.addListener((o, a, b) -> loadClientSalesArchived(
                table, cache, fromProp.get(), toProp.get(), applyFilters));

        // Slice 3A — columna "Dup" que marca con punto rojo las filas
        // cuyo SHA-256 aparece 2+ veces en el cache (= mismo PDF
        // importado varias veces). Se inserta como segunda columna
        // (tras Nº).
        //
        // Antes la cabecera era "⚠" (Unicode WARNING SIGN U+26A0), pero
        // en muchas fuentes de Windows se renderiza como un triángulo
        // SIN color de relleno → aparece como un "triángulo blanco"
        // pegado a la columna Nº y confunde al asesor. Por eso
        // pasamos a una cabecera textual i18n.
        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.DiaryEntry, String> colWarn =
                new javafx.scene.control.TableColumn<>(t("accounting.col.dup"));
        colWarn.setCellValueFactory(c -> {
            var e = c.getValue();
            return new javafx.beans.property.SimpleStringProperty(
                    e != null && e.sourcePdfSha256() != null
                            && duplicateShas.contains(e.sourcePdfSha256())
                            ? "●" : "");
        });
        // Color rojo de la paleta del app.css (#dc2626 = status-dot-error)
        // en hex literal — no usamos lookup CSS porque la columna se
        // crea programáticamente y JavaFX no resuelve variables
        // declaradas en .root cuando el estilo es inline.
        colWarn.setStyle("-fx-alignment: CENTER; -fx-text-fill: #dc2626; -fx-font-weight: bold;");
        colWarn.setPrefWidth(44);
        colWarn.setSortable(false);
        table.getColumns().add(1, colWarn);

        VBox box = new VBox(8, warningsBanner, filtersRow, table);
        VBox.setVgrow(table, Priority.ALWAYS);
        box.setPadding(new Insets(12));
        loadClientSalesArchived(table, cache, fromProp.get(), toProp.get(),
                applyFilters);
        return box;
    }

    /**
     * Diálogo accionable para resolver duplicados. Agrupa los asientos
     * del cache por SHA, muestra cada grupo + acciones:
     *  - Por grupo: "Conservar el primero, eliminar el resto" (1 click).
     *  - "Resolver TODOS (conservar el más antiguo de cada grupo)" para
     *    barrer la lista de un golpe.
     *
     * Backend: POST /api/accounting/duplicates/delete con ids a borrar.
     */
    private void showDuplicatesDialog(
            java.util.List<com.benjagest.ui.model.AccountingModels.DiaryEntry> cache,
            java.util.Set<String> duplicateShas) {
        // Agrupar por SHA solo los duplicados.
        java.util.LinkedHashMap<String, java.util.List<com.benjagest.ui.model.AccountingModels.DiaryEntry>> groups =
                new java.util.LinkedHashMap<>();
        for (var e : cache) {
            String sha = e.sourcePdfSha256();
            if (sha != null && duplicateShas.contains(sha)) {
                groups.computeIfAbsent(sha, k -> new java.util.ArrayList<>()).add(e);
            }
        }
        // Ordenar cada grupo por entryNumber asc — el primero es el "más
        // antiguo/canónico"; los siguientes son las copias a eliminar.
        for (var list : groups.values()) {
            list.sort(java.util.Comparator.comparingInt(
                    com.benjagest.ui.model.AccountingModels.DiaryEntry::entryNumber));
        }

        Dialog<ButtonType> dialog = new Dialog<>();
        dialog.setTitle(t("client.duplicates.title"));
        dialog.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);

        VBox container = new VBox(10);
        container.setPadding(new Insets(12));

        Label hint = new Label(t("client.duplicates.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");
        container.getChildren().add(hint);

        // Mapa entryId → RadioButton para construir la lista de
        // "qué conservar" cuando el usuario pulsa Aplicar.
        java.util.Map<String, javafx.scene.control.RadioButton> keepRadios =
                new java.util.LinkedHashMap<>();
        // Mapa grupo → todos los entryIds del grupo, para sacar el
        // complemento al "kept".
        java.util.List<java.util.List<String>> groupIdLists = new java.util.ArrayList<>();

        Button applyBtn = new Button();
        applyBtn.getStyleClass().add("button-primary");

        // Por cada grupo, un bloque con radios "Conservar" + datos.
        for (var entry : groups.entrySet()) {
            var list = entry.getValue();
            VBox groupBox = new VBox(4);
            groupBox.setStyle("-fx-background-color: #f7f7f7;"
                    + "-fx-padding: 8 10 8 10;"
                    + "-fx-background-radius: 4;");
            Label groupTitle = new Label(t("client.duplicates.group")
                    .replace("{n}", String.valueOf(list.size()))
                    .replace("{sha}", entry.getKey().substring(0,
                            Math.min(12, entry.getKey().length())) + "…"));
            groupTitle.setStyle("-fx-font-weight: bold;");
            groupBox.getChildren().add(groupTitle);

            javafx.scene.control.ToggleGroup tg = new javafx.scene.control.ToggleGroup();
            java.util.List<String> idsThisGroup = new java.util.ArrayList<>();
            for (int i = 0; i < list.size(); i++) {
                var dEntry = list.get(i);
                javafx.scene.control.RadioButton radio =
                        new javafx.scene.control.RadioButton();
                radio.setToggleGroup(tg);
                // Por defecto seleccionamos el PRIMERO de cada grupo
                // (el más antiguo por entryNumber, que suele ser el
                // canónico). El usuario puede cambiarlo a otro.
                if (i == 0) radio.setSelected(true);

                Label info = new Label(
                        "Nº " + (dEntry.entryNumber() <= 0 ? "—" : dEntry.entryNumber())
                        + "  ·  " + (dEntry.entryDate() == null ? "" : dEntry.entryDate())
                        + "  ·  " + (dEntry.concept() == null ? "" :
                                (dEntry.concept().length() > 60
                                        ? dEntry.concept().substring(0, 60) + "…"
                                        : dEntry.concept()))
                        + "  ·  " + formatMoney(dEntry.totalDebit()));
                HBox row = new HBox(8, radio, info);
                row.setAlignment(Pos.CENTER_LEFT);
                groupBox.getChildren().add(row);

                keepRadios.put(dEntry.id(), radio);
                idsThisGroup.add(dEntry.id());
            }
            groupIdLists.add(idsThisGroup);
            container.getChildren().add(groupBox);
        }

        // Recalcular el contador del botón cada vez que el usuario
        // cambia un radio. Total a borrar = (totalCopias) - (1 kept
        // por grupo). Como cada ToggleGroup garantiza exactamente 1
        // seleccionado, es simple: sum(group.size()-1) por grupo.
        Runnable updateApplyButton = () -> {
            int toDelete = 0;
            for (var grp : groupIdLists) toDelete += grp.size() - 1;
            applyBtn.setText(t("client.duplicates.apply")
                    .replace("{n}", String.valueOf(toDelete)));
            applyBtn.setDisable(toDelete <= 0);
        };
        for (var r : keepRadios.values()) {
            r.selectedProperty().addListener((o, a, b) -> updateApplyButton.run());
        }
        updateApplyButton.run();

        if (groupIdLists.isEmpty()) {
            Label empty = new Label(t("client.duplicates.none"));
            empty.getStyleClass().add("settings-hint");
            container.getChildren().add(empty);
        } else {
            // Atajos: conservar el más antiguo / más reciente de cada
            // grupo de un click. Útiles si el asesor tiene 10 grupos
            // y todos tienen el mismo criterio.
            Button keepOldestBtn = new Button(t("client.duplicates.keep_oldest"));
            keepOldestBtn.setOnAction(e -> {
                for (var grp : groupIdLists) {
                    keepRadios.get(grp.get(0)).setSelected(true);
                }
            });
            Button keepNewestBtn = new Button(t("client.duplicates.keep_newest"));
            keepNewestBtn.setOnAction(e -> {
                for (var grp : groupIdLists) {
                    keepRadios.get(grp.get(grp.size() - 1)).setSelected(true);
                }
            });

            applyBtn.setOnAction(e -> {
                // Calcular ids a eliminar = TODOS los del grupo menos
                // el "kept" (radio seleccionado).
                java.util.List<String> idsToDelete = new java.util.ArrayList<>();
                for (var grp : groupIdLists) {
                    for (String id : grp) {
                        if (!keepRadios.get(id).isSelected()) idsToDelete.add(id);
                    }
                }
                if (idsToDelete.isEmpty()) return;
                applyBtn.setDisable(true);
                Task<Integer> task = new Task<>() {
                    @Override protected Integer call() throws Exception {
                        return accountingApiClient.deleteImportedEntries(idsToDelete);
                    }
                };
                task.setOnSucceeded(ev -> {
                    showInfo(t("client.duplicates.done.title"),
                            t("client.duplicates.done.body")
                                    .replace("{n}", String.valueOf(task.getValue())));
                    com.benjagest.ui.support.RefreshBus.emit(
                            com.benjagest.ui.support.RefreshBus.TOPIC_JOURNAL,
                            com.benjagest.ui.support.RefreshBus.TOPIC_SALES);
                    dialog.setResult(ButtonType.CLOSE);
                    dialog.close();
                });
                task.setOnFailed(ev -> {
                    applyBtn.setDisable(false);
                    Throwable ex = task.getException();
                    showError(t("client.duplicates.fail.title"),
                            ex == null ? "" : ex.getMessage());
                });
                start(task, "delete-duplicates");
            });

            Region actionsSpacer = new Region();
            HBox.setHgrow(actionsSpacer, Priority.ALWAYS);
            HBox actions = new HBox(8, keepOldestBtn, keepNewestBtn,
                    actionsSpacer, applyBtn);
            actions.setAlignment(Pos.CENTER_LEFT);
            container.getChildren().add(actions);
        }

        ScrollPane scroll = new ScrollPane(container);
        scroll.setFitToWidth(true);
        installDialog(dialog, scroll);
        dialog.getDialogPane().setPrefSize(900, 600);
        dialog.showAndWait();
    }

    /**
     * Diálogo de "asientos sin nº de factura". Por ahora solo lista —
     * el botón "Editar" llama a {@link #openEntryEditorInDiary} para
     * que el asesor edite el concepto del asiento. La re-extracción
     * con PDF viene en un slice futuro.
     */
    private void showMissingNumberDialog(
            java.util.List<com.benjagest.ui.model.AccountingModels.DiaryEntry> cache) {
        java.util.List<com.benjagest.ui.model.AccountingModels.DiaryEntry> affected = new java.util.ArrayList<>();
        for (var e : cache) {
            String c = e.concept() == null ? "" : e.concept();
            boolean noNum = c.toLowerCase().startsWith("venta importada")
                    || (c.contains("Fra.")
                            && !c.matches(".*Fra\\.\\s*[A-Z0-9].*\\d.*"));
            if (noNum) affected.add(e);
        }
        Dialog<ButtonType> dialog = new Dialog<>();
        dialog.setTitle(t("client.missing.title"));
        dialog.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);

        VBox box = new VBox(8);
        box.setPadding(new Insets(12));
        Label hint = new Label(t("client.missing.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");
        box.getChildren().add(hint);
        if (affected.isEmpty()) {
            Label empty = new Label(t("client.missing.none"));
            empty.getStyleClass().add("settings-hint");
            box.getChildren().add(empty);
        }
        for (var e : affected) {
            HBox row = new HBox(8);
            row.setAlignment(Pos.CENTER_LEFT);
            row.setStyle("-fx-background-color: #fafafa; -fx-padding: 6 10 6 10;"
                    + "-fx-background-radius: 4;");
            Label desc = new Label(
                    "Nº " + (e.entryNumber() <= 0 ? "—" : e.entryNumber())
                    + "  ·  " + (e.entryDate() == null ? "" : e.entryDate())
                    + "  ·  " + (e.concept() == null ? "" :
                            (e.concept().length() > 80
                                    ? e.concept().substring(0, 80) + "…"
                                    : e.concept()))
                    + "  ·  " + formatMoney(e.totalDebit()));
            HBox.setHgrow(desc, Priority.ALWAYS);
            Button openBtn = new Button(t("client.missing.action.edit"));
            openBtn.setOnAction(ev -> showEditConceptDialog(e));
            row.getChildren().addAll(desc, openBtn);
            box.getChildren().add(row);
        }
        ScrollPane scroll = new ScrollPane(box);
        scroll.setFitToWidth(true);
        installDialog(dialog, scroll);
        dialog.getDialogPane().setPrefSize(900, 600);
        dialog.showAndWait();
    }

    /** Diálogo de descuadres — solo lista por ahora. */
    private void showUnbalancedDialog(
            java.util.List<com.benjagest.ui.model.AccountingModels.DiaryEntry> cache) {
        java.util.List<com.benjagest.ui.model.AccountingModels.DiaryEntry> affected = new java.util.ArrayList<>();
        for (var e : cache) {
            if (e.totalDebit() == null || e.totalCredit() == null) continue;
            var diff = e.totalDebit().subtract(e.totalCredit()).abs();
            if (diff.compareTo(new java.math.BigDecimal("0.01")) > 0) affected.add(e);
        }
        Dialog<ButtonType> dialog = new Dialog<>();
        dialog.setTitle(t("client.unbalanced.title"));
        dialog.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);

        VBox box = new VBox(6);
        box.setPadding(new Insets(12));
        Label hint = new Label(t("client.unbalanced.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");
        box.getChildren().add(hint);
        for (var e : affected) {
            Label row = new Label(
                    "Nº " + (e.entryNumber() <= 0 ? "—" : e.entryNumber())
                    + "  ·  " + (e.entryDate() == null ? "" : e.entryDate())
                    + "  ·  D=" + formatMoney(e.totalDebit())
                    + "  ·  H=" + formatMoney(e.totalCredit())
                    + "  ·  Δ=" + formatMoney(
                            e.totalDebit().subtract(e.totalCredit())));
            row.setStyle("-fx-background-color: #fafafa; -fx-padding: 6 10 6 10;"
                    + "-fx-background-radius: 4;");
            box.getChildren().add(row);
        }
        if (affected.isEmpty()) {
            Label empty = new Label(t("client.unbalanced.none"));
            empty.getStyleClass().add("settings-hint");
            box.getChildren().add(empty);
        }
        ScrollPane scroll = new ScrollPane(box);
        scroll.setFitToWidth(true);
        installDialog(dialog, scroll);
        dialog.getDialogPane().setPrefSize(900, 500);
        dialog.showAndWait();
    }

    /**
     * Diálogo para editar el concepto de un asiento. Incluye botón
     * "Re-extraer del PDF" que usa la regex/heurística actual sobre
     * el PDF asociado y propone el nº de factura nuevo. El asesor
     * decide aceptar la propuesta o escribir manualmente.
     */
    private void showEditConceptDialog(
            com.benjagest.ui.model.AccountingModels.DiaryEntry entry) {
        Dialog<ButtonType> dialog = new Dialog<>();
        dialog.setTitle(t("client.edit_concept.title"));
        ButtonType saveBt = new ButtonType(t("client.edit_concept.save"),
                ButtonBar.ButtonData.OK_DONE);
        ButtonType cancelBt = new ButtonType(t("client.edit_concept.cancel"),
                ButtonBar.ButtonData.CANCEL_CLOSE);
        dialog.getDialogPane().getButtonTypes().addAll(saveBt, cancelBt);

        VBox body = new VBox(10);
        body.setPadding(new Insets(12));

        Label header = new Label(
                "Nº " + (entry.entryNumber() <= 0 ? "—" : entry.entryNumber())
                + "  ·  " + (entry.entryDate() == null ? "" : entry.entryDate()));
        header.setStyle("-fx-font-weight: bold;");

        Label hint = new Label(t("client.edit_concept.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        TextField conceptField = new TextField(entry.concept() == null ? "" : entry.concept());
        conceptField.setPrefColumnCount(60);

        Label suggestionLabel = new Label("");
        suggestionLabel.setWrapText(true);
        suggestionLabel.setStyle("-fx-text-fill: #2e7d32;");
        suggestionLabel.setVisible(false);
        suggestionLabel.setManaged(false);

        Button reExtractBtn = new Button(t("client.edit_concept.re_extract"));
        reExtractBtn.setGraphic(icon("fas-magic"));
        reExtractBtn.setOnAction(e -> {
            reExtractBtn.setDisable(true);
            suggestionLabel.setVisible(false);
            suggestionLabel.setManaged(false);
            Task<java.util.Map<String, String>> task = new Task<>() {
                @Override protected java.util.Map<String, String> call() throws Exception {
                    return accountingApiClient.reExtractEntryFromPdf(entry.id());
                }
            };
            task.setOnSucceeded(ev -> {
                reExtractBtn.setDisable(false);
                var data = task.getValue();
                String num = data.getOrDefault("invoiceNumber", "");
                String name = data.getOrDefault("receiverName", "");
                if (num.isBlank() && name.isBlank()) {
                    suggestionLabel.setText(t("client.edit_concept.no_suggestion"));
                    suggestionLabel.setStyle("-fx-text-fill: #c62828;");
                } else {
                    // Construir la propuesta con el formato del backend.
                    StringBuilder proposed = new StringBuilder("Fra. ");
                    if (!num.isBlank()) proposed.append(num).append(' ');
                    if (!name.isBlank()) proposed.append("a ").append(name);
                    suggestionLabel.setText(
                            t("client.edit_concept.suggestion") + "  " + proposed);
                    suggestionLabel.setStyle("-fx-text-fill: #2e7d32;");
                    // Botón "Usar esta sugerencia" inline en el label
                    // via click handler — simple click rellena el campo.
                    suggestionLabel.setOnMouseClicked(mc -> conceptField.setText(
                            proposed.toString().trim()));
                    suggestionLabel.setStyle(suggestionLabel.getStyle()
                            + " -fx-cursor: hand; -fx-underline: true;");
                }
                suggestionLabel.setVisible(true);
                suggestionLabel.setManaged(true);
            });
            task.setOnFailed(ev -> {
                reExtractBtn.setDisable(false);
                Throwable ex = task.getException();
                showError(t("client.edit_concept.re_extract_fail.title"),
                        ex == null ? "" : ex.getMessage());
            });
            start(task, "re-extract");
        });

        body.getChildren().addAll(header, hint,
                new Label(t("client.edit_concept.concept_label")), conceptField,
                reExtractBtn, suggestionLabel);

        installDialog(dialog, body);
        dialog.getDialogPane().setPrefWidth(600);

        Button saveBtn = (Button) dialog.getDialogPane().lookupButton(saveBt);
        saveBtn.getStyleClass().add("button-primary");
        saveBtn.addEventFilter(javafx.event.ActionEvent.ACTION, ev -> {
            ev.consume();
            String newConcept = conceptField.getText() == null ? "" : conceptField.getText().trim();
            saveBtn.setDisable(true);
            Task<Boolean> task = new Task<>() {
                @Override protected Boolean call() throws Exception {
                    return accountingApiClient.updateEntryConcept(entry.id(), newConcept);
                }
            };
            task.setOnSucceeded(e -> {
                if (task.getValue()) {
                    com.benjagest.ui.support.RefreshBus.emit(
                            com.benjagest.ui.support.RefreshBus.TOPIC_JOURNAL);
                    dialog.setResult(saveBt);
                    dialog.close();
                } else {
                    saveBtn.setDisable(false);
                    showError(t("client.edit_concept.save_fail.title"),
                            t("client.edit_concept.save_fail.body"));
                }
            });
            task.setOnFailed(e -> {
                saveBtn.setDisable(false);
                Throwable ex = task.getException();
                showError(t("client.edit_concept.save_fail.title"),
                        ex == null ? "" : ex.getMessage());
            });
            start(task, "update-concept");
        });

        dialog.showAndWait();
    }

    /**
     * Heurística rápida cliente-side para distinguir rectificativa de
     * factura normal sin tocar el backend:
     *   - Total negativo (debe o haber) → rectificativa
     *   - Concepto contiene "rectific" / "abono" / "anula" → rectificativa
     */
    private boolean isLikelyRectifying(com.benjagest.ui.model.AccountingModels.DiaryEntry e) {
        if (e == null) return false;
        if (e.totalDebit() != null && e.totalDebit().signum() < 0) return true;
        if (e.totalCredit() != null && e.totalCredit().signum() < 0) return true;
        String concept = e.concept() == null ? "" : e.concept().toLowerCase();
        if (concept.contains("rectific") || concept.contains("abono")
                || concept.contains("anula")) return true;
        return false;
    }

    /**
     * Carga las ventas archivadas (asientos con
     * {@code source_type='SALES_PDF_IMPORT'}) del cliente activo via
     * actingForCompanyId. Filtra por rango de fechas (periodo activo
     * desde el selector trimestre/año de los KPIs).
     */
    private void loadClientSalesArchived(
            javafx.scene.control.TableView<com.benjagest.ui.model.AccountingModels.DiaryEntry> table,
            java.util.List<com.benjagest.ui.model.AccountingModels.DiaryEntry> cache,
            LocalDate from, LocalDate to,
            Runnable applyFilters) {
        Task<java.util.List<com.benjagest.ui.model.AccountingModels.DiaryEntry>> task = new Task<>() {
            @Override
            protected java.util.List<com.benjagest.ui.model.AccountingModels.DiaryEntry> call()
                    throws Exception {
                // Sin filtro de status: DRAFT + POSTED juntos. El periodo
                // viene del selector de arriba (compartido con KPIs).
                // Slice 3U — Listado centralizado de TODAS las ventas
                // del cliente: facturas emitidas/validadas en BENJAGEST
                // (SALES_INVOICE), facturas importadas por PDF
                // (SALES_PDF_IMPORT) y plantillas contables ejecutadas
                // por el cron (RECURRING_ACCOUNTING). Todas se ven en
                // el mismo listado — el asesor no tiene que saltar de
                // pantalla según el origen.
                return accountingApiClient.diary(from, to, null,
                        // Slice 3X — Las recurrentes ya guardan con
                        // source_type SALES_INVOICE; no hace falta
                        // RECURRING_ACCOUNTING aquí.
                        "SALES_INVOICE,SALES_PDF_IMPORT", 500);
            }
        };
        task.setOnSucceeded(ev -> {
            cache.clear();
            cache.addAll(task.getValue());
            applyFilters.run();
        });
        task.setOnFailed(ev -> System.err.println("[client-sales-archived] "
                + (task.getException() == null ? "?" : task.getException().getMessage())));
        start(task, "client-sales-archived");
    }

    /**
     * TPB-CLIENT-SETUP F3 — Sub-pestaña "Config. facturación" del
     * titular: reusa la pantalla de configuracion de facturacion
     * (billingConfigTab) cargada bajo el tenant del cliente. Permite a
     * la asesoria elegir VERIFACTU / NO_VERIFACTU para el cliente,
     * configurar series, textos y certificado. El boton Guardar
     * persiste bajo la shadow company del titular (actingForCompanyId).
     */
    private Node buildClientBillingConfigTab() {
        VBox holder = new VBox();
        holder.setPadding(new Insets(12));
        Label loading = new Label(t("panorama.loading"));
        loading.getStyleClass().add("settings-hint");
        holder.getChildren().add(loading);
        Task<BillingBundle> task = new Task<>() {
            @Override
            protected BillingBundle call() throws Exception {
                List<SeriesEntry> series = billingApiClient.listSeries();
                VerifactuConfig vfConfig = billingApiClient.getVerifactuConfig();
                InvoiceTexts texts = billingApiClient.getInvoiceTexts();
                List<CertificateOption> certificates;
                try { certificates = billingApiClient.listCertificateOptions(); }
                catch (Exception ignored) { certificates = List.of(); }
                return new BillingBundle(List.of(), series, vfConfig, texts, certificates);
            }
        };
        task.setOnSucceeded(ev -> {
            var b = task.getValue();
            VBox wrap = new VBox(billingConfigTab(b.verifactuConfig(), b.series(),
                    b.certificates(), b.invoiceTexts()));
            holder.getChildren().setAll(scroll(wrap));
        });
        task.setOnFailed(ev -> holder.getChildren().setAll(
                errorPanel(t("billing.shell.load_failed"))));
        start(task, "client-billing-config-load");
        return holder;
    }

