    /** Sub-pestaña "Perfiles" — lista + editor de autónomos (retaView async). */
    private Node buildRetaProfilesHolder() {
        VBox holder = new VBox();
        Label loading = new Label(t("panorama.loading"));
        loading.getStyleClass().add("settings-hint");
        loading.setPadding(new Insets(12));
        holder.getChildren().add(loading);
        VBox.setVgrow(holder, Priority.ALWAYS);
        Task<java.util.List<com.benjagest.ui.model.RetaProfileEntry>> task = new Task<>() {
            @Override protected java.util.List<com.benjagest.ui.model.RetaProfileEntry> call() throws Exception {
                // RETA-4: crea el perfil del autónomo si falta (empresa AUTONOMO o
                // titular RETA) antes de listar, para que no salga vacío.
                try { laborApiClient.ensureRetaProfiles(); } catch (Exception ignored) { }
                return laborApiClient.listRetaProfiles(true);
            }
        };
        task.setOnSucceeded(ev -> holder.getChildren().setAll(scroll(retaView(task.getValue()))));
        task.setOnFailed(ev -> holder.getChildren().setAll(errorPanel(t("reta.load_failed"))));
        start(task, "client-reta-load");
        return holder;
    }

    private Node buildClientLaborTab() {
        VBox holder = new VBox();
        holder.setPadding(new Insets(12));
        // BUG-NAV-1 — embebido en la ficha: el refresco tras una acción
        // recarga ESTE holder en su sitio, sin reemplazar el centro (que
        // borraría las pestañas de la ficha). loadLaborIntoHolder es la
        // versión reusable del cargador (también lo invoca laborRefresh).
        laborRefresh = () -> loadLaborIntoHolder(holder);
        loadLaborIntoHolder(holder);
        return holder;
    }

    /** Carga (o recarga en su sitio) el módulo Labor embebido en un holder. */
    private void loadLaborIntoHolder(VBox holder) {
        // Solo mostrar "Cargando…" en la primera carga; en los refrescos se
        // mantiene el contenido anterior hasta que llega el nuevo (sin parpadeo).
        if (holder.getChildren().isEmpty()) {
            Label loading = new Label(t("panorama.loading"));
            loading.getStyleClass().add("settings-hint");
            holder.getChildren().add(loading);
        }
        Task<LaborBundle> task = new Task<>() {
            @Override
            protected LaborBundle call() throws Exception {
                var employees = laborApiClient.listEmployees(true);
                var contracts = laborApiClient.listContracts(null);
                int year = java.time.LocalDate.now().getYear();
                var payslips = laborApiClient.listPayslips(year, null, null);
                java.util.List<com.benjagest.ui.model.TimeClockEventTypeEntry> evTypes;
                try { evTypes = laborApiClient.listTimeClockEventTypes(true); }
                catch (Exception ex) { evTypes = java.util.List.of(); }
                return new LaborBundle(employees, contracts, payslips, evTypes, year);
            }
        };
        task.setOnSucceeded(ev ->
                holder.getChildren().setAll(scroll(laborView(task.getValue()))));
        task.setOnFailed(ev ->
                holder.getChildren().setAll(errorPanel(t("labor.load_failed"))));
        start(task, "client-labor-full");
    }

    /** Helper genérico para añadir columnas con un getter String. */
    private <T> void addCol(javafx.scene.control.TableView<T> table, String header,
                              java.util.function.Function<T, String> getter, double width) {
        javafx.scene.control.TableColumn<T, String> c = new javafx.scene.control.TableColumn<>(header);
        c.setPrefWidth(width);
        c.setCellValueFactory(cd -> new javafx.beans.property.SimpleStringProperty(getter.apply(cd.getValue())));
        table.getColumns().add(c);
    }

    /**
     * VG-FULL-SCAN-2 — Variante de {@link #addCol} con comparador de
     * ordenacion para columnas numericas (importes) o de fecha. Sin
     * esto JavaFX ordena como texto y "10" cae antes de "9".
     */
    private <T> void addColSorted(javafx.scene.control.TableView<T> table, String header,
                                    java.util.function.Function<T, String> getter, double width,
                                    java.util.Comparator<String> comparator) {
        javafx.scene.control.TableColumn<T, String> c = new javafx.scene.control.TableColumn<>(header);
        c.setPrefWidth(width);
        c.setCellValueFactory(cd -> new javafx.beans.property.SimpleStringProperty(getter.apply(cd.getValue())));
        c.setComparator(comparator);
        table.getColumns().add(c);
    }

