    private void showScheduleTemplateDialog(
            com.benjagest.ui.model.ScheduleTemplateEntry existing, Runnable onSaved) {
        Dialog<Void> dialog = new Dialog<>();
        dialog.setTitle(existing == null ? t("labor.schedule.new") : t("labor.schedule.edit"));
        dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK, ButtonType.CANCEL);

        TextField name = new TextField(existing == null ? "" : existing.name());
        TextField desc = new TextField(existing == null ? "" : existing.description());
        CheckBox active = new CheckBox(t("labor.schedule.col.active"));
        active.setSelected(existing == null || existing.active());

        javafx.scene.layout.GridPane gp = new javafx.scene.layout.GridPane();
        gp.setHgap(8); gp.setVgap(8); gp.setPadding(new Insets(12));
        gp.add(new Label(t("labor.schedule.col.name")), 0, 0); gp.add(name, 1, 0);
        gp.add(new Label(t("labor.schedule.col.description")), 0, 1); gp.add(desc, 1, 1);
        if (existing != null) gp.add(active, 1, 2);
        dialog.getDialogPane().setContent(gp);

        dialog.setResultConverter(bt -> {
            if (bt != ButtonType.OK) return null;
            if (name.getText() == null || name.getText().isBlank()) {
                showError(t("labor.schedule.fail.title"), t("labor.schedule.name.required"));
                return null;
            }
            Task<Void> task = new Task<>() {
                @Override protected Void call() throws Exception {
                    if (existing == null) {
                        laborApiClient.createScheduleTemplate(name.getText().trim(), desc.getText());
                    } else {
                        laborApiClient.updateScheduleTemplate(existing.id(), name.getText().trim(),
                                desc.getText(), active.isSelected());
                    }
                    return null;
                }
            };
            task.setOnSucceeded(ev -> { toast(t("labor.schedule.saved")); onSaved.run(); });
            task.setOnFailed(ev -> showError(t("labor.schedule.fail.title"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "schedule-save");
            return null;
        });
        dialog.showAndWait();
    }

    private void showScheduleBlocksDialog(
            com.benjagest.ui.model.ScheduleTemplateEntry template, Runnable onSaved) {
        Dialog<Void> dialog = new Dialog<>();
        dialog.setTitle(t("labor.schedule.blocks") + " — " + template.name());
        dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK, ButtonType.CANCEL);
        dialog.getDialogPane().setPrefWidth(640);

        Label hint = new Label(t("labor.schedule.blocks.hint"));
        hint.setWrapText(true); hint.getStyleClass().add("settings-hint");

        // Todos los bloques (todos los días) en memoria; se guardan al Aceptar.
        final javafx.collections.ObservableList<com.benjagest.ui.model.ScheduleBlockEntry> all =
                FXCollections.observableArrayList();
        final int[] selDay = {1};

        // --- Selector de día (Lun..Dom) con contador de bloques por día ---
        javafx.scene.control.ToggleGroup tg = new javafx.scene.control.ToggleGroup();
        javafx.scene.control.ToggleButton[] dayBtns = new javafx.scene.control.ToggleButton[8];
        HBox dayBar = new HBox(6);
        dayBar.setAlignment(Pos.CENTER_LEFT);

        // --- Tabla SOLO del día seleccionado ---
        final javafx.collections.ObservableList<com.benjagest.ui.model.ScheduleBlockEntry> dayRows =
                FXCollections.observableArrayList();
        TableView<com.benjagest.ui.model.ScheduleBlockEntry> table = new TableView<>(dayRows);
        table.getStyleClass().add("data-table");
        table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        table.setPrefHeight(200);
        table.setPlaceholder(new Label(t("labor.schedule.day.empty")));
        TableColumn<com.benjagest.ui.model.ScheduleBlockEntry, String> tc =
                new TableColumn<>(t("labor.schedule.col.type"));
        tc.setCellValueFactory(c -> new SimpleStringProperty(
                "BREAK".equals(c.getValue().blockType()) ? t("labor.schedule.type.break")
                        : t("labor.schedule.type.work")));
        TableColumn<com.benjagest.ui.model.ScheduleBlockEntry, String> sc =
                new TableColumn<>(t("labor.workdays.col.in"));
        sc.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().startTime()));
        TableColumn<com.benjagest.ui.model.ScheduleBlockEntry, String> ec =
                new TableColumn<>(t("labor.workdays.col.out"));
        ec.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().endTime()));
        table.getColumns().addAll(java.util.List.of(tc, sc, ec));

        // --- Formulario de añadir bloque al día seleccionado ---
        ComboBox<String> type = new ComboBox<>(FXCollections.observableArrayList("WORK", "BREAK"));
        type.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(String s) {
                return "BREAK".equals(s) ? t("labor.schedule.type.break") : t("labor.schedule.type.work");
            }
            @Override public String fromString(String s) { return null; }
        });
        type.getSelectionModel().selectFirst();
        type.setPrefWidth(150);
        TextField start = new TextField(); start.setPromptText("09:00"); start.setPrefWidth(80);
        TextField end = new TextField(); end.setPromptText("14:00"); end.setPrefWidth(80);
        com.benjagest.ui.support.EditableCells.installTimeMask(start);
        com.benjagest.ui.support.EditableCells.installTimeMask(end);

        java.util.Comparator<com.benjagest.ui.model.ScheduleBlockEntry> byStart =
                java.util.Comparator.comparing(com.benjagest.ui.model.ScheduleBlockEntry::startTime);

        Runnable refreshDay = () -> {
            dayRows.setAll(all.stream().filter(b -> b.weekday() == selDay[0]).sorted(byStart).toList());
            for (int d = 1; d <= 7; d++) {
                final int dd = d;
                long c = all.stream().filter(b -> b.weekday() == dd).count();
                dayBtns[d].setText(weekdayName(d) + (c > 0 ? " (" + c + ")" : ""));
            }
            // Pre-rellena la entrada del siguiente bloque con la salida del último (contiguo).
            start.setText(dayRows.isEmpty() ? "09:00" : dayRows.get(dayRows.size() - 1).endTime());
            end.clear();
        };

        for (int d = 1; d <= 7; d++) {
            javafx.scene.control.ToggleButton tb = new javafx.scene.control.ToggleButton(weekdayName(d));
            tb.setToggleGroup(tg);
            final int dd = d;
            tb.setOnAction(e -> { if (tb.isSelected()) { selDay[0] = dd; refreshDay.run(); } });
            dayBtns[d] = tb;
            dayBar.getChildren().add(tb);
        }
        dayBtns[1].setSelected(true);

        Button addRow = new Button(t("labor.schedule.block.add"));
        addRow.setGraphic(icon("fas-plus"));
        addRow.getStyleClass().add("primary-button");
        addRow.setOnAction(e -> {
            if (!isHhmm(start.getText()) || !isHhmm(end.getText())) {
                showError(t("labor.schedule.fail.title"), t("labor.schedule.time.invalid"));
                return;
            }
            java.time.LocalTime s = java.time.LocalTime.parse(start.getText().trim());
            java.time.LocalTime en = java.time.LocalTime.parse(end.getText().trim());
            if (!en.isAfter(s)) {
                showError(t("labor.schedule.fail.title"), t("labor.schedule.block.order"));
                return;
            }
            for (var b : dayRows) {
                if (s.isBefore(java.time.LocalTime.parse(b.endTime()))
                        && java.time.LocalTime.parse(b.startTime()).isBefore(en)) {
                    showError(t("labor.schedule.fail.title"), t("labor.schedule.block.overlap"));
                    return;
                }
            }
            all.add(new com.benjagest.ui.model.ScheduleBlockEntry(
                    null, selDay[0], type.getValue(), start.getText().trim(), end.getText().trim()));
            refreshDay.run();
        });
        Button delRow = new Button(t("labor.schedule.block.remove"));
        delRow.setGraphic(icon("fas-trash"));
        delRow.setOnAction(e -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel != null) { all.remove(sel); refreshDay.run(); }
        });
        HBox form = new HBox(8,
                formLabel("labor.schedule.col.type"), type,
                formLabel("labor.workdays.col.in"), start,
                formLabel("labor.workdays.col.out"), end, addRow, delRow);
        form.setAlignment(Pos.CENTER_LEFT);

        // --- Acciones de día: copiar a otros días / vaciar ---
        Button copyBtn = new Button(t("labor.schedule.copy_days"));
        copyBtn.setGraphic(icon("fas-copy"));
        copyBtn.setOnAction(e -> {
            if (dayRows.isEmpty()) { showInfo(t("labor.schedule.copy_days"), t("labor.schedule.no_blocks")); return; }
            Dialog<Void> cd = new Dialog<>();
            cd.setTitle(t("labor.schedule.copy_days"));
            cd.getDialogPane().getButtonTypes().addAll(ButtonType.OK, ButtonType.CANCEL);
            Label ch = new Label(t("labor.schedule.copy_days.hint")
                    .replace("{day}", weekdayName(selDay[0])));
            ch.setWrapText(true); ch.getStyleClass().add("settings-hint");
            VBox checks = new VBox(6);
            java.util.List<CheckBox> cbs = new java.util.ArrayList<>();
            for (int d = 1; d <= 7; d++) {
                if (d == selDay[0]) continue;
                CheckBox cb = new CheckBox(weekdayName(d));
                cb.setUserData(d);
                cbs.add(cb);
                checks.getChildren().add(cb);
            }
            VBox cbox = new VBox(10, ch, checks);
            cbox.setPadding(new Insets(12));
            cd.getDialogPane().setContent(cbox);
            cd.setResultConverter(bt -> {
                if (bt != ButtonType.OK) return null;
                java.util.List<com.benjagest.ui.model.ScheduleBlockEntry> src =
                        new java.util.ArrayList<>(dayRows);
                for (CheckBox cb : cbs) {
                    if (!cb.isSelected()) continue;
                    int dd = (Integer) cb.getUserData();
                    all.removeIf(b -> b.weekday() == dd);
                    for (var b : src) {
                        all.add(new com.benjagest.ui.model.ScheduleBlockEntry(
                                null, dd, b.blockType(), b.startTime(), b.endTime()));
                    }
                }
                refreshDay.run();
                return null;
            });
            cd.showAndWait();
        });
        Button clearBtn = new Button(t("labor.schedule.clear_day"));
        clearBtn.setGraphic(icon("fas-eraser"));
        clearBtn.setOnAction(e -> {
            all.removeIf(b -> b.weekday() == selDay[0]);
            refreshDay.run();
        });
        HBox dayActions = new HBox(8, copyBtn, clearBtn);
        dayActions.setAlignment(Pos.CENTER_LEFT);

        Label dayLbl = new Label(t("labor.schedule.day") + ":");
        dayLbl.setMinWidth(javafx.scene.layout.Region.USE_PREF_SIZE);
        HBox dayRow = new HBox(8, dayLbl, dayBar);
        dayRow.setAlignment(Pos.CENTER_LEFT);
        VBox box = new VBox(10, hint, dayRow, table, form, dayActions);
        box.setPadding(new Insets(12));
        dialog.getDialogPane().setContent(box);

        // Carga inicial de los bloques existentes.
        Task<java.util.List<com.benjagest.ui.model.ScheduleBlockEntry>> load = new Task<>() {
            @Override protected java.util.List<com.benjagest.ui.model.ScheduleBlockEntry> call() throws Exception {
                return laborApiClient.getScheduleBlocks(template.id());
            }
        };
        load.setOnSucceeded(ev -> { all.setAll(load.getValue()); refreshDay.run(); });
        load.setOnFailed(ev -> showError(t("labor.schedule.fail.title"),
                load.getException() == null ? "" : load.getException().getMessage()));
        start(load, "schedule-blocks-load");
        refreshDay.run();

        dialog.setResultConverter(bt -> {
            if (bt != ButtonType.OK) return null;
            java.util.List<com.benjagest.ui.model.ScheduleBlockEntry> snapshot =
                    new java.util.ArrayList<>(all);
            Task<Void> task = new Task<>() {
                @Override protected Void call() throws Exception {
                    laborApiClient.replaceScheduleBlocks(template.id(), snapshot);
                    return null;
                }
            };
            task.setOnSucceeded(ev -> { toast(t("labor.schedule.saved")); onSaved.run(); });
            task.setOnFailed(ev -> showError(t("labor.schedule.fail.title"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "schedule-blocks-save");
            return null;
        });
        dialog.showAndWait();
    }

    private void showScheduleAssignDialog(
            com.benjagest.ui.model.ScheduleTemplateEntry template,
            java.util.List<com.benjagest.ui.model.EmployeeEntry> employees, Runnable onSaved) {
        Dialog<Void> dialog = new Dialog<>();
        dialog.setTitle(t("labor.schedule.assign") + " — " + template.name());
        dialog.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);
        dialog.getDialogPane().setPrefWidth(660);

        javafx.collections.ObservableList<com.benjagest.ui.model.ScheduleAssignmentEntry> rows =
                FXCollections.observableArrayList();
        TableView<com.benjagest.ui.model.ScheduleAssignmentEntry> table = new TableView<>(rows);
        table.getStyleClass().add("data-table");
        table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        table.setPrefHeight(200);
        TableColumn<com.benjagest.ui.model.ScheduleAssignmentEntry, String> ec =
                new TableColumn<>(t("labor.shifts.col.employee"));
        ec.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().employeeName()));
        TableColumn<com.benjagest.ui.model.ScheduleAssignmentEntry, String> fc =
                new TableColumn<>(t("labor.schedule.col.from"));
        fc.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().effectiveFrom()));
        fc.setPrefWidth(110);
        TableColumn<com.benjagest.ui.model.ScheduleAssignmentEntry, String> toc =
                new TableColumn<>(t("labor.schedule.col.to"));
        toc.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().effectiveTo() == null || c.getValue().effectiveTo().isBlank()
                        ? "—" : c.getValue().effectiveTo()));
        toc.setPrefWidth(110);
        table.getColumns().addAll(java.util.List.of(ec, fc, toc));

        Runnable reloadAssign = () -> {
            Task<java.util.List<com.benjagest.ui.model.ScheduleAssignmentEntry>> task = new Task<>() {
                @Override protected java.util.List<com.benjagest.ui.model.ScheduleAssignmentEntry> call() throws Exception {
                    return laborApiClient.listScheduleAssignments(template.id());
                }
            };
            task.setOnSucceeded(ev -> rows.setAll(task.getValue()));
            task.setOnFailed(ev -> showError(t("labor.schedule.fail.title"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "schedule-assign-load");
        };

        ComboBox<com.benjagest.ui.model.EmployeeEntry> empCombo =
                new ComboBox<>(FXCollections.observableArrayList(employees));
        empCombo.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(com.benjagest.ui.model.EmployeeEntry e) {
                return e == null ? "" : e.fullName();
            }
            @Override public com.benjagest.ui.model.EmployeeEntry fromString(String s) { return null; }
        });
        empCombo.setPrefWidth(190);
        DatePicker fromP = new DatePicker(java.time.LocalDate.now());
        DatePicker toP = new DatePicker();
        fromP.setPrefWidth(130);
        toP.setPrefWidth(130);
        com.benjagest.ui.support.EditableCells.installFlexibleConverter(fromP);
        com.benjagest.ui.support.EditableCells.installFlexibleConverter(toP);
        Button addBtn = new Button(t("labor.schedule.assign.add"));
        addBtn.getStyleClass().add("primary-button");
        addBtn.setGraphic(icon("fas-plus"));
        addBtn.setOnAction(e -> {
            var emp = empCombo.getValue();
            if (emp == null) { showError(t("labor.schedule.fail.title"), t("labor.schedule.employee.required")); return; }
            Task<Void> task = new Task<>() {
                @Override protected Void call() throws Exception {
                    laborApiClient.assignSchedule(template.id(), emp.id(), fromP.getValue(), toP.getValue());
                    return null;
                }
            };
            task.setOnSucceeded(ev -> { toast(t("labor.schedule.saved")); reloadAssign.run(); onSaved.run(); });
            task.setOnFailed(ev -> showError(t("labor.schedule.fail.title"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "schedule-assign-add");
        });
        Button removeBtn = new Button(t("labor.schedule.assign.remove"));
        removeBtn.setGraphic(icon("fas-trash"));
        removeBtn.setOnAction(e -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null) return;
            Task<Void> task = new Task<>() {
                @Override protected Void call() throws Exception {
                    laborApiClient.removeScheduleAssignment(sel.id());
                    return null;
                }
            };
            task.setOnSucceeded(ev -> { toast(t("labor.schedule.deleted")); reloadAssign.run(); onSaved.run(); });
            task.setOnFailed(ev -> showError(t("labor.schedule.fail.title"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "schedule-assign-remove");
        });

        HBox form = new HBox(8, empCombo,
                formLabel("labor.schedule.col.from"), fromP,
                formLabel("labor.schedule.col.to"), toP, addBtn, removeBtn);
        form.setAlignment(Pos.CENTER_LEFT);
        VBox box = new VBox(10, table, form);
        box.setPadding(new Insets(12));
        dialog.getDialogPane().setContent(box);

        reloadAssign.run();
        dialog.showAndWait();
    }

    private String weekdayName(int wd) {
        return switch (wd) {
            case 1 -> t("weekday.mon");
            case 2 -> t("weekday.tue");
            case 3 -> t("weekday.wed");
            case 4 -> t("weekday.thu");
            case 5 -> t("weekday.fri");
            case 6 -> t("weekday.sat");
            case 7 -> t("weekday.sun");
            default -> String.valueOf(wd);
        };
    }

    private boolean isHhmm(String s) {
        return s != null && s.trim().matches("([01]?\\d|2[0-3]):[0-5]\\d");
    }

    private void openShiftCreateDialog(
            java.util.List<com.benjagest.ui.model.EmployeeEntry> employees,
            Runnable onSaved) {
        Dialog<Void> dialog = new Dialog<>();
        dialog.setTitle(t("labor.shifts.add"));
        dialog.setHeaderText(t("labor.shifts.add.header"));

        ComboBox<com.benjagest.ui.model.EmployeeEntry> empCombo =
                new ComboBox<>(FXCollections.observableArrayList(employees));
        empCombo.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(com.benjagest.ui.model.EmployeeEntry e) {
                return e == null ? "" : e.fullName();
            }
            @Override public com.benjagest.ui.model.EmployeeEntry fromString(String s) { return null; }
        });
        DatePicker dateP = new DatePicker(java.time.LocalDate.now());
        com.benjagest.ui.support.EditableCells.installFlexibleConverter(dateP);
        TextField minutes = new TextField("0");
        TextField desc = new TextField();
        desc.setPromptText(t("labor.shifts.add.desc_prompt"));
        CheckBox billable = new CheckBox(t("labor.shifts.col.billable"));
        TextField amount = new TextField();
        amount.setPromptText(t("labor.shifts.add.amount_prompt"));

        VBox form = new VBox(8,
                new Label(t("labor.shifts.col.employee")), empCombo,
                new Label(t("labor.shifts.col.date")), dateP,
                new Label(t("labor.shifts.col.minutes")), minutes,
                new Label(t("labor.shifts.col.description")), desc,
                billable,
                new Label(t("labor.shifts.col.amount")), amount);
        form.setPadding(new Insets(16));
        form.setPrefWidth(400);
        dialog.getDialogPane().setContent(form);
        dialog.getDialogPane().getButtonTypes().addAll(
                javafx.scene.control.ButtonType.CANCEL, javafx.scene.control.ButtonType.OK);

        dialog.setResultConverter(bt -> {
            if (bt == javafx.scene.control.ButtonType.OK) {
                if (empCombo.getValue() == null || dateP.getValue() == null) {
                    showError(t("labor.shifts.fail.title"), t("labor.shifts.add.missing"));
                    return null;
                }
                int mins;
                java.math.BigDecimal amt = null;
                try {
                    mins = Integer.parseInt(minutes.getText().trim());
                    if (amount.getText() != null && !amount.getText().isBlank()) {
                        amt = new java.math.BigDecimal(amount.getText().trim());
                    }
                } catch (NumberFormatException ex) {
                    showError(t("labor.shifts.fail.title"), t("labor.shifts.add.invalid"));
                    return null;
                }
                final java.math.BigDecimal amtFinal = amt;
                final int minsFinal = mins;
                Task<Void> t = new Task<>() {
                    @Override protected Void call() throws Exception {
                        altaApiClient.createWorkLog(new com.benjagest.ui.model.WorkLogEntry(
                                null, empCombo.getValue().id(), null,
                                dateP.getValue().toString(), minsFinal,
                                null, null, desc.getText(), billable.isSelected(),
                                null, null, null, amtFinal, "DRAFT", null));
                        return null;
                    }
                };
                t.setOnSucceeded(s -> onSaved.run());
                t.setOnFailed(s -> showError(t("labor.shifts.fail.title"),
                        t.getException() == null ? "" : t.getException().getMessage()));
                start(t, "shifts-create");
            }
            return null;
        });
        dialog.showAndWait();
    }

    // ============================================================
    //  L2-IT — Bajas médicas (Incapacidad Temporal)
    // ============================================================
    //
    //  Pestaña del módulo Labor con CRUD de bajas. Backend cerrado en
    //  sesión 2026-06-09 (`labor.leaves.MedicalLeaveService`), UI
    //  pendiente — añadida en sesión autónoma 2026-06-09.
    //
    //  Patrón mínimo: tabla (período, empleado, tipo, estado) + botones
    //  Nueva/Editar/Eliminar + diálogo formulario. Sin filtros por ahora.
    //  Pendientes futuros: filtro por empleado, exportable, vinculo con
    //  cálculo nómina.
    //
    //  i18n: keys "labor.leaves.*" en ambos idiomas.
    private Node buildMedicalLeavesTab(
            java.util.List<com.benjagest.ui.model.EmployeeEntry> employees) {
        VBox content = new VBox(12);
        content.setPadding(new Insets(16));

        java.util.Map<String, String> empById = new java.util.HashMap<>();
        for (var e : employees) empById.put(e.id(), e.fullName());

        Label hint = new Label(t("labor.leaves.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        TableView<com.benjagest.ui.model.MedicalLeaveEntry> table = new TableView<>();
        table.getStyleClass().add("data-table");
        table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        table.setPlaceholder(new Label(t("labor.leaves.placeholder.empty")));
        com.benjagest.ui.support.TableSelectionHelper.install(table);

        TableColumn<com.benjagest.ui.model.MedicalLeaveEntry, String> cEmp =
                new TableColumn<>(t("labor.leaves.col.employee"));
        cEmp.setCellValueFactory(c -> new SimpleStringProperty(
                empById.getOrDefault(c.getValue().employeeId(),
                        shortId(c.getValue().employeeId()))));
        cEmp.setPrefWidth(180);

        TableColumn<com.benjagest.ui.model.MedicalLeaveEntry, String> cType =
                new TableColumn<>(t("labor.leaves.col.type"));
        cType.setCellValueFactory(c -> new SimpleStringProperty(
                t("labor.leaves.type." + c.getValue().leaveType())));
        cType.setPrefWidth(180);

        TableColumn<com.benjagest.ui.model.MedicalLeaveEntry, String> cStart =
                new TableColumn<>(t("labor.leaves.col.start"));
        cStart.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().startDate() == null ? "" : c.getValue().startDate().toString()));
        cStart.setPrefWidth(110);
        cStart.setComparator(ISO_DATE_COMPARATOR);

        TableColumn<com.benjagest.ui.model.MedicalLeaveEntry, String> cEnd =
                new TableColumn<>(t("labor.leaves.col.end"));
        cEnd.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().endDate() == null ? "" : c.getValue().endDate().toString()));
        cEnd.setPrefWidth(110);
        cEnd.setComparator(ISO_DATE_COMPARATOR);

        TableColumn<com.benjagest.ui.model.MedicalLeaveEntry, String> cStatus =
                new TableColumn<>(t("labor.leaves.col.status"));
        cStatus.setCellValueFactory(c -> new SimpleStringProperty(
                t("labor.leaves.status." + c.getValue().status())));
        cStatus.setPrefWidth(100);

        TableColumn<com.benjagest.ui.model.MedicalLeaveEntry, String> cNotes =
                new TableColumn<>(t("labor.leaves.col.notes"));
        cNotes.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().notes() == null ? "" : c.getValue().notes()));

        table.getColumns().addAll(java.util.List.of(cEmp, cType, cStart, cEnd, cStatus, cNotes));

        Runnable reload = () -> {
            Task<java.util.List<com.benjagest.ui.model.MedicalLeaveEntry>> t = new Task<>() {
                @Override protected java.util.List<com.benjagest.ui.model.MedicalLeaveEntry> call()
                        throws Exception {
                    return altaApiClient.listMedicalLeaves(null);
                }
            };
            t.setOnSucceeded(ev -> table.setItems(
                    FXCollections.observableArrayList(t.getValue())));
            t.setOnFailed(ev -> showError(t("labor.leaves.load_failed"),
                    t.getException() == null ? "" : t.getException().getMessage()));
            start(t, "labor-leaves-load");
        };
        reload.run();

        Button newBtn = new Button(t("labor.leaves.btn.new"));
        newBtn.setGraphic(icon("fas-plus"));
        newBtn.getStyleClass().add("primary-button");
        newBtn.setOnAction(ev -> openMedicalLeaveDialog(null, employees, reload));

        Button editBtn = new Button(t("labor.leaves.btn.edit"));
        editBtn.setGraphic(icon("fas-pen"));
        editBtn.setDisable(true);
        editBtn.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel != null) openMedicalLeaveDialog(sel, employees, reload);
        });

        Button delBtn = new Button(t("labor.leaves.btn.delete"));
        delBtn.setGraphic(icon("fas-trash"));
        delBtn.setDisable(true);
        delBtn.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null) return;
            Alert confirm = new Alert(Alert.AlertType.CONFIRMATION);
            confirm.setTitle(t("labor.leaves.confirm.delete.title"));
            confirm.setHeaderText(t("labor.leaves.confirm.delete.body"));
            confirm.showAndWait().ifPresent(rsp -> {
                if (rsp == javafx.scene.control.ButtonType.OK) {
                    Task<Void> del = new Task<>() {
                        @Override protected Void call() throws Exception {
                            altaApiClient.deleteMedicalLeave(sel.id());
                            return null;
                        }
                    };
                    del.setOnSucceeded(s -> reload.run());
                    del.setOnFailed(s -> showError(t("labor.leaves.delete_failed"),
                            del.getException() == null ? "" : del.getException().getMessage()));
                    start(del, "labor-leaves-delete");
                }
            });
        });

        table.getSelectionModel().selectedItemProperty().addListener((obs, oldV, newV) -> {
            boolean has = newV != null;
            editBtn.setDisable(!has);
            delBtn.setDisable(!has);
        });

        HBox actions = new HBox(8, newBtn, editBtn, delBtn);
        VBox.setVgrow(table, Priority.ALWAYS);
        content.getChildren().addAll(hint, table, actions);
        return content;
    }

    /** Diálogo formulario para nueva/editar baja médica. */
    private void openMedicalLeaveDialog(
            com.benjagest.ui.model.MedicalLeaveEntry existing,
            java.util.List<com.benjagest.ui.model.EmployeeEntry> employees,
            Runnable onSuccess) {
        Dialog<javafx.scene.control.ButtonType> dlg = new Dialog<>();
        dlg.setTitle(existing == null
                ? t("labor.leaves.editor.title_new")
                : t("labor.leaves.editor.title_edit"));
        dlg.getDialogPane().getButtonTypes().addAll(
                javafx.scene.control.ButtonType.OK,
                javafx.scene.control.ButtonType.CANCEL);

        GridPane grid = new GridPane();
        grid.setHgap(10);
        grid.setVgap(10);
        grid.setPadding(new Insets(16));

        ComboBox<com.benjagest.ui.model.EmployeeEntry> empCombo = new ComboBox<>();
        empCombo.getItems().addAll(employees);
        empCombo.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(com.benjagest.ui.model.EmployeeEntry e) {
                return e == null ? "" : e.fullName();
            }
            @Override public com.benjagest.ui.model.EmployeeEntry fromString(String s) { return null; }
        });
        if (existing != null) {
            for (var e : employees) if (e.id().equals(existing.employeeId())) empCombo.setValue(e);
            empCombo.setDisable(true);
        }

        ComboBox<String> typeCombo = new ComboBox<>();
        typeCombo.getItems().addAll(
                com.benjagest.ui.model.MedicalLeaveEntry.TYPE_COMMON_DISEASE,
                com.benjagest.ui.model.MedicalLeaveEntry.TYPE_WORK_ACCIDENT,
                com.benjagest.ui.model.MedicalLeaveEntry.TYPE_MATERNITY,
                com.benjagest.ui.model.MedicalLeaveEntry.TYPE_PATERNITY,
                com.benjagest.ui.model.MedicalLeaveEntry.TYPE_OTHER);
        typeCombo.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(String s) {
                return s == null ? "" : t("labor.leaves.type." + s);
            }
            @Override public String fromString(String s) { return s; }
        });
        typeCombo.setValue(existing == null
                ? com.benjagest.ui.model.MedicalLeaveEntry.TYPE_COMMON_DISEASE
                : existing.leaveType());

        DatePicker startPicker = new DatePicker(
                existing == null ? java.time.LocalDate.now() : existing.startDate());
        DatePicker endPicker = new DatePicker(
                existing == null ? null : existing.endDate());
        com.benjagest.ui.support.EditableCells.installFlexibleConverter(startPicker);
        com.benjagest.ui.support.EditableCells.installFlexibleConverter(endPicker);

        ComboBox<String> statusCombo = new ComboBox<>();
        statusCombo.getItems().addAll(
                com.benjagest.ui.model.MedicalLeaveEntry.STATUS_OPEN,
                com.benjagest.ui.model.MedicalLeaveEntry.STATUS_CLOSED,
                com.benjagest.ui.model.MedicalLeaveEntry.STATUS_DRAFT);
        statusCombo.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(String s) {
                return s == null ? "" : t("labor.leaves.status." + s);
            }
            @Override public String fromString(String s) { return s; }
        });
        statusCombo.setValue(existing == null
                ? com.benjagest.ui.model.MedicalLeaveEntry.STATUS_OPEN
                : existing.status());

        TextArea notesArea = new TextArea(existing == null ? "" : existing.notes());
        notesArea.setPrefRowCount(3);
        notesArea.setWrapText(true);

        int r = 0;
        grid.addRow(r++, new Label(t("labor.leaves.field.employee")), empCombo);
        grid.addRow(r++, new Label(t("labor.leaves.field.type")), typeCombo);
        grid.addRow(r++, new Label(t("labor.leaves.field.start")), startPicker);
        grid.addRow(r++, new Label(t("labor.leaves.field.end")), endPicker);
        grid.addRow(r++, new Label(t("labor.leaves.field.status")), statusCombo);
        grid.addRow(r++, new Label(t("labor.leaves.field.notes")), notesArea);

        dlg.getDialogPane().setContent(grid);
        dlg.showAndWait().ifPresent(rsp -> {
            if (rsp != javafx.scene.control.ButtonType.OK) return;
            if (empCombo.getValue() == null) {
                showError(t("labor.leaves.error"), t("labor.leaves.error.no_employee"));
                return;
            }
            if (startPicker.getValue() == null) {
                showError(t("labor.leaves.error"), t("labor.leaves.error.no_start"));
                return;
            }
            // Auto-status si el usuario no toca el combo:
            // - OPEN si no hay endDate
            // - CLOSED si hay endDate
            String status = statusCombo.getValue();
            if (status == null) {
                status = endPicker.getValue() != null
                        ? com.benjagest.ui.model.MedicalLeaveEntry.STATUS_CLOSED
                        : com.benjagest.ui.model.MedicalLeaveEntry.STATUS_OPEN;
            }
            String notes = notesArea.getText() == null || notesArea.getText().isBlank()
                    ? null : notesArea.getText().trim();
            final String finalStatus = status;
            Task<Void> save = new Task<>() {
                @Override protected Void call() throws Exception {
                    if (existing == null) {
                        altaApiClient.createMedicalLeave(
                                empCombo.getValue().id(),
                                typeCombo.getValue(),
                                startPicker.getValue(),
                                endPicker.getValue(),
                                finalStatus,
                                notes);
                    } else {
                        altaApiClient.updateMedicalLeave(
                                existing.id(),
                                typeCombo.getValue(),
                                startPicker.getValue(),
                                endPicker.getValue(),
                                finalStatus,
                                notes);
                    }
                    return null;
                }
            };
            save.setOnSucceeded(s -> onSuccess.run());
            save.setOnFailed(s -> showError(t("labor.leaves.save_failed"),
                    save.getException() == null ? "" : save.getException().getMessage()));
            start(save, "labor-leaves-save");
        });
    }

    // ============================================================
    //  L2-SS — Cotizaciones Seguridad Social (TC1 / sistema RED)
    // ============================================================
    //
    //  Listado solo-lectura. Las cuotas se calculan desde las nóminas;
    //  el editor manual NO es prioritario (lo que querría editar el
    //  usuario es la nómina, no la cuota individual).
    //
    //  Patrón: filtros Año + Mes + Empleado al cabezal + tabla con
    //  período, empleado/empresa, tipo, base, cuota, estado. Botón
    //  Eliminar solo activo para DRAFT (backend bloquea DELETE si
    //  !=DRAFT vía 409).
    /**
     * Tipos de cotización a la Seguridad Social por año (PARAM-YEAR). El
     * cálculo de nóminas los lee de aquí; al cambiar la ley solo hay que
     * añadir/editar el año, sin tocar código.
     */
    private Node buildSsRatesTab() {
        VBox content = new VBox(12);
        content.setPadding(new Insets(16));
        Label hint = new Label(t("labor.ssrates.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        TableView<com.benjagest.ui.model.SsRateEntry> table = new TableView<>();
        table.getStyleClass().add("data-table");
        table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        table.setPlaceholder(new Label(t("labor.ssrates.empty")));
        com.benjagest.ui.support.TableSelectionHelper.install(table);

        addColSorted(table, t("labor.ssrates.col.year"), r -> String.valueOf(r.year()), 60, NUMERIC_STRING_COMPARATOR);
        addColSorted(table, "Trab. CC", r -> pctTxt(r.eeCommon()), 80, NUMERIC_STRING_COMPARATOR);
        addColSorted(table, "Trab. Desempleo", r -> pctTxt(r.eeUnemployment()), 110, NUMERIC_STRING_COMPARATOR);
        addColSorted(table, "Trab. Form.", r -> pctTxt(r.eeTraining()), 80, NUMERIC_STRING_COMPARATOR);
        addColSorted(table, "Trab. MEI", r -> pctTxt(r.eeMei()), 75, NUMERIC_STRING_COMPARATOR);
        addColSorted(table, "Emp. CC", r -> pctTxt(r.erCommon()), 80, NUMERIC_STRING_COMPARATOR);
        addColSorted(table, "Emp. Desempleo", r -> pctTxt(r.erUnemployment()), 110, NUMERIC_STRING_COMPARATOR);
        addColSorted(table, "Emp. FOGASA", r -> pctTxt(r.erFogasa()), 90, NUMERIC_STRING_COMPARATOR);
        addColSorted(table, "Emp. Form.", r -> pctTxt(r.erTraining()), 80, NUMERIC_STRING_COMPARATOR);
        addColSorted(table, "Emp. MEI", r -> pctTxt(r.erMei()), 75, NUMERIC_STRING_COMPARATOR);
        addColSorted(table, "AT/EP def.", r -> pctTxt(r.defaultAtEp()), 80, NUMERIC_STRING_COMPARATOR);
        addColSorted(table, t("labor.ssrates.col.basemax"),
                r -> r.baseMaxMonthly() == null ? "" : money(r.baseMaxMonthly()), 100, NUMERIC_STRING_COMPARATOR);
        addColSorted(table, t("labor.ssrates.col.basemin"),
                r -> r.baseMinMonthly() == null ? "" : money(r.baseMinMonthly()), 100, NUMERIC_STRING_COMPARATOR);
        addColSorted(table, t("labor.ssrates.col.ref"),
                r -> r.legalReference() == null ? "" : r.legalReference(), 160, String.CASE_INSENSITIVE_ORDER);

        Runnable reload = () -> {
            Task<java.util.List<com.benjagest.ui.model.SsRateEntry>> tk = new Task<>() {
                @Override protected java.util.List<com.benjagest.ui.model.SsRateEntry> call() throws Exception {
                    return laborApiClient.listSsRates();
                }
            };
            tk.setOnSucceeded(ev -> table.setItems(FXCollections.observableArrayList(tk.getValue())));
            tk.setOnFailed(ev -> showError(t("labor.ssrates.load_failed"),
                    tk.getException() == null ? "" : tk.getException().getMessage()));
            start(tk, "ssrates-load");
        };

        Button addBtn = new Button(t("labor.ssrates.add"));
        addBtn.getStyleClass().add("button-primary");
        addBtn.setOnAction(e -> {
            // Copia del año más reciente como base para el siguiente.
            var items = table.getItems();
            com.benjagest.ui.model.SsRateEntry base = items.isEmpty() ? null : items.get(0);
            int nextYear = base == null ? java.time.Year.now().getValue() + 1 : base.year() + 1;
            showSsRateEditor(base, nextYear, reload);
        });
        Button editBtn = new Button(t("labor.ssrates.edit"));
        editBtn.getStyleClass().add("button-secondary");
        editBtn.setOnAction(e -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel != null) showSsRateEditor(sel, sel.year(), reload);
        });
        HBox actions = new HBox(8, addBtn, editBtn);

        reload.run();
        VBox body = new VBox(10, hint, actions, table);
        VBox.setVgrow(table, Priority.ALWAYS);
        content.getChildren().add(body);
        VBox.setVgrow(body, Priority.ALWAYS);
        return content;
    }

    private String pctTxt(java.math.BigDecimal v) {
        return v == null ? "" : v.toPlainString().replace(".", ",") + " %";
    }

    private void showSsRateEditor(com.benjagest.ui.model.SsRateEntry base, int year, Runnable onSaved) {
        Dialog<ButtonType> d = new Dialog<>();
        d.setTitle(t("labor.ssrates.edit") + " — " + year);
        ButtonType save = new ButtonType(t("labor.ssrates.save_btn"), ButtonBar.ButtonData.OK_DONE);
        d.getDialogPane().getButtonTypes().addAll(save, ButtonType.CANCEL);

        TextField yearF = new TextField(String.valueOf(year));
        TextField eeC = rateField(base == null ? null : base.eeCommon(), "4.70");
        TextField eeU = rateField(base == null ? null : base.eeUnemployment(), "1.55");
        TextField eeT = rateField(base == null ? null : base.eeTraining(), "0.10");
        TextField eeM = rateField(base == null ? null : base.eeMei(), "0.15");
        TextField erC = rateField(base == null ? null : base.erCommon(), "23.60");
        TextField erU = rateField(base == null ? null : base.erUnemployment(), "5.50");
        TextField erF = rateField(base == null ? null : base.erFogasa(), "0.20");
        TextField erT = rateField(base == null ? null : base.erTraining(), "0.60");
        TextField erM = rateField(base == null ? null : base.erMei(), "0.75");
        TextField atEp = rateField(base == null ? null : base.defaultAtEp(), "1.50");
        TextField baseMax = rateField(base == null ? null : base.baseMaxMonthly(), "5101.20");
        TextField baseMin = rateField(base == null ? null : base.baseMinMonthly(), "0");
        TextField ref = new TextField(base == null || base.legalReference() == null ? "" : base.legalReference());

        GridPane g = new GridPane();
        g.setHgap(10); g.setVgap(8); g.setPadding(new Insets(12));
        int r = 0;
        g.add(new Label(t("labor.ssrates.col.year")), 0, r); g.add(yearF, 1, r++);
        g.add(new Label("Trabajador — Cont. comunes"), 0, r); g.add(eeC, 1, r++);
        g.add(new Label("Trabajador — Desempleo"), 0, r); g.add(eeU, 1, r++);
        g.add(new Label("Trabajador — Formación"), 0, r); g.add(eeT, 1, r++);
        g.add(new Label("Trabajador — MEI"), 0, r); g.add(eeM, 1, r++);
        g.add(new Label("Empresa — Cont. comunes"), 0, r); g.add(erC, 1, r++);
        g.add(new Label("Empresa — Desempleo"), 0, r); g.add(erU, 1, r++);
        g.add(new Label("Empresa — FOGASA"), 0, r); g.add(erF, 1, r++);
        g.add(new Label("Empresa — Formación"), 0, r); g.add(erT, 1, r++);
        g.add(new Label("Empresa — MEI"), 0, r); g.add(erM, 1, r++);
        g.add(new Label("AT/EP por defecto"), 0, r); g.add(atEp, 1, r++);
        g.add(new Label(t("labor.ssrates.col.basemax")), 0, r); g.add(baseMax, 1, r++);
        g.add(new Label(t("labor.ssrates.col.basemin")), 0, r); g.add(baseMin, 1, r++);
        g.add(new Label(t("labor.ssrates.col.ref")), 0, r); g.add(ref, 1, r++);
        installDialog(d, g);

        d.showAndWait().ifPresent(bt -> {
            if (bt != save) return;
            com.benjagest.ui.model.SsRateEntry e = new com.benjagest.ui.model.SsRateEntry(
                    parseIntSafe(yearF.getText()) == null ? year : parseIntSafe(yearF.getText()),
                    parseDecSafe(eeC.getText()), parseDecSafe(eeU.getText()),
                    parseDecSafe(eeT.getText()), parseDecSafe(eeM.getText()),
                    parseDecSafe(erC.getText()), parseDecSafe(erU.getText()), parseDecSafe(erF.getText()),
                    parseDecSafe(erT.getText()), parseDecSafe(erM.getText()), parseDecSafe(atEp.getText()),
                    parseDecSafe(baseMax.getText()), parseDecSafe(baseMin.getText()),
                    blankToNullOrSelf(ref.getText()));
            Task<Void> tk = new Task<>() {
                @Override protected Void call() throws Exception { laborApiClient.upsertSsRate(e); return null; }
            };
            tk.setOnSucceeded(ev -> onSaved.run());
            tk.setOnFailed(ev -> showError(t("labor.ssrates.save_failed"),
                    tk.getException() == null ? "" : tk.getException().getMessage()));
            start(tk, "ssrates-save");
        });
    }

    private TextField rateField(java.math.BigDecimal v, String fallback) {
        return new TextField(v == null ? fallback : v.toPlainString());
    }

